const leituras = {"0:0":{"alias":"EJIOGBE","page":4,"phrase":"Baba Ejiogbe alalekun moni lekun, okó ayá lalá, omodú aboxun, omó eni ko xé ileké rixí kamu, ileké omó lorí adifafun aladaxe ilapaporo timbabeledi agogo.","sections":{"representation":[["Ejiogbe é o primeiro Odu-Ifá e assinala o início de tudo.",4],["É um Odu masculino que deu origem às águas, às palmeiras, às plantas revestidas de espinhos, aos vasos sangüíneos, à coluna vertebral e ao externo.",4],["Representa os raios solares e o ponto cardeal Este.",4],["Este Odu determina que deve-se recorrer à proteção de Oxun e de Orunmilá, para o que faz-se três ebós no mesmo dia.",5]],"native":[["O awo deste Odu recebe Olofin no primeiro ano de sua iniciação e durante este tempo é acompanhado por ele.",7],["O Awo deste Odu não pode praticar sexo oral nem sexo anal com suas mulheres.",7]],"reading":[["Prenuncia infelicidade no amor, o que pode ser evitado com: eiyelé metá funfun 3; dezesseis folhas de amendoeira (Amygdalus communis, Lin.); osun e efun que se despacha no alto do morro com o ebó.",4],["Assinala perseguição de um Egun de Omolú.",5],["Indica que existe alguém que só fala com a pessoa para inteirar-se de sua vida.",6]],"care":[["É proibido fumar no Igbodun de Ifá.",4],["Este itan é prenúncio de que a pessoa será surpreendida fazendo algo que não deve e isto lhe trará muitos problemas e muita vergonha.",10]],"stories":[["Foi por este Odu que Olofin se afastou da Terra por causa da fumaça das fogueiras feitas pelo homem.",4]],"curiosities":[["Representa os raios solares e o ponto cardeal Este.",4],["É regido pelo Sol; seu dia propício é o domingo e sua cor é o branco.",4]]},"ire":{"p":159,"text":"Ogbe abre o caminho para uma nova vida."},"ibi":{"p":159,"text":"o caminho para uma nova vida está bloqueado."}},"0:1":{"alias":"OGBEYEKU","page":17,"phrase":"Ogbeyeku Babá Omolú Ogbeato Awo edan adifafun Inaxe Ikú Agba Iworo akú kata, Oló owolá tinxé ni apé, Yangi omó bogbo eranko lorugbo elegbó.","sections":{"representation":[],"native":[],"reading":[["Fala de separação conjugal na qual terá influência determinante para bons ou maus resultados.",17],["Indica surgimento ou existência de uma situação delicada que se configura devido a desentendimentos em família.",17],["Indica que o consulente não foi criado pelo próprio pai.",18]],"care":[["Não se deve dar opinião sobre uma questão alheia pois isto poderá trazer problemas e repercussões negativas.",17],["Não deve tomar muitos líquidos durante as refeições.",18]],"stories":[],"curiosities":[]},"ire":{"p":159,"text":"o caminho aberto conduz a um fim com êxito. Esse Odu expressa a ideia de um equilíbrio perfeito entre o esforço e o avanço, como também da habilidade de desfrutar o momento e retirar-se novamente."},"ibi":{"p":159,"text":"o caminho aberto conduz a um fim precoce. Esse Odu adverte que os desequilíbrios do presente podem inviabilizar os planos do futuro."}},"0:2":{"alias":"OGBEIWORI","page":21,"phrase":"Ogbeiworí maferefun Obatalá Aleiyó Umbó, inedi ire Umbó Omofá obe bodê kino ideele adifá joko axeguidá Orunmilá Dadá axe, kue ki eiyelé, ekodidé, ekú, ejá, epô, agbado, opolopo owo.","sections":{"representation":[["Este é um Odu de provas, guerras, trabalho, desobediência, necessidades, enganos, inconformidade, traições, inimigos ocultos, etc.",21]],"native":[],"reading":[["Quando surge o Awo deve voltar sua cabeça para a direita e depois para a esquerda.",21],["Quando surge na consulta de uma virgem, indica que ela precisa receber Akofá39 o mais rápido possível, para que não dê desgostos a seus pais.",21],["Avisa que é necessário ficar atento para uma situação pela qual se está passando e que trará muito aborrecimento e vergonha.",21]],"care":[["Evite deixar-se levar, pois, por trás disso, existe apenas uma intenção de vingança.",21]],"stories":[],"curiosities":[]},"ire":{"p":160,"text":"os conflitos se solucionam, liberando o caminho para a transformação espiritual. Esse Odu representa também a masculinidade, a fertilidade e a responsabilidade de ter filhos."},"ibi":{"p":160,"text":"os conflitos do presente conduzem à instabilidade e a processos de transformação complicados. Esse Odu descreve os efeitos negativos de projetos, competências e estruturas evidentes que não são aceitos ou que são desestabilizados, impedindo as transformações por vir. A responsabilidade do desenvolvimento pessoal deve ser assumida."}},"0:3":{"alias":"OGBEDI","page":27,"phrase":"Ogbedi Kaka, Ogbedi Lele, ada xaxá asiko ebana adifafun ati Ogun tinxo oka mamá okpa marun elebó.","sections":{"representation":[],"native":[["Para que os Awo deste Odu não fiquem impotentes têm que praticar sexo com suas mulheres quando estiverem menstruadas.",27],["Para fazer borí para o Awo deste Odu, é preciso também muito orô49, para que nenhum mal venha ocorrer ao oficiante.",27]],"reading":[["Indica a existência de um rapaz que gosta de abusar de meninas muito jovens e que, por este motivo, poderá ser preso, o que só servirá para degenerar ainda mais o seu caráter.",28]],"care":[],"stories":[["Foi neste caminho que o homem aliou-se ao ajapá para refrear o cavalo de Obatalá.",27]],"curiosities":[]},"ire":{"p":160,"text":"o caminho aberto conduz a um renascimento vantajoso. Esse Odu representa, entre outras coisas, a pobreza que se transforma em riqueza através do trabalho árduo e do otimismo, trazendo mais amizades e contatos sociais à pessoa. Ele representa a segunda chance, a vida nova, a metamorfose da lagarta em borboleta."},"ibi":{"p":161,"text":"os caminhos bloqueados conduzem ao fracasso de novos começos. Esse Odu adverte que o recomeço de uma relação com alguém pode ser impedido por uma terceira pessoa. A sogra pode impedir que o casamento seja reatado. Um colega pode atrapalhar a promoção no trabalho."}},"0:4":{"alias":"OGBEROSO","page":30,"phrase":"Ogberoso untele axe ebó tó ariku Babawá Orunmilá akpalosinan, akpo ebó rori Orunmilá Iseta Ogberoso untele axe. Ate deku atie. Atie deja, deja atie. Ate akukó, akukó atie.","sections":{"representation":[["Este é o Odu da verdade e da mentira, onde se confrontam duas inteligências.",30],["Este Odu prenuncia pranto irremediável.",31],["Este é o Exú da mentira, tem três caras e leva uma carga diferente para cada uma delas.",33]],"native":[["Os filhos deste signo são invencíveis e, por isto, Olofin lhes deu o governo do mundo.",30],["O Awo deste signo usa um colar de Orunmilá com 16 contas verdes e 16 amarelas em cada gomo.",30],["O Awo deste Odu tem o dom de adivinhação pela revelação de Egun.",31]],"reading":[],"care":[["Por este motivo, quando surgir este signo, não deve ser registrado e sim substituído por outro, sacado logo depois.",30]],"stories":[],"curiosities":[]},"ire":{"p":161,"text":"o caminho aberto conta com o apoio dos ancestrais. Esse Odu representa a necessidade de dar passos lentos, porém firmes, para que o destino se cumpra. Esse desenvolvimento deve ser orientado e apoiado."},"ibi":{"p":161,"text":"o caminho aberto conduz à instabilidade devido à resistência de algum antepassado. Esse Odu adverte que uma vida oprimida pode não progredir devido à falta de esforço para cumprir o destino pessoal."}},"0:5":{"alias":"OGBEWÓNRIN","page":35,"phrase":"Ogbewónrin ago emi ibeború ke Okunin pawó ayawalá, ayawalá otó, ayawalá osi mokunlo mokunlo, wale koto wale to oun beleno otó otó.","sections":{"representation":[["Este Odu assinala projetos sem consistência e que se transformam em ilusões vãs.",35],["Este é o caminho das Cinco Pedras da Coroa.",36]],"native":[["O filho deste signo considera-se por demais importante, não aceita conselhos nem orientações de ninguém.",35],["O Awo deste signo tem que receber Axekpelú; Osain; Oduduwa e Olofin.",36]],"reading":[["Assinala guerra dentro de casa.",36],["Adverte contra ardência e dores nas solas dos pés; doenças nas vistas; câncer nos ossos e males cardíacos Tem que dar comida a bogbo egun58.",36]],"care":[],"stories":[["Foi por este caminho que Oxun comeu galinha pela primeira vez.",35],["Foi aqui que Obatalá concedeu ao escorpião o poder existente na ponta de seu rabo e que consiste num ferrão e veneno.",35]],"curiosities":[]},"ire":{"p":162,"text":"esse Odu representa o caminho aberto onde pode haver um caos inesperado. Espere o inesperado. O azar pode transformar-se em sorte."},"ibi":{"p":162,"text":"o caminho aberto está bloqueado por um caos inesperado. Esse Odu adverte que pode haver uma desventura. Influências inesperadas transformam a situação presente."}},"0:6":{"alias":"OGBEBARA","page":37,"phrase":"Didun nixe uiye bigbe niti okuru lema ixe unjé lese lokun, ekú adeniá ré wale adifafun oxere igbeti iyegba oma oja fi Ogbematuxe gegere axe esede won ni ko eru, ekú, ejá lebe, igbín meji lebe.","sections":{"representation":[["Este é um Odu que traz traição para seus filhos.",37],["É um Odu de riquezas dadas por Obatalá através de negócios.",38]],"native":[],"reading":[],"care":[["Não deve ostentar sua sabedoria, pois isto lhe traz inimigos poderosos.",37],["Deve ter cuidado porque pode ser grave.",37],["Por isto não deve ter muita vida noturna.",37]],"stories":[],"curiosities":[]},"ire":{"p":162,"text":"o caminho para uma transformação pessoal ou para uma autodescoberta está aberto. Esse Odu identifica um ponto de partida favorável (com força, estrutura, entre outros elementos) para a superação futura do ego."},"ibi":{"p":162,"text":"o autoengano e a negação conduzem ao egocentrismo. Esse Odu adverte que as consequências de não aceitar a vida podem ser negativas."}},"0:7":{"alias":"OGBEKANA","page":40,"phrase":"Ogbekana, Ogbekaran, lodafun Obatalá, lodafun Xangô ni moti alamo ni alakosi moni jeun Ogun Babare. Orunmilá Lorubo.","sections":{"representation":[["Este Odu é que resolve problemas de trabalho.",40],["Este é o osogbo e a principal interdição deste Odu.",40]],"native":[["A pessoa deste Odu tem que fazer Ifá, pois foi neste signo que nasceram os segredos do oponifá e do erukeré.",40]],"reading":[["Assinala uma guerra de grandes proporções que, para ser ganha, tem que se recorrer ao auxílio de Xangô.",40],["Fala de doenças que se mantêm escondidas por muito tempo.",40],["Fala de inimigos ocultos que trabalham em segredo para prejudicar a pessoa.",41]],"care":[["O homem, se a mulher o abandonar, não deve ir atrás dela.",40]],"stories":[],"curiosities":[]},"ire":{"p":163,"text":"o caminho aberto leva a uma nova direção. Esse Odu ressalta a importância de condições favoráveis para um novo começo na vida."},"ibi":{"p":163,"text":"o caminho aberto conduz a uma direção errada. Esse Odu adverte que uma situação inicial aparentemente favorável pode ser mal interpretada, bloqueando um novo começo. Isso possivelmente ocorre devido à falta de visão e de responsabilidade para assumir o controle do próprio futuro e pelo ego."}},"0:8":{"alias":"OGBEGUNDÁ","page":42,"phrase":"","sections":{"representation":[["Este é o Exú de Ogbeyuno que se assenta num jacaré empalhado.",45],["Trata-se de um fio de contas que deverás usar sempre que fores consultar teu Ifá, para que nenhum mal te alcance.",49]],"native":[["O filhos deste Odu não devem, nunca mais em suas vidas, comer pombo.",43]],"reading":[["Assinala três cirurgias e problemas numa das vistas.",43],["Fala de alterações do pâncreas.",44],["Fala de separação e de afastamento o que pode ser resolvido com o oferecimento de um galo branco a Elegbara.",44]],"care":[],"stories":[["Foi neste Odu que Azawani correu o mundo montado num bode da montanha e, como o caminho era muito longo, teve que substituí-lo por um veado, chegando assim em seu reino na Terra de Arará.",43],["Foi por este caminho que se assentou Oxun pela primeira vez.",43]],"curiosities":[]},"ire":{"p":163,"text":"um caminho aberto exige que obstáculos sejam eliminados. Esse Odu indica que há condições para a realização de uma ideia ou visão."},"ibi":{"p":163,"text":"um caminho aberto conduz a conflitos e disputas. Esse Odu adverte que a concretização de projetos, desejos e ideias possivel-mente encontrará forte resistência."}},"0:9":{"alias":"OGBESÁ","page":54,"phrase":"Ogbesá Yeyematero afefé salu aiye, afefé salu Olorun, adifafun ewe bana agbaiyeni abo, agbaiyeni Orunmilá, afefelona Xangô adifafun ewe bana.","sections":{"representation":[["Este Odu é o trono de Ikú.",54],["Este signo marca traição de amigos.",54]],"native":[["O Awo deste Odu tem que usar quatro pulseiras de prata, duas em cada mão.",55],["O filá do Awo deste signo tem que ter, na parte de cima, um círculo na cor de seu Orixá.",55]],"reading":[["Fala de pessoas que foram amigas e que agora se detestam.",54]],"care":[["Depois de assentado, a pessoa deve evitar fazer visitas a enfermos para não adquirir contágio.",54]],"stories":[],"curiosities":[]},"ire":{"p":164,"text":"há condições favoráveis para uma mudança na vida exterior. Esse Odu indica que há condições favoráveis para que uma mudança seja feita com êxito. A mudança corresponde ao mundo exterior, ao plano material ou a relacionamentos."},"ibi":{"p":164,"text":"condições desfavoráveis do estado inicial desfavorecem uma mudança exterior. Esse Odu adverte que o estado inicial (amigos, finanças, etc.) pode ser mal entendido, deixando a pessoa despre-parada para uma futura mudança."}},"0:10":{"alias":"OGBEKA","page":57,"phrase":"Ogbeká adifá joko kanfun axe berebere omó Olofin orubó eure akukó, eiyelé, yarako, axo pupá, Orunmilá lorubo.","sections":{"representation":[["Este Odu fala dos coqueiros, dos testículos e do pênis.",57]],"native":[["O Awo deste Odu é rodeado por uma aura de poder que o protege das negatividades que chegam por Xangô e Oxóssi.",57],["O Awo deste Odu tem que ter oito obís para cada mão de seu Ifá, devendo renová-los todo ano.",57],["É a origem dos altares, por isto, as pessoas deste Odu devem ter um altar com imagens em sua casa.",57]],"reading":[["Indica problemas no local de trabalho.",58]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":164,"text":"um caminho aberto conduz a uma etapa de contemplação. Esse Odu indica que a humildade, o foco e a responsabilidade conduzem à estabilidade."},"ibi":{"p":164,"text":"a falta de responsabilidade própria e a falta de humildade impedem o acesso e a conexão à essência eterna. Esse Odu pede que a vida seja aceita e que a eternidade da essência seja reconhecida."}},"0:11":{"alias":"OGBETRUPON ou OGBETUMAKO","page":59,"phrase":"Ogbetumako kukujé ajá, kukujé ajá, arun atamá jubara kumisá Iyá Adelawá Orunmilá agbani lebó, Orun Ire Nirá kilodafun Exú.","sections":{"representation":[["Este é o caminho de Exú Ní, que possui duas caras.",60]],"native":[["Os filhos deste Odu, por mais inteligentes que sejam, geram um filho mais inteligente que eles.",59]],"reading":[["Quando surge este Odu tem que ser feito ebó para o pai do consulente, para que não venha a falecer precocemente.",59]],"care":[],"stories":[],"curiosities":[]}},"0:12":{"alias":"OGBETUA","page":61,"phrase":"Ogbetua mo foú sesí adifafun Oluwo Alade Mofú Sesí adifafun ajapá tiroko lole nifá ojegue Oduduwa mowale iyere Olofin.","sections":{"representation":[["Neste signo nasceu o Okpele Ifá.",61]],"native":[["Os filhos deste Odu não devem ter cães em casa, pois esses animais roubam-lhe a memória.",62],["Uma grande sombra se interpõe entre Orunmilá e o Awo deste signo e o Orixá acaba por virar-lhe as costas.",62],["O Awo deste signo morre solitário.",62]],"reading":[["Quando este Odu surge trazendo osogbo Ikú, arun ou ofo66, manda-se o consulente fazer alguma coisa para Egun antes de tudo.",61],["Fala de doenças no sangue e na cabeça.",61],["Prenuncia que o consulente ou alguém de sua família fará uma viagem para o exterior e lá se casará.",62]],"care":[],"stories":[["Foi neste Odu que, pela primeira vez, se abriu um buraco.",61]],"curiosities":[]},"ire":{"p":165,"text":"o caminho está aberto para a visão mística. Esse Odu representa a pureza e a confiança nas visões do interior."},"ibi":{"p":165,"text":"o caminho é um autoengano. Esse Odu adverte que as ilusões e as perspectivas podem estar equivocadas."}},"0:13":{"alias":"OGBEATE","page":65,"phrase":"Ogbe Mata Alamata; Alamata omó Awoxe Mafitarun adifafun Omá Banixe ekodidé, adê, ekú, ejá, eiyelé, efun, osun. Obatalá owo mesan elebó.","sections":{"representation":[],"native":[["O Awo deste Odu deve ter um okpele de metal que faça barulho ao ser jogado para que Oxun saiba que está trabalhando com Ifá.",65]],"reading":[["Assinala um pouco de fraqueza sexual.",66]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":165,"text":"os caminhos estão abertos para que a vida exterior seja levada em sintonia com as visões do interior. É necessário agir para que as visões do interior se manifestem."},"ibi":{"p":166,"text":"o caminho aberto conduz à teimosia. Esse Odu adverte que pode haver uma perda devido a um acidente ou a uma doença."}},"0:14":{"alias":"OGBEXE","page":67,"phrase":"Ogbexe kan kanton obajë dewá ekodidé saraundere ololukere lodiye Iyalode okere jimoro enidesun ediferemo otolarefa eji bojo nila. Odu Ajibagadara niawasi niawasi, ikowoxe Iyami waxe, xiiyami mori yeye o!","sections":{"representation":[["Este é o Odu da espionagem.",67]],"native":[],"reading":[["Fala de tiros, maldiçöes, zombaria, doenças do estômago e das vísceras.",67]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":166,"text":"o caminho aberto conduz a uma forte conexão espiritual. Uma vida levada com responsabilidade e em ressonância com o destino é a base da confiança na condução espiritual."},"ibi":{"p":166,"text":"a conexão espiritual fracassa, pois o acesso à vida está bloqueado. Não há responsabilidade e confiança suficientes para uma condução espiritual intensa."}},"0:15":{"alias":"OGBEFUN","page":69,"phrase":"Ogbefun funló puani erí bawí Ikú Mayeyerí wani adifafun Euba unlofé omá Obatalá axé lebó Jekpa Oduxe igungun mariwo lebó abeboadie meji, akukó meji, ekú, ejá epô, owo.","sections":{"representation":[],"native":[["Os filhos deste Odu não devem dormir depois de haverem comido.",69]],"reading":[["Assinala roubos, inconformidade e vidência espiritual.",69],["Fala de falta aos compromissos e falação pelas costas da pessoa.",70],["Assinala doenças do coração.",70]],"care":[],"stories":[["Foi por este Odu que Arun, Ofo e Ikú queriam desposar a filha de Olofin e Orunmilá fez ebó com um galho de seu tamanho, igbín, guizos e mariwo, conseguindo assim, que desposasse Obatalá.",69]],"curiosities":[]},"ire":{"p":166,"text":"os caminhos abertos prometem uma grande realização e satisfação. Esse Odu representa a revelação das visões interiores em equilíbrio com o destino. Esse equilíbrio só é possível quando o ser humano está em harmonia com a vida."},"ibi":{"p":167,"text":"um bloqueio e a má interpretação da vida impedem a concretização de visões internas. Esse Odu conecta o início e o fim. Para alcançar a revelação do destino, é necessário confiar em todos os passos percorridos ao longo do caminho."}},"1:1":{"alias":"OYEKU MEJI","page":71,"phrase":"Baba Oyeku Meji ariké madawá ejó Ogun, sigun moló pororo jarun oni kpo un Babalawo adifafun Ogbe Oluwo agogo, abo lebó.","sections":{"representation":[["É um Odu feminino e teria sido engendrado por duas entidades femininas que o conceberam de forma misteriosa e inexplicável.",71],["Rege os nós das madeiras, o couro áspero dos crocodilos e o pudor humano.",71],["Este é o Exú que acompanha Egun.",74]],"native":[["Os filhos deste Odu possuem uma aura de proteção natural.",72]],"reading":[["Assinala a direção dos movimentos sociais, a realeza, a plenitude.",72]],"care":[],"stories":[["Foi neste Odu que os seres humanos começaram, por recato, a cobrirem seus corpos com folhas e peles de animais, escondendo, assim, suas partes pudicas, o que deu origem às roupas hoje usadas.",71],["Foi aqui que as árvores, para não serem cortadas, fizeram ebó com dois galos, duas galinhas pretas, dois preás, dois machados, dois ekós, dois tambores e muitas moedas.",72]],"curiosities":[["Oyeku Meji é o segundo Odu na ordem de chegada do sistema de Ifá, sua representaçäo indicial é composta de duas colunas de quatro sinais duplos superpostos.",71],["Apesar de ser o segundo na ordem de chegada, este Odu, que representa as trevas, seria mais velho que seu antecessor Ejiogbe, símbolo do surgimento da luz e da vida, já que, segundo os ensinamentos mais recônditos, as trevas antecedem a existência da luz.",71],["É um dos quatro principais signos de Ifá por representar o ponto cardeal Oeste, o Ocidente, o poente, a noite, a morte e as trevas1.",71]]}},"1:0":{"alias":"OYEKUNILOGBE","page":75,"phrase":"Oyekunilogbe Babá Amolú koma arugbo nixe akun gbajé ajalo bogbo nixe aiyuale oun bisiye omode baiya oma arugbo nitu aiyexe obí fun obifá koninibó.","sections":{"representation":[["Este Odu deu ordem para que os tambores jamais fossem tocados de graça.",75],["Este é o Odu da cana-brava (Bambusa vulgaris.",76]],"native":[],"reading":[["Assinala proteção de Orunmilá, de Xangô e de Ibeji.",75],["Quando surge este Odu numa consulta, diz-se ao cliente: Você deu um desgosto tão grande à uma pessoa que ela ficou enferma para sempre.",76],["Prenuncia o risco de se perder um órgão interno.",76]],"care":[["Evite passar por trás de qualquer animal que possa escoiceá-lo.",76],["No ato sexual a mulher não deve ficar por cima.",76]],"stories":[],"curiosities":[]},"ire":{"p":160,"text":"o fim de um ciclo abre um novo caminho. Esse Odu se refere ao fim de diferentes fases do desenvolvimento pessoal (ou de projetos) no decorrer da etapa por vir. O fim da infância conduz à trans-formação da pessoa em adulto. O fim de um projeto, conflito ou de uma etapa cria espaço para novidades."},"ibi":{"p":160,"text":"a má conclusão de um ciclo conduz à instabilidade e ao fracasso de novos começos. Esse Odu alerta para o perigo da avaliação incorreta da responsabilidade pessoal na etapa de desenvolvimento por vir. O fim da infância pode conduzir a problemas na puberdade."}},"1:2":{"alias":"OYEKUIWORÍ","page":77,"phrase":"Oyekuiwori adifafun okini. Elegbara owo, kafarefun Oxun, lodafun Orunmilá.","sections":{"representation":[["É um Odu que, mesmo prenunciando um osogbo, depois de 21 dias virá em ire.",77],["É um Odu de destruição para as crianças.",77]],"native":[["As pessoas deste signo costumam ser mal agradecidas e, por mais que se lhes faça, nunca estão satisfeitas.",77]],"reading":[["Quando surge numa consulta para mulher indica que ela tem que receber akofá imediatamente.",77],["Quando surge este Odu na consulta de uma mulher grávida não se pode fazer nenhum tipo de ebó pois isto fará com que aborte.",77]],"care":[],"stories":[],"curiosities":[["Oyekuiwori, também chamado Oyekupití, é o segundo Amolú de Oyeku Meji, resultado da interação de Oyeku com Iwori Meji.",77]]},"ire":{"p":171,"text":"o fim de um ciclo conduz a uma transformação. Um ciclo deve ser concluído para que mudanças possam ocorrer. As condições estão favoráveis para mudanças."},"ibi":{"p":171,"text":"o fim de um ciclo conduz a conflitos. Esse Odu adverte que muitos projetos paralelos podem atrapalhar o desenvolvimento."}},"1:3":{"alias":"OYEKUDI","page":80,"phrase":"Oyekudi Orunmilá adifá joko, oloju Oyeku orugbo, akukó, ewere, yarako, ajá, ebejó, owo, iwá, bogbo inkan arajé ebebi kan lonlé ile Olofin.","sections":{"representation":[["Este Odu representa o pôr-do-sol.",80],["É filho de Oyeku Meji e Odi Meji.",80]],"native":[["O Awo deste Odu, para ter dinheiro, tem que sentar-se ao lado de Orunmilá e cantar para agradá-lo.",81]],"reading":[["Assinala doenças venéreas e suas conseqüências fatais.",80],["Fala de uma pessoa que não conhece o próprio pai.",80],["Assinala insultos e situações de ridículo para o Awo.",80]],"care":[],"stories":[["Foi por este signo que Orunmilá, por ordem de Olofin, veio organizar o mundo que se encontrava em desordem total.",80]],"curiosities":[]},"ire":{"p":171,"text":"o fim de um ciclo conduz ao renascimento. O fim de uma etapa e um novo começo estão claramente à vista. Uma lagarta se transforma em borboleta."},"ibi":{"p":171,"text":"esse Odu representa o fim precoce de um ciclo e o nascimento precoce de outro. Uma fase não é concluída, impedindo uma renovação."}},"1:4":{"alias":"OYEKUBIROSO","page":82,"phrase":"Oyekubiroso Awo otí Olofin Tuló xawo sadú merin otí, owo iwoko alá ori bogbo intori Aiye kobó otigbe eiyelé, agbo, intori Ikú.","sections":{"representation":[["Este é o caminho, através do qual, Ikú vem buscar as pessoas.",82]],"native":[["O Awo deste signo perde a mãe muito cedo e seu signo irá sobrepujar o de seu padrinho.",83]],"reading":[["Assinala doenças, desgostos e escassez.",82],["Assinala acusações e calúnias.",82],["Assinala uma disputa entre irmãos por uma determinada coisa.",82]],"care":[],"stories":[["Foi por este caminho que Oduduwa sentou-se no trono de Olofin.",83]],"curiosities":[]},"ire":{"p":171,"text":"o fim de um ciclo conduz à revelação dos potenciais. Esse Odu representa o fim de uma fase que abre o caminho para uma revelação consciente, espiritual e enriquecedora."},"ibi":{"p":171,"text":"o fim precoce de um ciclo impede a evolução. Uma fase é interrompida ou concluída de forma precoce, inviabilizando a recriação e o redirecionamento, como também o desenvolvimento espiritual e a consciência."}},"1:5":{"alias":"OYEKUWORIN","page":84,"phrase":"Oyekuwónrin Babawá Ifá Obá Majire. Elegbara Babawá Ifá Ayore lokun, Obá lokun.","sections":{"representation":[["Este Odu castiga, com a perda de tudo, as pessoas que abandonam os seus Santos.",84]],"native":[["Para que o Awo deste Odu seja grande, tem que dar um bode e um galo a Elegbara todos os anos, repartindo seus pedaços com pessoas carentes de diferentes lugares.",84]],"reading":[["Fala de alguém que mantém relações com uma pessoa comprometida.",85]],"care":[],"stories":[["Foi por este caminho que Elegbara comeu galo e bode pela primeira vez.",84]],"curiosities":[]},"ire":{"p":172,"text":"o fim de um ciclo conduz a uma reestruturação interior. A conclusão de uma fase abre o caminho para uma transformação interior."},"ibi":{"p":172,"text":"o fim precoce dos ciclos produz caos. Um ciclo é interrompido ou concluído na hora errada, provocando caos e crises no interior."}},"1:6":{"alias":"OYEKUBARA","page":86,"phrase":"Oyekubara lodafun Oxun lo Osain Oni Xangô Xebe, xintilu osuxe meti exin niloko xixé Ifá xemi. Oxun loxe mamú Olufina opolopo otí ogu weru nixé omó Olofin lodafun Osain kaferefun Agbana Oni Xangô.","sections":{"representation":[["Este é um Odu de atração e amarração.",86],["Este Odu arranca das trevas o espírito do Awo falecido.",86]],"native":[],"reading":[["Avisa de uma dívida com Yemanjá e com Xangô.",86]],"care":[["Não deve ter bengalas ou guarda-chuvas pendurados.",86]],"stories":[],"curiosities":[]},"ire":{"p":172,"text":"o fim de um ciclo conduz à transformação do ego. A transformação interior e a conscientização são possíveis devido à conclusão de um projeto, de uma etapa ou relacionamento."},"ibi":{"p":172,"text":"o fim precoce de um ciclo conduz ao egoísmo. Esse Odu alerta para os problemas relacionados a uma derrota e à perda de disciplina espiritual. Os ciclos não são processados e não podem ser concluídos; o ego é alimentado ao invés de ser transformado."}},"1:7":{"alias":"OYEKUKANRAN","page":88,"phrase":"Oyeku peleká adifafun Okanran, Oyeku Obara jiré wa Obinin aiye olonu ogu larifun Ikú Oyeku peleká.","sections":{"representation":[["Este Odu também é chamado Oyeku Foloko Kana.",88]],"native":[],"reading":[["Fala de alguém que mantém relações sexuais com uma apetebí e com outra mulher de sua própria família.",88],["Assinala doenças no sangue e doenças venéreas.",89]],"care":[["Evite discussões dentro de casa.",89],["Faça ebó para que possa seguir em frente e evite discussões com seu cônjuge.",89]],"stories":[],"curiosities":[]},"ire":{"p":173,"text":"o fim de um ciclo abre as portas para as questões do coração. Temas antigos serão concluídos e novas possibilidades surgirão. Um novo começo é possível."},"ibi":{"p":173,"text":"o fim precoce de um ciclo leva à isolação e à estagnação. Um novo começo é impedido por temas antigos em aberto."}},"1:8":{"alias":"OYEKUGUNDÁ","page":90,"phrase":"Oyeku te Gundá lobina nasá ojó opá otá kuku wora adifafun Aberegue lubá omó Orunmilá, koba Ogun titiwo beberé olotura, agogô labiniku tenyé ewe ogumá. Ifá ni ota ojojo ebó adié, ekú, ejá, ejá, owo teteború.","sections":{"representation":[["Este Odu, também chamado Oyekutegundá, é a personificação espiritual de Orunmilá, ao contrário de seu irmão Ogundayekú, personificação material do Senhor do Oráculo.",90],["É filho de Oyeku e de Ogundá.",90],["Neste signo nasceu a determinação de soprar obí mascado com ataré aos quatro pontos cardeais, sempre que se faz ebó.",91]],"native":[["O Awo deste Odu não pode se afastar deixando questões pendentes, pois isto lhe trará grandes prejuízos.",91]],"reading":[["Avisa ao Awo que Orunmilá afastou-se de sua casa e, para que volte, tem que se fazer ebó com duas galinhas pretas, preá e peixe fresco.",90]],"care":[],"stories":[],"curiosities":[["Este Odu, também chamado Oyekutegundá, é a personificação espiritual de Orunmilá, ao contrário de seu irmão Ogundayekú, personificação material do Senhor do Oráculo.",90]]},"ire":{"p":173,"text":"o fim de um ciclo inviabiliza a concretização de interesses e de novos temas."},"ibi":{"p":173,"text":"a má conclusão de um ciclo ou sua interrupção conduz ao conflito e à disputa."}},"1:9":{"alias":"OYEKUSÁ","page":92,"phrase":"Oyeku Rikusá kuté kukú adifafun Ogun ati Oxóssi. Dariko Oyekusá kaferefun Oiyá, Orunmilá, adifajoko aladafá Awo aladafá otokó, tojo ina meji, ina lowo, Odisá inite lesuxu komandi kolikú edan atoke tojo orugbo sikodie, akukó pupá elebó.","sections":{"representation":[["Este Odu, também conhecido como Oyeku Rikusá, é o caminho de Agoí, qualidade de Omolú fêmea, que surge das águas de uma lagoa, trazendo nas mãos, um abebé e um xaxará9.",92],["Este signo fala de fenômenos espirituais.",92]],"native":[["O Awo deste Odu não respeita Orunmilá e continua a levar o mesmo tipo de vida que levava antes de sua iniciação.",92],["Os filhos deste Odu não devem molhar-se na chuva e, se for filho de Obatalá, deve vestir-se sempre de branco.",93]],"reading":[],"care":[],"stories":[],"curiosities":[["Este Odu, também conhecido como Oyeku Rikusá, é o caminho de Agoí, qualidade de Omolú fêmea, que surge das águas de uma lagoa, trazendo nas mãos, um abebé e um xaxará9.",92]]},"ire":{"p":173,"text":"o fim de um ciclo viabiliza uma mudança radical."},"ibi":{"p":173,"text":"a má conclusão de um ciclo conduz ao caos e à instabilidade."}},"1:10":{"alias":"OYEKUBIKÁ","page":94,"phrase":"Oyekubiká oye wadelaka adifafun Oyeku Oyeku, adifafun Ifá. Oyekubiká alake edon adifá oye oun nogbati ti asokpo. Kun ekú, ejá ti o la xawo.","sections":{"representation":[["É filho de Oyeku e de Iká Meji.",94]],"native":[["Os Awo deste Odu não podem fazer Ifá em ninguém.",94],["Os filhos deste Odu têm que fazer borí com ejá enirú10.",95]],"reading":[["Assinala soberba e orgulho.",95],["Assinala falta de ar, insuficiência respiratória e doenças cardíacas.",95]],"care":[],"stories":[["Foi por este caminho que Ogun tirou os dezesseis Meji do merindilogun.",94]],"curiosities":[]},"ire":{"p":174,"text":"o fim de um ciclo libera e avigora a força interior."},"ibi":{"p":174,"text":"o fim inesperado e desfavorável de um ciclo enfraquece o ponto de vista pessoal e a força interior."}},"1:11":{"alias":"OYEKUTURUPON","page":96,"phrase":"Oyekubatrupon Ifá ni unlesile ilare lokun, ilare obí, ni pa mi, kaferefun Orunmilá, Obarabanirogun Olofin.","sections":{"representation":[["Este Odu assinala proteção de Exú, Orunmilá, Ogun e Oxun.",96]],"native":[["O Awo deste signo não se ocupa com Ifá, por isto, não é reconhecido como sacerdote.",96]],"reading":[["Assinala sofrimento causado pelo fogo.",96]],"care":[],"stories":[["Foi neste Odu que se cozinhou pela primeira vez.",96]],"curiosities":[]},"ire":{"p":174,"text":"o fim de um ciclo conduz a um novo crescimento e à cura."},"ibi":{"p":174,"text":"a má conclusão de um ciclo impede o crescimento e a cura."}},"1:12":{"alias":"OYEKUTURA","page":98,"phrase":"Oyekuturá Tesia akiki Olorun obí lolun mati mibi kogun Awo Apigumi wá ta akin adilá sara akukó abelo Orunmilá.","sections":{"representation":[["Este é o Odu da transfiguração.",98]],"native":[["O Awo deste signo deve criar, em sua casa, duas galinhas d'angola É caminho de Oduduwa e das almas solitárias Coloque uma bandeira vermelha em Xangô e saúde-o.",98],["Os filhos deste Odu gostam de praticar o sexo oral.",98]],"reading":[],"care":[],"stories":[],"curiosities":[["EXÚ AIYANGI ELUFÉ É um Exú da Terra Dassá, também chamado Kpoli.",99]]},"ire":{"p":174,"text":"o fim de um ciclo libera a mente para novas visões."},"ibi":{"p":174,"text":"a má conclusão de um ciclo cerra as portas para novas visões."}},"1:13":{"alias":"OYEKUBIRETE","page":100,"phrase":"Oyekubirete molalá, Awo molalá, intori Ifá arun molalá, abe oju laye tin xore. Ifá Oluwo Popo molalá. Awo tinxore Ifá Oxalá, Ifá molalá ni jabe otároni. Ifá mojare ni laiye molalá.","sections":{"representation":[["É filho de Oyeku e Irete Meji.",100]],"native":[],"reading":[["Assinala separação conjugal.",100],["Assinala fraqueza dos ossos, artrite, impotência por abusos sexuais, doenças nas pernas e leucemia.",100]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":174,"text":"o fim de um ciclo cria espaço para que a pessoa aja com determinação."},"ibi":{"p":175,"text":"a má conclusão ou o fim desfavorável de um ciclo conduz à rigidez."}},"1:14":{"alias":"OYEKUXE","page":102,"phrase":"Oyeku Pekioxe lodafun obí oxeman eyeleo kama xeruwo ilê kende oma firo Oxun Obinin meji tanilo.","sections":{"representation":[["É filho de Oyeku Meji e Oxe Meji.",102],["Este Odu mostra a morte em sonho.",102],["Este Odu proíbe que se empreste agulhas para não ocasionar transtornos.",103]],"native":[["As pessoas deste signo não devem usar perfumes nem colocar flores dentro de sua casa.",102]],"reading":[["Assinala proteção de Yemanjá.",102]],"care":[],"stories":[["Foi por este caminho que Orunmilá chegou a um local onde não existiam seres vivos e que servia de descanso para todos os reis de Ifé.",102]],"curiosities":[]},"ire":{"p":175,"text":"a conclusão de um ciclo conduz à prosperidade, conexão e abundância."},"ibi":{"p":175,"text":"o fim desfavorável de um ciclo conduz ao egoísmo, à perda de conexão e ao vazio."}},"1:15":{"alias":"OYEKUBEFUN","page":104,"phrase":"Oyekúbedurá mafun agbá barabá, mafun agba Ofun mayekun fun Iyansã, lelé foguere belele malere, Oyeku fun mafunyeké belere Ori Oxun Oriyeyeo, molala lala jeri Iyalode Oriyeyeo, lele Oxun bebere Okanran ielegue yelele, Oyekufun yeyebi Oiya Oma jire Awa Babadawa. Awo Oba Eri Ifá kaferefun Lewri Ifá. Kaferefun Elegbara.","sections":{"representation":[],"native":[],"reading":[],"care":[],"stories":[["Foi por este caminho que, com a ajuda de Oiyá, Exú Larufá se fez grande sobre a Terra.",104],["Foi aqui que Xangô transmitiu o poder do reino a Orunmilá.",104],["Foi neste caminho que Oxun adquiriu escravos.",104]],"curiosities":[]},"ire":{"p":175,"text":"a conclusão de um ciclo conduz à revelação, trazendo uma experiência de abundância, do destino e da criação."},"ibi":{"p":175,"text":"o fim de um ciclo conduz ao fracasso geral. O destino e as metas pessoais não são cumpridos."}},"2:2":{"alias":"IWORI MEJI","page":106,"phrase":"Iwori Meji iguí iguí, miyo miyo, adifafun Kolokó iyebefá tiroke Iyá lampé Xangô, Aroní yeó Eleripin Orunmilá lorugbó.","sections":{"representation":[["Este é um Odu masculino, filho de Tehitana e Houlogodo.",106],["Este Odu determina que se resguarde a cabeça de sua ação de Anjo Exterminador.",106],["Este signo desperta a pessoa para que descubra grandes coisas a partir de detalhes insignificantes.",107]],"native":[["Os filhos deste Odu ocultam muitas verdades dentro de si mesmos.",107]],"reading":[["Prenuncia a morte de uma criança.",107],["Fala de chantagem, roubo, instabilidade no matrimônio, mulher inescrupulosa que usa de todos os meios, por mais imorais que sejam, para conquistar o homem desejado.",107]],"care":[["O Awo que tenha um afilhado deste signo deve evitar dar-lhe muito poder, pois são pessoas muito perigosas e, dentro de cada uma delas, existe uma verdadeira fera adormecida.",107]],"stories":[],"curiosities":[["Está ligado ao ponto cardeal Sul e, por isto, é um dos quatro principais Odus de Ifá.",106],["Sua cor é o marrom-avermelhado e é através dele que se faz o mal às mulheres usando, para este fim, panos sujos de seu sangue menstrual colocados dentro de uma cabaça junto com pó de peixe e de preá e um peixe de água doce.",106],["Proíbe, a seus filhos, comerem galo e amalá. ordem de chegada: Ejiogbe; Oyeku Meji; Iwori Meji; Odi Meji; Irosun Meji; Owónrin Meji; Obara Meji; Okanran Meji; Ogunda Meji; Osá Meji; Iká Meji; Oturukpon Meji; Otura ou Otuwá Meji; Irete Meji; Oxe Meji e Ofun Meji.",107]]},"ire":{"p":178,"text":"uma transformação conduz a uma nova identidade."},"ibi":{"p":178,"text":"a resistência à transformação conduz a conflitos e à perda da identidade."}},"2:0":{"alias":"IWORIBOGBE","page":110,"phrase":"Iworibogbe Ifá mayewé, Ifá Afefé ti ikí ití ewe anakun Orun Bebeni. Ifá Adiyoko Onibarabaniregun ará buxe, Awo Mayewe, Awo Adiyoko ori Ifá oni Xangô, oniwó Olokun onini Ifá.","sections":{"representation":[["Este Odu resulta da interação de Iwori com Ogbe.",110]],"native":[["O Awo deste Odu não deve trabalhar com Ifá quando ocorrerem tempestades.",111]],"reading":[["Assinala débitos com Xangô.",110],["Fala de enfermidades produzidas por descontrole nervoso, asma, esquizofrenia, úlceras gástricas, úlceras duodenais e ataques transitórios de insanidade mental.",110],["Fala de doenças da cabeça, para as quais, tem-se que fazer ebó, pois existe perigo de vida.",110]],"care":[["O Awo deste Odu não deve trabalhar com Ifá quando ocorrerem tempestades.",111]],"stories":[],"curiosities":[]},"ire":{"p":160,"text":"a transformação bem-sucedida abre um novo caminho. Esse Odu realça a necessidade de levar os processos de desenvolvimento até o fim e concluí-los."},"ibi":{"p":160,"text":"a transformação inacabada fecha as portas para novos caminhos. Esse Odu adverte que uma interrupção ou processos de transformação inacabados podem dificultar os projetos do futuro e levá-los ao fracasso."}},"2:1":{"alias":"IWORIYEKU","page":112,"phrase":"Iworiyeku inkan Ikú ombelare oun yelein intori ikan to walore alá toguman alá bururu oun batonxé gbe inkan to gire lori ko mawá yote lowo loma ni mi obori.","sections":{"representation":[],"native":[],"reading":[["Assinala traição por parte da mulher.",112],["Assinala que a mulher tem dois homens que pertencem a um mesmo grupo religioso ou a uma mesma sociedade.",112],["Assinala uma guerra por causa de um certo homem.",112]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":171,"text":"a transformação conduz à contemplação, à paz e à conclusão. A transformação de uma pessoa ou de uma situação cria as condições necessárias para a conclusão de projetos em aberto."},"ibi":{"p":171,"text":"um conflito conduz ao fim precoce de um ciclo. Processos de transformação, que são necessários, não estão em andamento, impedindo a conclusão de uma fase ou de um projeto."}},"2:3":{"alias":"IWORIDI","page":114,"phrase":"Iwori Bode, Iwori Ifá, Ifá Iwori, omó yebé gongoló, yebó Obatalá, abure ni Ifá Olokun Gbore, omó ina bore Ifá wolode fi alaguema sayeré, Ifá Oxalá lorubo.","sections":{"representation":[["Este Odu fala de fenômenos marinhos como maremotos e alterações nas marés.",114],["Este Odu traz o risco da cegueira.",114]],"native":[],"reading":[["Assinala problemas com o aparelho urinário.",114],["Fala de touradas, do touro e do toureiro.",114],["Assinala uma demanda com um macumbeiro.",115]],"care":[["Não deve matar lagartixas, elas são sua salvação.",115]],"stories":[],"curiosities":[]},"ire":{"p":178,"text":"a transformação é a base do renascimento. Uma nova identidade dá impulso a um novo começo."},"ibi":{"p":179,"text":"a resistência à transformação e à descoberta da identidade impede que novos temas sejam reabertos. A transformação e a descoberta da identidade não são possíveis. No futuro, tentativas de reaver projetos, fases do passado, ou de reatar relacionamentos, fracassarão."}},"2:4":{"alias":"IWORIKOSO","page":116,"phrase":"Iworikoso eni ewá Ogboni Egun Ikú ayegue, iwoneke arun efun. Efun lelé yekun Iyá arun leyé leyé intori arun Obonhú. Oluwo Aboman Ifá omó Awo Oyeku leyé lengue yengue Orun Ogboni Fá Inle ebó lokun omó niká.","sections":{"representation":[["Este Odu mora num pântano onde as pombas se perdem.",117]],"native":[],"reading":[["Assinala inveja que atrasa o desenvolvimento das atividades comerciais, roubo no comércio e transações desleais.",116]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":179,"text":"uma transformação conduz à realização do potencial. A descoberta da identidade permite que novos temas sejam vividos com um novo espírito."},"ibi":{"p":179,"text":"uma crise de identidade impede que algo seja reconstruído. A transformação e a descoberta da identidade não são concluídas. Não é possível dar vida, uma nova consciência ou um novo sentido a novos projetos."}},"2:5":{"alias":"IWORIWORIN","page":118,"phrase":"Ifá Iworiwónrin, Ifá wará wará a ni moro ka xe itá, ka xe mine, wará wará Babasonan Ela roye laroye ka xe itá, ka xe mine, wará wará mi moro Orunmilá o lorubo.","sections":{"representation":[["Este Odu é o guardião das sepulturas e de Ikú, pai de Laye.",118]],"native":[["As pessoas deste signo devem cuidar de um Egun denominado Babá Oba Axe, que é tratado num coco seco, dentro do qual se introduz, por um buraquinho feito na parte de cima, seis grãos de ataré, nove gotas de epo-pupá e um pouco de aguardente.",119]],"reading":[],"care":[["A pessoa, embora passando por grandes dificuldades, não deve chorar miséria, ao contrário, deve mostrar-se satisfeita e cantar para que a miséria se afaste.",119]],"stories":[],"curiosities":[]},"ire":{"p":180,"text":"uma transformação e uma nova identidade conduzem a mudanças positivas inesperadas no interior e no exterior. A disposição para transformar-se, formando uma nova identidade, conduz a mudanças inesperadas e possivelmente drásticas na vida interior. A transformação conduz a um desapego interior."},"ibi":{"p":180,"text":"uma crise de identidade e a resistência à transformação conduzem ao caos interior e à perda de controle. Uma crise interior está fora de controle. Não há disposição para que ocorra uma mudança, porém ela é inevitável."}},"2:6":{"alias":"IWORIBARA","page":120,"phrase":"Iwori Obara oun bareye, oun tirola, iyo timode aye, oun beré loko, adifafun Iyalode, eye bemeku, Yewá joko, Yewá eure elebó.","sections":{"representation":[["Este Odu é caminho de Orunmilá, Oxun e Xangô.",120],["Este signo indica cargo de Babalosain.",120],["Este Odu indica que a pessoa tem bom coração e que, por este motivo, todos se aproveitam dela.",121]],"native":[],"reading":[["Indica que existe uma pedra em seu caminho.",120]],"care":[],"stories":[["Foi por este Odu que Orunmilá, associando-se a Ossain, não precisou mais trabalhar na lavoura, passando a viver da prática da medicina.",120]],"curiosities":[]},"ire":{"p":180,"text":"uma transformação e a descoberta da identidade transformam o ego."},"ibi":{"p":180,"text":"uma crise de identidade impede a transformação do ego. Não há preparação para conhecimentos interiores, não há disposição para mudança. O ego domina."}},"2:7":{"alias":"IWORIKANRAN","page":122,"phrase":"Iwori Kana adifafun ejá Okunin, axirí Okun, Olokun Obá, Olokun lopá leri, kaferefun Orunmilá, lodafun Olokun.","sections":{"representation":[["Este é o signo dos mergulhadores e escafandristas.",122],["Trata-se de alguém muito ingrato e que não demonstra reconhecimento por nada que se faça em seu favor.",122],["Este Odu fala de uma pessoa que não conheceu a própria mãe.",123]],"native":[],"reading":[],"care":[],"stories":[],"curiosities":[]},"ire":{"p":180,"text":"a transformação do ego favorece um novo começo para os assuntos do coração."},"ibi":{"p":181,"text":"o egoísmo e o egocentrismo impedem um novo começo e bloqueiam os assuntos do coração."}},"2:8":{"alias":"IWORIGUNDÁ","page":124,"phrase":"Iwori Ogunda, Iwori owá lelé Ifá, Ogunda awabó borun awaniri lorín oni Ifá Awo Beheni, Awo Kanibi, Ifá awakení, Ifá oribayé, Awo Abiwá abani Awo.","sections":{"representation":[["É um Odu de perdas violentas.",124],["Este Odu fala de Olokun e de Ogun e a pessoa para quem sair, provavelmente, será filha de Oxóssi.",125],["É um Odu que fala de tratos verbais.",125]],"native":[["A pessoa deste signo tem que ter um pedaço de yagua (Tecido fibroso que rodeia a parte superior e mais macia do tronco da palmeira-imperial).",124],["Por este motivo, os filhos deste Odu não devem comer carne suína.",124],["As pessoas deste signo não podem confiar em ninguém e todos os seus negócios devem ser muito bem documentados para que não venham a causar problemas e grandes perdas.",125]],"reading":[["Fala de intoxicação ocasionada por carne de porco.",124]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":181,"text":"uma transformação e uma nova identidade liberam energia, abrindo o caminho para a concretização de novas ideias e projetos."},"ibi":{"p":181,"text":"uma crise de identidade enfraquece a capacidade de ação e a força de vontade necessárias para a concretização de novos temas."}},"2:9":{"alias":"IWORIOSÁ","page":126,"phrase":"Iwori Bosá adifafun Babá Ajagunan, Elese Olofin amego ogbo ni Ologun bogbo aiye Olofin Alámerere. Kaferefun Obatalá. Lodafun Odu.","sections":{"representation":[["Este é o caminho do calote.",127]],"native":[],"reading":[["Assinala dívida com Obaluaye.",126],["Assinala perseguição de um Egun que deve ser afastado com ebó.",127]],"care":[],"stories":[["Foi por este Odu que Olofin abandonou a Terra.",126]],"curiosities":[]},"ire":{"p":181,"text":"uma transformação interior e a descoberta da identidade conduzem a mudanças externas radicais."},"ibi":{"p":181,"text":"a resistência interior à transformação conduz a um colapso na vida exterior. Outra opção é que uma resistência interior impeça que mudanças externas necessárias ocorram."}},"2:10":{"alias":"IWORIOBOKÁ","page":128,"phrase":"Iworiboká adifafun Orunmilá. Iworiboká boko adifafun Orunmilá. Adie elebó. Babá Boká gunugun axabá gagá gungun aká axabá gueko adifafun Aleyo ibaba gueko.","sections":{"representation":[["Este é um signo de infelicidade conjugal e de tragédias passionais.",128],["Este é um signo de roubos e perdas.",129]],"native":[],"reading":[],"care":[],"stories":[["Foi neste Odu que o inhame e a malanga (Planta arácea comum nas zonas intertropicais, cujo tubérculo é importante alimento, principalmente para os camponeses) estabeleceram uma disputa entre si.",128]],"curiosities":[]},"ire":{"p":181,"text":"uma transformação e a descoberta da identidade avigoram a força interior e a essência."},"ibi":{"p":182,"text":"a falta de transformação e de descoberta da identidade desestabilizam a posição e a força interior."}},"2:11":{"alias":"IWORITURUKPON","page":130,"phrase":"Iwori Trupon eiyelé, ekó, oni guere eyiele, adakoi eiyele, lebó. Owunkó lebó.","sections":{"representation":[],"native":[],"reading":[["Prenuncia nascimento de filhos gêmeos.",131]],"care":[["A pessoa não deve tomar muito Sol. no Oráculo de Ifá.",130]],"stories":[["Foi neste caminho que Orunmilá apaixonou-se pelos encantos de Yemanjá, o que o levou a matar, com uma estocada, o rei do país onde vivia sua amada.",130]],"curiosities":[]},"ire":{"p":182,"text":"uma nova identidade conduz a um novo crescimento."},"ibi":{"p":182,"text":"uma crise de identidade e uma estagnação impedem o crescimento."}},"2:12":{"alias":"IWORITURÁ","page":132,"phrase":"Iwori Otura iguí iguí, miyo miyo, adifafun Kolokó iyebefá tiroke iya lampé Xangô, Aroní yeó Eleripin Orunmilá lorugbó.","sections":{"representation":[["Este é o caminho do curioso.",132]],"native":[],"reading":[["Assinala a troca de cabeça de duas irmãs.",132],["Assinala um grande desgosto relacionado à uma mulher grávida.",133]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":182,"text":"a transformação e uma nova identidade avigoram a visão interior."},"ibi":{"p":182,"text":"a estagnação da descoberta da identidade e a recusa a transformarse conduzem ao autoengano ou bloqueiam a capacidade de visão interior."}},"2:13":{"alias":"IWORIRETE","page":134,"phrase":"Iwori Irete adaé ebí osu dudu ekun fibí kurumá tele ijó. Xeke irí xake adifafun akukó mokekejé, ekó tolofe aniake omó Olokun, bogbo Awo eranko eiyé xagobo aluku inika ni ejá okó abele ikokó eji adifafun Elegbara.","sections":{"representation":[["Este Odu prenuncia fogo dentro de casa.",134],["Este é seu ponto vulnerável.",135]],"native":[["A pessoa deste Odu não pode andar na rua depois das vinte e quatro horas, pois podem deparar-se com fantasmas e assombrações.",135]],"reading":[["Fala de um homem de mau caráter que, depois de abandonar sua própria casa, pretende voltar para continuar maltratando sua mulher e seus filhos.",135],["Assinala chegada de dinheiro, provavelmente através de alguém vindo do interior.",135],["Fala de três enfermidades que devem ser tratadas espiritualmente.",135]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":182,"text":"a transformação e a descoberta da identidade conduzem à determina-ção e à ação."},"ibi":{"p":182,"text":"a resistência a mudanças e a novas direções conduz à obstinação ou à incapacidade de ação."}},"2:14":{"alias":"IWORIBOXE","page":136,"phrase":"Iwori Boxe Oba Leri, Oba Leri Inle Poledi wanwan lodé nifá Abeyere Awo Leri Baleri Inle Iwori Obá ni. Iwori Babá loní Oxe Iwori Noxenxé abí Oxe okolowo borí boxé egboni in xé inle nayeri layé Awo Obara Ni Boxanxe Ifá.","sections":{"representation":[["É um Odu de defeitos físicos e morais.",136]],"native":[["Os filhos deste Odu sentem-se atraídos por todos os tipos de jogos, mas, como não têm sorte, devem evitar esta prática, pois esta será a sua destruição.",136]],"reading":[],"care":[["Não deve admirar-se tanto no espelho, nem permitir que outra pessoa use sua toalha e seu sabão para que não venha a perder o que lhe pertence.",137]],"stories":[],"curiosities":[]},"ire":{"p":183,"text":"a descoberta da identidade conduz à prosperidade e à conexão espiritual."},"ibi":{"p":183,"text":"uma crise de identidade conduz à ganância ou à perda."}},"2:15":{"alias":"IWORIBOFUN","page":138,"phrase":"Iwori Ofun, Iwori Towofun, Iwori Tesofú Obá Iworifará Inle reré bobofun xerú xerú adifafun Obinin Olonú tiriko kodun. Adepenite omó Olokun lodafun oni obinin sokun, Inle Oniká Olokun wagbe ni omobini omotitun okeke Obá Iyá Omologu akere sopotu ikoló. Olokun lodafun Olokun.","sections":{"representation":[["Este Odu indica que quando a mulher estiver grávida e as condições em que vive não forem propícias, fará tudo para livrar-se da gravidez, mesmo que isto possa lhe custar a vida.",139]],"native":[],"reading":[["Assinala problemas no útero que podem provocar abortos.",139]],"care":[],"stories":[["Foi por este Odu que Ogun, para ganhar uma guerra, fez ebó com um galo, inhame e dois pombos.",138],["Foi neste Odu que os dinossauros vieram à Terra.",138]],"curiosities":[]},"ire":{"p":183,"text":"a transformação interior conduz a revelações. A descoberta da identidade favorece a manifestação do destino. Novos encontros ou projetos estão à vista e trarão muita satisfação, basta quer o processo de transformação seja concluído."},"ibi":{"p":183,"text":"uma crise de identidade e a falta de força de vontade para mudar bloqueiam o caminho do destino. Esse Odu adverte para a possibilidade de haver estagnação, projetos ruins, relacionamentos e fases infelizes."}},"3:3":{"alias":"ODI MEJI","page":140,"phrase":"Odi Meji axama, arumá, kodimá Ikú, kodimá xukurú, kurú kielé bití bití, kogobale ni abiti adifafun aiye, omó egan ekodidé lebé.","sections":{"representation":[["Representa os órgãos sexuais femininos.",140]],"native":[["As filhas deste Odu são de natureza quente e muito sensuais.",140],["Os filhos deste Odu são demasiadamente ciumentos e intrigantes, gostando de imiscuir-se em assuntos com os quais nada têm a ver.",140],["As pessoas deste signo devem ter muito cuidado com o mar e com os rios que representam sempre, para elas, um perigo constante.",141]],"reading":[["Fala de perversões, da prática do espiritismo e indica soluções de problemas com a ajuda de Eguns.",140],["Fala de enfermidades nos ouvidos.",141],["Indica problemas de loucura na família.",141]],"care":[],"stories":[["Foi neste signo que as mulheres aprenderam a fazer lavagens em seus órgãos sexuais.",141]],"curiosities":[["Seu nome significa \"Duas Nádegas\".",140]]},"ire":{"p":186,"text":"a renovação sucede em todos os níveis."},"ibi":{"p":186,"text":"há uma estagnação no antigo; o vinho velho está em uma garrafa nova. Não há novidade."}},"3:0":{"alias":"ODIGBE","page":143,"phrase":"Odigbe Orona Ogun. Odigbe Orona Orixá ekuté lelé ouá okí Iyá adifafun Oká Babá, eiyele marun elebó. Odigbe Oruna Ogun, Odigbe Oruna Orixá lo omó Ogun Iyá adifafun Orunmilá lorubo.","sections":{"representation":[["Este Odu é filho de Odi com Ogbe.",143],["É um Odu de roubo, de malversação e desonestidade na administração de coisas alheias.",144]],"native":[],"reading":[["Fala de mulheres violentas.",143],["Assinala sacrifícios pela família ou pela sociedade que, no final, não são reconhecidos.",143],["Fala de doenças de pele, principalmente de lepra.",143]],"care":[["A pessoa não deve molhar-se na chuva e tem que ter muito cuidado com as vistas.",143],["Deve ter cuidado para não morrer de um susto.",144]],"stories":[["Neste caminho Osain traiu a Yemanjá e a Orixaoko.",144]],"curiosities":[]},"ire":{"p":161,"text":"o renascimento abre o caminho para a vida. Esse Odu representa a possibilidade de contornar uma ameaça e de conseguir manter um ambiente favorável."},"ibi":{"p":161,"text":"a renovação não conduz a novos caminhos. Esse Odu alerta para a necessidade de conduzir o novo caminho de uma maneira diferente às anteriores. Um maior esforço, quando feito no âmbito de antigos hábitos, não conduz a um maior êxito. Um caminho novo não deve ser uma repetição."}},"3:1":{"alias":"ODIYEKÚ","page":147,"phrase":"Odiyekú Diyekú olodafun Babararegun aun rukú oloyá umbó umpelesé ayareló.","sections":{"representation":[["Este signo é pintado na Atena quando se vai cultuar Egun.",147]],"native":[],"reading":[["Quando este Odu surge para um enfermo, não se pode fazer nada, pois a salvação dele pode significar a morte de quem fizer o trabalho para salvá-lo.",147],["Assinala o nascimento de um menino.",147]],"care":[["Não deve zombar de ninguém, tampouco dos alcoólatras, para não se tornar alvo do mesmo tipo de zombaria.",147],["Não deve maldizer nem desejar mal a ninguém.",147],["Não deve aceitá-lo, pois aparecerá um outro que lhe será muito mais conveniente.",148]],"stories":[["Foi aqui que se fizeram as máscaras para o culto de Egun e de Olokun.",147]],"curiosities":[]},"ire":{"p":171,"text":"o renascimento conduz à realização. Um novo começo e o renascimento com novas energias e novas estruturas conduzem à conclusão."},"ibi":{"p":171,"text":"a renovação fracassa, conduzindo ao fim precoce de um ciclo. Todas as tentativas de reviver um tema fracassam, dando fim a um ciclo."}},"3:2":{"alias":"ODIORÍ","page":149,"phrase":"Odiorí, Odi ofoyu nowá yení obá oyú lelé. Inle Alabanijó, omólogú Yekú, omó Inle sokun yeré ofujú ni ainá Iyá Inle lodafun. Axe axirí lelé ojueró. Obá aina oná, Obá Odé lodafun Inle. Kaferefun Osain.","sections":{"representation":[["Este Odu determina que a pessoa tenha que cultuar Yemanjá e Orunmilá.",149]],"native":[],"reading":[["Assinala doenças na barriga e ao redor da cintura.",149],["Assinala sofrimento das hemorróidas.",150]],"care":[["A pessoa não deve colher folhas depois das 18 horas, pois isto lhe trará atraso de vida.",150],["Não deve tomar chuva para não adoecer.",150],["Durante este período, a pessoa não deve ingerir bebidas alcoólicas.",150]],"stories":[],"curiosities":[]},"ire":{"p":179,"text":"o renascimento conduz à transformação e à descoberta da identidade. Um tema antigo é reatado, conduzindo a novas descobertas, à transformação e à identidade."},"ibi":{"p":179,"text":"uma tentativa de recomeçar algo que já foi concluído fracassa, levando a uma crise de identidade. A teimosia, o apego e a repetição de antigos hábitos conduzem ao fracasso, levando a conflitos internos, crises de sentido e processos complicados de transformação."}},"3:4":{"alias":"ODIROSO","page":151,"phrase":"Odi Irosun awosé wewé adifafun ologbo, adifafun ona odifé okuté aiyajú koró adafé ajá, eiyele. lebó, ewefá lebó.","sections":{"representation":[["Este Odu é regido pelo mar bravio, a pessoa sofre dos ouvidos.",152]],"native":[["As pessoas deste Odu não podem raspar a cabeça quando fazem Santo.",151],["Os filhos deste Odu não podem cuidar de loucos para não ficarem abalados mentalmente.",151],["As filhas deste Odu têm que amarrar seus maridos para não serem abandonadas por eles.",152]],"reading":[["Assinala doenças nos testículos.",152]],"care":[],"stories":[["Neste caminho faz-se ebó com qualquer coisa.",152]],"curiosities":[]},"ire":{"p":186,"text":"a renovação conduz à realização dos potenciais."},"ibi":{"p":186,"text":"a falta de renovação impede a realização dos potenciais."}},"3:5":{"alias":"ODIWÓNRIN","page":153,"phrase":"Odi Owónrin awo faxé Ikú. Ikú omó Sarebakú faxé Ikú. Awo omó Ikú Aberere nilaye Inle. Awo faxé Ikú omó Oyeku obá ni Xangô.","sections":{"representation":[["Neste signo nasceu a inimizade entre o tigre e o macaco.",154]],"native":[["As pessoas deste signo, para terem sucesso na vida, não podem depender de ninguém.",154]],"reading":[["Assinala proteção de Xangô.",153],["Assinala perdas ocasionadas por menosprezo a outrem.",153]],"care":[["Sofre prejuízos morais e materiais por falar o que não deve acerca de outras pessoas.",153],["Não deve fazer nada que não queira fazer mesmo sendo obrigada.",153],["Não deve dar garantias nem aval a ninguém.",153]],"stories":[],"curiosities":[]},"ire":{"p":187,"text":"a renovação dissolve padrões internos e conduz a processos de purificação."},"ibi":{"p":187,"text":"a renovação ou novos temas, pessoas e situações conduzem ao caos interno. Abortos ou a reincidência de antigos hábitos ou temas podem causar uma sobrecarga, desorientação ou dúvida pessoal."}},"3:6":{"alias":"ODIBARÁ","page":155,"phrase":"Adifafun Ekuekuyeye Oxá Odadra waye adafun adié orubó. Adié ekani odara.","sections":{"representation":[["Este signo fala de um jardim florido.",156],["Este Odu ensina que Oxun é natural da terra Ijexá e a pessoa para quem saia é sua filha.",156]],"native":[["O Awo deste Odu tem que ter um pé de ewe yeyé plantado na frente de sua casa, seja no solo ou num vaso, para defendê-lo de qualquer malefício.",156]],"reading":[],"care":[["Deve ter cuidado par anão expor ao Sol, as partes de seu corpo onde a pele for mais sensível.",155]],"stories":[],"curiosities":[]},"ire":{"p":187,"text":"a renovação viabiliza a transformação do ego."},"ibi":{"p":187,"text":"os antigos hábitos e a estagnação, ou também projetos inapropriados e pessoas erradas, intensificam o egoísmo."}},"3:7":{"alias":"ODIKANRAN","page":157,"phrase":"Odikanran kamayé bi Awo Menorá, Awo Iyabí Madawá, Awo Abiti Laiye, omó Maiyagba, omó Inle. Ibaí Babá Ifá omó Mosagbá Agbeiye. Nifá odara.","sections":{"representation":[],"native":[["O Awo deste signo não pode morar em apartamentos ou sobrados, tem que residir em casa baixa, que tenha quintal de terra.",158]],"reading":[["Assinala destruição do organismo, quer seja por doença incurável, quer seja por acidente imposto como castigo dos Orixás.",158],["Indica enfermidades relacionadas à circulação sangüínea (veias e artérias), ao coração e aos brônquios.",158]],"care":[["Não deve aceitar de volta uma mulher que o abandonou.",157]],"stories":[],"curiosities":[]},"ire":{"p":187,"text":"a renovação e o novo começo abrem novas possibilidades."},"ibi":{"p":187,"text":"a recusa ou a falta de capacidade de renovar-se bloqueia novas possibilidades, conduzindo à estagnação interna e externa."}},"3:8":{"alias":"ODIGUNDÁ","page":160,"phrase":"Odigundá pinamú ibú omu adifafun Akuê axé akukó lebé yamagara adifafun Alakú akukó idá, otí, owo mesan elebó.","sections":{"representation":[["Este signo é filho de Odi com Ogundá.",160]],"native":[["As pessoas deste signo envolvem-se em confusões que, quase sempre, resultam em derramamento de sangue.",160]],"reading":[["Assinala desentendimento entre os filhos.",160],["Assinala que a pessoa fez Ifá sem a permissão de seu Olorí.",160],["Quando surge este signo, a pessoa que estiver jogando bate no próprio corpo e sopra em direção à porta da rua.",161]],"care":[],"stories":[["Foi por este caminho que Obatalá, depois de correr o mundo para verificar os sentimentos dos Babalawos, voltou muito triste com o que viu.",161]],"curiosities":[]},"ire":{"p":188,"text":"o renascimento e a renovação liberam as forças necessárias para a concretização de ideias e projetos."},"ibi":{"p":188,"text":"a falta de renovação impede a concretização de planos."}},"3:9":{"alias":"ODIKÁ","page":163,"phrase":"Odiká Okoloiu Opuá adifafun Orixaye tinxeme Aiyalorun. Obá nifá tinxemo Olofin Obá Orixaye adifafun Egun Oiyba Orun. Maferefun Xangô Orixaye, Obaye. Adifafun Oduduwa.","sections":{"representation":[["Este Odu ensinou o costume de apresentar os iyawos aos atabaques e a razão pele qual devem vestir-se de branco.",163],["Este Odu é muito destrutivo e não possui cabeça.",163]],"native":[["As pessoas deste Odu tomam borí com água do mar e peixe seco.",163]],"reading":[["Quando este Odu surge num itá, o Awo não deve marcá-lo, devendo substituí-lo, no opon, por Ogbetua ou Ejiogbe.",163],["Quando surge num atefá, é substituído porque, na verdade, significa um aprisionamento.",163],["Quando surge este Odu numa feitura de Ifá, a pessoa tem que assentar Oduduwa antes mesmo de sair do Igbodun de Ifá.",164]],"care":[["Quando este Odu surge num itá, o Awo não deve marcá-lo, devendo substituí-lo, no opon, por Ogbetua ou Ejiogbe.",163]],"stories":[],"curiosities":[]},"ire":{"p":188,"text":"a renovação conduz a mudanças externas radicais."},"ibi":{"p":188,"text":"a falta de renovação e o apego aos hábitos impedem as mudanças ou conduzem a mudanças drásticas no mundo externo."}},"3:10":{"alias":"ODISÁ","page":165,"phrase":"Odisá, Odi Mayere Mániania le yeré Iyalode mama wa ameiyá, wá yeré omó Oxunguere Iyá iedé babinú Omó Oxunguere fun mi xeré.","sections":{"representation":[["Este é o Odu das falsidades e dos enganos.",165],["Este é o signo do enforcado.",165],["Este é o Odu do espiritismo.",165]],"native":[["As pessoas deste Odu têm que acender lamparinas para Yemanjá, para que ela possa solucionar seus problemas.",165],["O awo deste Odu não procria em Ifá.",166],["As pessoas deste Odu são farsantes e gostam de usar os outros para atingirem seus objetivos.",166]],"reading":[["Assinala impotência sexual no homem.",165],["Assinala maldição lançada pela própria mãe, por um mal-feito qualquer.",165]],"care":[["Deve evitar caluniar ou roubar, para não ter que sair fugido de alguém, ou ver-se impedido de freqüentar algum lugar.",166]],"stories":[],"curiosities":[]},"ire":{"p":188,"text":"a renovação avigora a força interior e o status."},"ibi":{"p":188,"text":"a estagnação enfraquece o status e a força."}},"3:11":{"alias":"ODITURUPON","page":168,"phrase":"Odibatrupon Yabolé apu eté axikale xeyé, axikale kilé foloni owó kilé otó.","sections":{"representation":[],"native":[],"reading":[["Assinala dores no abdome e no corpo, principalmente durante a noite.",168],["Assinala influência de Eguns obsessores provocando doenças nas pernas e na barriga.",169]],"care":[["Em osogbo avisa que o Awo não deve assumir compromissos, pois ocorrerão sensíveis mudanças.",168],["Exige união de todos e determina que, se alguém se separar, não deve ser pranteado caso venha a morrer.",168]],"stories":[["Neste caminho Orunmilá recomendou ao homem que fizesse ebó com folhas da guiné, mas sua recomendação não foi atendida.",169]],"curiosities":[]},"ire":{"p":188,"text":"a renovação conduz ao crescimento e, eventualmente, à melhora da saúde."},"ibi":{"p":188,"text":"a estagnação ou o apego aos hábitos impede o crescimento e a cura."}},"3:12":{"alias":"ODITURÁ","page":170,"phrase":"Odi Atakofenió, Idi atá kole eiyn aparo oun tufujé loiun si adifafun Obalaxé lebó.","sections":{"representation":[["Este é um Odu de vícios e aberrações sexuais.",170]],"native":[],"reading":[["Indica que a pessoa trocou a sopeira de Orunmilá, mas que ele quer voltar à sua antiga casa.",170],["Fala de pessoas efeminadas que querem ser iniciadas em Ifá, envergonhando seus padrinhos.",170],["Assinala dores no peito e nas costas ocasionadas por problemas cardíacos.",171]],"care":[["Não deve batizar ninguém, pois a inveja criará um grande aborrecimento entre os compadres.",171]],"stories":[],"curiosities":[]},"ire":{"p":189,"text":"a renovação fortalece a visão e a conexão mística."},"ibi":{"p":189,"text":"mudanças arbitrárias ou o apego aos hábitos conduzem ao autoengano e à falta de visão."}},"3:13":{"alias":"ODIRETÊ","page":172,"phrase":"Odirete Awari Odi Olowó axukpa odoloro odiguim odafun Orunmilá orubó.","sections":{"representation":[],"native":[],"reading":[["Assinala fome e troca de cabeça.",172]],"care":[],"stories":[["Neste caminho, o touro, por fazer favores ao cão, tornou-se escravo para sempre.",172]],"curiosities":[]},"ire":{"p":189,"text":"a renovação conduz à determinação, à orientação e à felicidade."},"ibi":{"p":189,"text":"a estagnação e o apego impedem a orientação interior e conduzem à ruína."}},"3:14":{"alias":"ODIXE","page":174,"phrase":"Odixe, Idi Xe oun babalawo bombô xeketé, xeketé bombô.","sections":{"representation":[["Este Odu é filho de Odi com Oxe.",174],["Este Odu destrói a pessoa que, para poder vencer, tem que transformar-se num rei.",174]],"native":[["A pessoa deste Odu, antes de sair de casa, tem que lançar água na rua para espantar um Egun que a persegue.",175],["O Awo deste signo só pode ter uma mulher e tem que fazer sexo com ela todos os dias.",175]],"reading":[["Assinala infidelidade por parte da mulher.",174],["Assinala roubo contínuo, ás escondidas.",174],["Assinala enfermidades estomacais e renais, problemas endócrinos que impedem a geração de filhos.",174]],"care":[["Não deve viver em casa úmida porque irá adquirir dores nos ossos.",175]],"stories":[],"curiosities":[]},"ire":{"p":189,"text":"a renovação conduz à abundância e à conexão espiritual."},"ibi":{"p":189,"text":"a resistência à renovação leva à ganância, à perda e à falta de conexão espiritual."}},"3:15":{"alias":"ODIFUN","page":176,"phrase":"Odi Fumbó, Odi Fumbó Ará Oxalá. Ará Ile Aiye Moyerami Oxalá, odogun agba agó ará.","sections":{"representation":[["Este Odu determina que o ânus tenha mal-cheiro.",176]],"native":[],"reading":[["Assinala que a pessoa deseja partir.",176],["Indica que os filhos não reconhecem o sacrifício dos pais que, entristecidos, abandonam a casa.",176]],"care":[],"stories":[["Neste caminho o afilhado mata o padrinho.",176]],"curiosities":[]},"ire":{"p":190,"text":"a renovação conduz a uma revelação."},"ibi":{"p":190,"text":"resistir às renovações inviabiliza a conscientização e o cumprimento do destino."}},"4:4":{"alias":"IROSUN MEJI","page":178,"phrase":"Irosun Meji, Oiyerosun Apantaritá Bebé ojorokó to begbe loiokun.","sections":{"representation":[["Este Odu representa as profundezas da Terra.",179],["Este Odu gerou a mentira ao pretender ter domínio sobre o sangue e não possuir faca para fazê-lo escorrer.",180]],"native":[["Os filhos deste Odu costumam apresentar os olhos avermelhados e lacrimejantes.",179],["O Awo deste signo, para não morrer precocemente, tem que adquirir, sempre, novos conhecimentos sobre Ifá.",179],["O Awo deste Odu deve cultuar, com muito amor, o Orixá Oxun.",180]],"reading":[["Fala de acidentes, de violência, revoluções e derramamento de sangue.",178],["Quando surge numa consulta o Awo e todos os presentes têm que passar, por três vezes, efun sobre as pálpebras, para aliviar sua negatividade proveniente da cor vermelha.",179],["Assinala problemas cardíacos, inflamações nos olhos, problemas na circulação sangüínea, paralisia do sistema motor, inflamações cerebrais e intestinais.",180]],"care":[],"stories":[["Foi por este caminho que Xangô ensinou aos homens, as posições corretas dos dezesseis Odus Mejis.",179]],"curiosities":[["Sua cor é o vermelho-vinho e rege todas as coisas naturalmente vermelhas.",178]]},"ire":{"p":193,"text":"realização plena dos potenciais e conexão com a energia ancestral e familiar."},"ibi":{"p":193,"text":"conflitos familiares e com antepassados impedem a realização plena dos potenciais."}},"4:0":{"alias":"IROSOLOGBE","page":183,"phrase":"Iroso Umbó xeregún komaxé kotumbé arexanlé adifafun Orunmilá ti o fa maré akofá elebó, ekodidé elebó.","sections":{"representation":[["É um Odu de provas e de roubos.",184]],"native":[["Recolhe-se as vísceras comestíveis da cabra de Orunmilá, prepara-se com bastante tempero e dá-se ao Awo deste Odu para comer.",183],["Tem que fazer Ifá de graça às pessoas deste signo.",183]],"reading":[["Quando surge este signo pergunta-se logo se Orunmilá quer comer duas galinhas pretas.",183],["Assinala julgamento público e falsos testemunhos.",183],["Quando surge este Odu devolve-se a importância paga pela consulta.",183]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":161,"text":"o destino se cumpre com a orientação ou ajuda dos ancestrais. Esse Odu representa a vida que surge através da recriação e reen-carnação."},"ibi":{"p":161,"text":"seguir os passos dos ancestrais ou não os homenagear conduz à ruína. Esse Odu adverte que as consequências causadas pela desarmonia de uma pessoa com os seus antepassados podem ser negativas."}},"4:1":{"alias":"IROSOYEKÚ","page":185,"phrase":"Irosoyekú, Irosokalelu, ko ni awo efá abé lalá belé lelé maká dakpare ré Ifá Onibarabaniregun, awo Obayá pelé Ikú.","sections":{"representation":[["Neste signo nasceu mudança de vida.",185],["Este Odu é filho de Irosun e Oyeku.",185]],"native":[["O Awo deste signo tem que assentar Oduduwa.",186]],"reading":[["Assinala úlceras no estômago e falsa gravidez.",185],["Quando surge este signo, pode estar acusando a morte de um Babalawo.",186],["Assinala dificuldades que só serão vencidas com empenho e dedicação.",186]],"care":[["Não deve sair para a rua durante a noite.",185]],"stories":[],"curiosities":[]},"ire":{"p":172,"text":"o reconhecimento e a recriação encerram um ciclo. O reconhecimento, a experiência de vida, a reencarnação de ideias e visões encerram um ciclo."},"ibi":{"p":172,"text":"a resistência conduz à perda. Resistir ao desenvolvimento e à recriação em planos superiores conduz a perdas, bloqueando caminhos futuros."}},"4:2":{"alias":"IROSOIWORÍ","page":187,"phrase":"Iroso Iwori, Iroso ni baiye, ni gbaun, ni tenxé, ni alodafun ayo omó Odé. Mafarefun Xangô.","sections":{"representation":[["Este é o Odu dos carregadores e estivadores.",187],["É filho de Irosun e Iwori É signo de mal-agradecidos.",187],["Este Odu assinala problemas no estômago e no sangue.",188]],"native":[["Os filhos deste Odu têm propensão a adquirirem malária, por este motivo, devem precaver-se contra picadas de mosquitos.",187]],"reading":[["Assinala que a pessoa já não suporta a carga que leva às costas.",187],["Avisa que a pessoa dorme de um jeito e acorda de outro.",187]],"care":[["A pessoa não deve lançar mão daquilo que não lhe pertence.",187],["A pessoa não deve ajudar ninguém, pois não haverá reconhecimento nem gratidão pela ajuda.",188]],"stories":[["Neste caminho o camponês plantou uma palmeira desconhecida que, depois de crescida, criou tantos espinhos que, nem ele, conseguia colher os seus frutos.",188]],"curiosities":[]},"ire":{"p":179,"text":"o renascimento de um tema com um novo significado favorece a descoberta da identidade. Existe uma segunda chance; um tema ganha força com um novo sentido. Essa “reencarnação” conduz a uma nova identidade, a um novo sentido e uma nova interpretação de si próprio."},"ibi":{"p":179,"text":"não enfrentar um tema de uma forma diferente impede que uma transformação ocorra e que a identidade se desenvolva. Segundas chances não são aproveitadas. O acesso à própria identidade está bloqueado."}},"4:3":{"alias":"IROSODI","page":190,"phrase":"Irosodi mandulaiye ati Rintoxe oun omó Orunmilá. Adifafun Orunmilá kowaye.","sections":{"representation":[["Este Odu é filho de Irosun com Odi.",190],["Este é o Odu dos coletores de ervas.",190]],"native":[],"reading":[["Quando este Odu traz ire omó, prenuncia que, a pessoa, tem ou terá um filho que será a alegria de sua vida.",190],["Indica que a pessoa possui três inimigos renitentes e implacáveis.",191],["Assinala vertigens, a pessoa deve procurar um médico.",191]],"care":[["Não deve confiar em ninguém, muito menos nos parentes.",190],["Não deve pular buracos nem atravessar mangues para não ficar impotente.",191]],"stories":[],"curiosities":[]},"ire":{"p":186,"text":"a realização dos potenciais conduz à renovação."},"ibi":{"p":187,"text":"a resistência para realizar os potenciais impede a renovação. O tradicional, já conhecido, é agarrado com toda força, enquanto o novo é rejeitado."}},"4:5":{"alias":"IROSOWÓNRIN","page":192,"phrase":"Irosowónrin ababoru ona odo adifafun Orú Lejó eiyele oni oko dundun, akukó lebó, ewefá lebó.","sections":{"representation":[["Este Odu fala de um rei que está ameaçado de perder a coroa.",192],["É filho de Irosun e Owónrin.",192],["Este Odu assinala que a mulher tem um Egun que a ajuda para que tenha sucesso como prostituta, dando-lhe dinheiro e posição social, mas tirando-lhe qualquer possibilidade de contrair matrimônio.",192]],"native":[],"reading":[["Assinala toxicomania, da qual, a pessoa não tem forças para livrar-se.",192],["Indica que Yewá quer comer.",192],["Fala de abandono por parte dos familiares porque, a pessoa, sendo despreocupada com a vida, só quer saber de festas, não buscando meios que garantam sua própria subsistência.",193]],"care":[["O homem deve ter cuidado para não se ver envolvido em tragédias causadas pelas mulheres.",193],["Este signo é ire ajê7 Não deve dar as mãos à outras pessoas.",193]],"stories":[],"curiosities":[]},"ire":{"p":193,"text":"a concretização dos potenciais prepara para o enfrentamento do inesperado."},"ibi":{"p":193,"text":"a resistência ao destino conduz ao caos."}},"4:6":{"alias":"IROSOBARA","page":195,"phrase":"Irosobara iromagan opé ku iriwo Ikú ado, lodifá Kolará Oxá woni aiya tami omó fé Odu ni amabaxé kupá eure elebó.","sections":{"representation":[["Este Odu é filho de Irosun com Obará.",195]],"native":[],"reading":[["Assinala morte por envenenamento.",195],["Avisa sobre tragédias por causa de mulheres ou por coisas extraviadas.",195]],"care":[["A pessoa não deve dizer, a ninguém, para onde vai.",195],["A pessoa não deve usar roupas pretas.",195]],"stories":[],"curiosities":[]},"ire":{"p":194,"text":"a concretização dos potenciais leva à transformação e ao desenvolvimento do ego."},"ibi":{"p":194,"text":"a resistência ao destino conduz ao egoísmo."}},"4:7":{"alias":"IROSOKANRAN","page":197,"phrase":"Irosokanran kukuté kukú adifafun Maladê tinakayá Orunmilá Obarabaniregun.","sections":{"representation":[["Este Odu ordena que o Awo estude Ifá.",197],["É filho de Irosun com Okanran.",197],["Este é o signo da imprudência.",197]],"native":[],"reading":[["Assinala perseguição de Ikú.",197],["Assinala acidente na rua envolvendo a pessoa e um estranho.",197]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":194,"text":"a concretização dos potenciais e a conexão com a família favorecem novos começos."},"ibi":{"p":194,"text":"a resistência ao destino, à família e aos antepassados leva à isolação, bloqueando os caminhos do coração e de novas possibilidades."}},"4:8":{"alias":"IROSOGUNDÁ","page":199,"phrase":"Iroso Todá Obatalá mowa iyení. A lié bogbo Orixá ewi iyará okun. Olokun ore Oxá iyániá. Aguemam opá eni ina odenu eni Olokun abagba Obatalá lodafun Oxá Odonu, kaferefun Xangô.","sections":{"representation":[["Este Odu manda agradar Exú com um coco, água e uma vela.",199]],"native":[["O Awo deste Odu tem que ter cinco moedas de prata em cada uma de suas mãos de Ifá.",199]],"reading":[["Assinala cirurgia de coração.",199],["Fala de envolvimento em atividades comerciais.",199]],"care":[["A pessoa não deve fazer favores, pois não receberá nenhum agradecimento.",200]],"stories":[["Neste caminho nasceu a vindima.",199],["Neste caminho, quando se dá um galo a Elegbara, recolhem-se três penas da cauda da ave e deixa-se, por três dias, no igbá.",200]],"curiosities":[]},"ire":{"p":194,"text":"a concretização dos potenciais, a conexão familiar e com os antepassados e a assunção da responsabilidade pelo próprio destino eliminam barreiras, viabilizando a realização das exigências pessoais."},"ibi":{"p":194,"text":"a resistência ao destino e à família gera conflitos e disputas."}},"4:9":{"alias":"IROSOSÁ","page":202,"phrase":"Irososá Ifá pelé pelé lelé lile eguele wa guere manile ilá pupá Ologuin linxé ofoyude Olofin, mafarefun Xangô.","sections":{"representation":[["É filho de Irosun e de Osá.",202]],"native":[["Os filhos deste Odu têm pouca fé e costumam abandonar seus Orixás, esquecendose do juramento feito diante de Olorun de, trabalhando com eles, ajudar a humanidade.",202]],"reading":[],"care":[],"stories":[],"curiosities":[]},"ire":{"p":195,"text":"a concretização dos potenciais e a conexão familiar e ancestral conduzem a reviravoltas externas, rompendo amizades, carreiras ou projetos."},"ibi":{"p":195,"text":"a resistência à família e ao destino conduz ao caos incontrolado e a mudanças drásticas no mundo exterior."}},"4:10":{"alias":"IROSOKÁ","page":203,"phrase":"Irosoká bokalá, okalá, bokiká otatun, adifafun obó, akukó lebó.","sections":{"representation":[["Este Odu assinala traição.",203]],"native":[["O filho deste Odu tem que assentar Osain.",204]],"reading":[["Fala de irmãos que, embora tenham sido criados juntos, não se toleram e nem podem ver um ao outro.",203]],"care":[["A pessoa, para não sofrer um atentado fatal, não deve ir ao campo sem antes fazer ebó.",203],["Não deve se aborrecer com nada que lhe suceda.",203]],"stories":[["Foi por este Odu que Oxun trouxe o dinheiro e a riqueza à Terra.",203]],"curiosities":[]},"ire":{"p":195,"text":"a realização dos potenciais e a conexão ancestral e familiar conduzem à força interior, dando nova energia para a concretização de projetos."},"ibi":{"p":195,"text":"a resistência à família e ao destino conduz à instabilidade mental e psicológica, afetando a força interior."}},"4:11":{"alias":"IROSOTRUPON","page":205,"phrase":"Irosoturukpon tutu abeneri, Koiye Wanadoró. Ifá yokafun Yemanjá Obadorô Awo Ire Baiyani. Xangô Awo Maro eledé afafé lokoniedé wawá iyeré abebe laiye Ifá.","sections":{"representation":[["Este Odu é filho de Irosun e Oturukpon.",205],["Este Odu proíbe que seus filhos façam força.",205],["É um Odu de injustiças, lutas e falta de reconhecimento por parte das pessoas que são beneficiadas por favores.",205]],"native":[["Os filhos deste Odu não podem comer pombo.",206],["Se tiver outro Awo deste Odu, seu amigo, deve tratá-lo friamente, evitando que o visite.",206],["As pessoas deste Odu têm tendências para se portarem de forma cruel e brutal.",206]],"reading":[["Assinala roubos contínuos.",205],["Assinala o poder de clariaudiência dado por Olorun ao filho de Ogun e ao filho de Osain.",205],["Assinala desentendimentos dentro de casa.",205]],"care":[["O Awo que tiver um afilhado deste signo deve evitar que vá à sua casa pois, este afilhado, representa um grande perigo para ele.",206]],"stories":[],"curiosities":[]},"ire":{"p":195,"text":"a aceitação do destino e a harmonia familiar são a base para um novo crescimento e para a saúde."},"ibi":{"p":195,"text":"a resistência à família e os conflitos de âmbito familiar, como também a não aceitação do destino, impedem o crescimento, podendo conduzir a perdas e provocar doenças."}},"4:12":{"alias":"IROSOTURÁ","page":207,"phrase":"Iroso Turá nibé akani ikanijú olodafun Ogun nibatí, Ogun Olosilé, Orunmilá Kate nifá.","sections":{"representation":[["Este Odu serve de caminho para duas qualidades de Ogun: Ogun Alagbedé - ligado ao ferro, e Ogun Sondé - ligado ao cobre.",207],["É filho de Irosun com Otura.",207],["Este Odu proíbe, aos seus filhos, o consumo de carne de galo e de bebidas alcoólicas.",208]],"native":[["O Awo deste Odu tem que possuir um okpele de ferro do seu tamanho.",207]],"reading":[["Assinala inflamações no ventre e doenças nasais.",208],["Assinala problemas respiratórios, enfermidades na boca e frieza sexual.",208]],"care":[["Não deve tentar fazer coisas para as quais não tenha vocação.",208]],"stories":[],"curiosities":[]},"ire":{"p":196,"text":"a realização dos potenciais conduz a uma visão mística."},"ibi":{"p":196,"text":"a resistência ao destino conduz ao autoengano."}},"4:13":{"alias":"IROSORETÊ","page":210,"phrase":"Irosun unkuemí laterí Tuká aparo, ataré mesan, ewe enatorí, eiyé aparo, ataré metá, agbado luiyere merin aiye kaabá gbe gbe xerin xaió kanxá, gbe gbe torokô omodé tobariní.","sections":{"representation":[["Este Odu proíbe que se empreste dinheiro, porque é com o próprio dinheiro da pessoa que lhe fazem um feitiço.",210],["É filho de Irosun e de Irete.",210],["Este Odu ensina, às mães, que devem conduzir seus filhos pelas mãos.",210]],"native":[["O Awo deste signo, que não observa as interdições por ele determinadas, expõe-se a um grande perigo.",210]],"reading":[["Assinala o fim de uma casa e necessidades prementes, ocasionados provavelmente, pelo falecimento de um dos cônjuges.",211],["Assinala feitiços colocados na porta de casa.",211]],"care":[["A pessoa não deve atender a chamados para ir ao encontro de ninguém.",211],["A pessoa não deve emprestar dinheiro a quem quer que seja, não importando quem lhe peça.",211]],"stories":[],"curiosities":[]},"ire":{"p":196,"text":"a realização dos potenciais e a conexão familiar em harmonia viabilizam agir com determinação e conduzem à felicidade."},"ibi":{"p":196,"text":"a resistência ao destino e à família conduz ao azar e à passividade."}},"4:14":{"alias":"IROSOXE","page":212,"phrase":"Irosun Xe Olú jenjé adifafun Auré Linjó. Launjé okan akukó lebó. Oxá kelefun kitifun xawó adifafun Orunmilá.","sections":{"representation":[["Este signo é filho de Irosun e Oxe.",212],["Este é o caminho, através do qual, agem os Eguns.",212],["Este Odu proíbe que se chore por falta de dinheiro.",212]],"native":[],"reading":[["Prenuncia uma guerra para a qual a pessoa tem que estar preparada.",213],["Quando surge, pega-se uma brasa viva e coloca-se na porta de casa às 12 horas do dia.",213]],"care":[["Deve ter cuidado, pois há prenúncios de um incêndio em sua casa que começará pela cozinha.",213]],"stories":[["Foi por este caminho que os homens aprenderam a utilização dos óleos vegetais na culinária e na confecção de lamparinas.",212]],"curiosities":[]},"ire":{"p":196,"text":"a realização dos potenciais e a harmonia familiar conduzem à prosperidade, à plenitude e à conexão."},"ibi":{"p":196,"text":"as hesitações em relação ao destino e os conflitos familiares causam vazio, perdas e a falta de orientação."}},"4:15":{"alias":"IROSOFUN","page":215,"phrase":"Irosofun oxú oponi minoman agbado orilelé lori apatá ibunjó ni gbe xibú inbelotan oxe elepo gbaxugbu igbé larifá adifafun Oluwo.","sections":{"representation":[["Este é o signo da desconfiança.",215]],"native":[],"reading":[["Assinala traição entre irmãos.",215],["Fala de corrupção na família onde, um dos membros, é filho bastardo.",215],["Assinala fraqueza sexual no homem.",215]],"care":[],"stories":[["Foi por este caminho que Aganjú declarou guerra a Obatalá, pelo domínio das cabeças humanas.",215],["Neste caminho Obaluaye recebeu coroa.",216]],"curiosities":[]},"ire":{"p":197,"text":"a realização dos potenciais e a harmonia das relações familiares revelam os verdadeiros valores e prioridades."},"ibi":{"p":197,"text":"a resistência ao destino e as disputas familiares impedem que a revelação do destino seja vivenciada, atrapalhando as relações familiares. A família e os objetivos pessoais da vida fracassam."}},"5:5":{"alias":"OWÓNRIN MEJI","page":217,"phrase":"Owónrin Meji Baba Orogun, ni moún ni ori oún joko adifafun Akitifá, adifafun Aroni, mama forosile akitifá, adie sinkena elebo.","sections":{"representation":[["Este é um Odu feminino, representa a Terra e o submundo.",217],["Este Odu proíbe os seus filhos de comerem galinha d`angola, milho e gergelim (Sesamum indicum, Lin.).",217],["Este é o signo das salamandras que se alimentam de fogo obtendo, desta forma, o poder de mudarem de cor, mas que, apesar disto, possuem os corpos tão frios que podem apagar o fogo.",218]],"native":[["As pessoas deste Odu ficam atordoadas porque querem fazer mais coisas do que podem.",218],["As filhas deste Odu amam com muita sinceridade e são extremamente fiéis.",218],["O Awo deste signo tem que, periodicamente, colocar seu Ifá na casa onde fica assentado seu Egun protetor.",219]],"reading":[["Assinala enfermidades estomacais, como úlceras e dispepsias, além de tumores intestinais.",217],["Fala de um Egun que acompanha e ajuda a pessoa, mas que a mantém solitária, só permitindo que se aproxime de quem acreditar na sua existência.",218],["Quando este Odu surge numa consulta, a pessoa para quem tenha surgido deve permanecer, durante sete dias, sem sair de casa.",218]],"care":[],"stories":[["Neste caminho encontram-se três Ajés1que são: Ologbumole - O que viaja pelo caminho, Ologbumosá - O que voa, e Ologbumarepá - O que existe para matar.",218]],"curiosities":[]},"ire":{"p":200,"text":"a purificação interior e a reestruturação abrem espaço para novas perspectivas e para o desenvolvimento do ego."},"ibi":{"p":200,"text":"o caos interior conduz à desorientação, abre questões de sentido e gera dúvidas sobre si mesmo."}},"5:0":{"alias":"OWÓNRINXOGBE","page":221,"phrase":"Owónrinxogbe tabakoyú, baín, baín, Ikú baín baín jobatí adifafun oun Babalawo merindilogun tinlodifá ile Olofin.","sections":{"representation":[["Este signo é filho de Owónrin e Ogbe.",221],["Este Odu avisa que a pessoa deve policiar-se muito para não ser soberba e violenta.",222]],"native":[["Os filhos deste Odu não são amigos de ninguém pois tentam conquistar a mulher de seu maior amigo.",221],["Da mesma forma, os filhos deste Odu querem que todos se submetam aos seus caprichos.",222],["TRABALHO PARA LEVANTAR UMA PESSOA Obs.: Este trabalho pode ser utilizado sempre que necessário para os filhos deste Odu.",223]],"reading":[["Fala de um acidente provocando ferimentos graves na cabeça.",222],["Assinala problemas nas vistas que exigem o uso de óculos escuros.",222],["Assinala a existência de um compromisso muito desagradável que, para deixar de existir, exige que se aja com muita sabedoria e moderação, caso contrário, surgirão vários prejuízos.",222]],"care":[],"stories":[["Neste caminho Elegbara quer que todos façam a sua vontade.",222],["Foi neste caminho que Exú, usando um gorro preto de um lado e vermelho do outro, provocou uma discussão entre dois amigos que, a partir de então, tornaram-se inimigos para sempre.",222]],"curiosities":[]},"ire":{"p":162,"text":"o caos inesperado abre caminhos. Esse Odu ressalta a importância de confiar no poder da força purificadora das mudanças incon-troláveis."},"ibi":{"p":162,"text":"o caos inesperado conduz à confusão; o início de uma nova fase da vida não é favorável. Esse Odu adverte que acidentes ou surpresas desagradáveis podem interromper uma situação presente de forma repentina, bloqueando um novo começo."}},"5:1":{"alias":"OWÓNRIYEKU","page":225,"phrase":"Owónriyeku abori oribaxé kawo oribawá, ire axekun otá, elese Xangô marilawe ni Elegbara orukpale owó ogoró obori obori Oyeku, Inle eberen bawá Ifá kalerun Owórinyeku.","sections":{"representation":[["Este Odu é filho de Owónrin com Oyeku.",225],["Este Odu dá muito dinheiro, mas, se não se oferecer um galo a Elegbara, perde-se tudo pouco a pouco.",225]],"native":[],"reading":[["Prenuncia uma guerra que, para ser ganha, o Awo tem que se preparar muito bem.",225]],"care":[],"stories":[["Foi por este caminho que, pela primeira vez, a mulher levantou a mão contra o homem.",225]],"curiosities":[]},"ire":{"p":172,"text":"uma transformação interior conduz à conclusão de uma fase. Esse Odu representa reestruturações e redirecionamentos que interrompem fases e projetos."},"ibi":{"p":172,"text":"o caos leva à derrota. Turbulências internas e conflitos estão descontrolados e conduzem a interrupções e transformações agitadas e inconvenientes."}},"5:2":{"alias":"OWÓNRIWORÍ","page":227,"phrase":"Owónrin Tanxelá Owari Ofore oun joko iguerí aoforé ejá, Oxun adifafun Oriní está bain bain Awo Oxa Omi.","sections":{"representation":[["Este Odu é filho de Owónrin e Iwori.",227],["É um Odu de mentiras, de desprezo e de delações.",227],["Este é um Odu de bandidos e de pessoas que se envolvem em negócios sujos.",228]],"native":[["Por este motivo, o Awo deste Odu tem que ter a mulher de cor diferente da sua.",227],["A pessoa deste signo é desgovernada, precisa organizar-se, respeitar aos outros e às religiões que professem, não importando quais sejam.",229]],"reading":[],"care":[["Não deve usar perfumes muito ativos porque isto atrai osogbo.",228],["A pessoa encontra inúmeras dificuldades para cumprir suas obrigações com os Santos, mas não deve desesperar-se, as coisas serão feitas na hora certa.",228]],"stories":[["Neste caminho o dia e a noite fizeram um pacto.",227],["Neste caminho Olokun se fez comerciante e o búzio era o seu intermediário.",228]],"curiosities":[]},"ire":{"p":180,"text":"uma crise interior inesperada conduz à transformação e a uma fase de descoberta da identidade. Uma crise de sentido e a perda de controle da “vida interior” conduzem a uma fase de descoberta da identidade."},"ibi":{"p":180,"text":"reprimir a perda de controle e a crise de sentido dificulta a descoberta da identidade. Há uma forte pressão interior, uma repressão de questões de sentido que devem ser enfrentadas. O perigo da perda de controle e da crise de identidade não é enxergado."}},"5:3":{"alias":"OWÓNRINSODI","page":231,"phrase":"Owónrin ni Sodí Ariré leparí kosobo tolepani adifafun Awo Axelu finxomé olojá.","sections":{"representation":[["Este Odu é filho de Owónrin e Odi.",231]],"native":[],"reading":[["Fala de uma mulher que roubou o marido de outra.",231],["Assinala problemas com a justiça.",232]],"care":[["Não deve iniciar algo que não possa terminar.",231],["Não deve acreditar que ninguém possa lhe causar algum malefício.",231]],"stories":[["Foi neste caminho que nasceu Odé, o Orixá caçador.",231],["Neste caminho se faz ebó com carne podre.",232]],"curiosities":[]},"ire":{"p":187,"text":"uma mudança interna inesperada e a consciência conduzem à renovação ou ao início bem-sucedido de um negócio."},"ibi":{"p":187,"text":"mudanças inesperadas conduzem à perda de controle e à volta a antigos hábitos."}},"5:4":{"alias":"OWÓNRIROSO","page":233,"phrase":"Owónrinroso Ogun ati Elegbara Awo nifá lese Olofin, Orunmilá ati Xangô unbó wariyo odara mi dara. Omó Olofin ofo Leí toxú Arajé lodafun Orunmilá kaferefun pinado.","sections":{"representation":[["Este signo de Ifá é filho de Owónrin e Iroso.",233],["Este Odu fala de feitiços e amarrações.",234],["Este Odu preside as consultas com os espíritos.",234]],"native":[["O Ôsun7 do Awo deste Odu tem que ser do seu tamanho.",233],["Quando o Awo deste Odu oferece galinha a Orunmilá tem que, antes, salpicar ataré moído dentro do igbá.",234],["O eleké do Awo deste signo leva um ekodidé amarrado.",234]],"reading":[["Quando surge este Odu numa consulta o Awo abraça o consulente e dá graças a Orunmilá, a Xangô e a Obatalá.",233],["Quando este Odu surge para um Babalawo, ele tem que oferecer duas galinhas ao seu Ifá.",234],["Assinala que o Awo vai se separar de seus mais velhos.",234]],"care":[],"stories":[["Foi por este caminho que Yemanjá surpreendeu Orunmilá com Oxun, dentro de um poço rodeado de cabaças.",233],["Neste caminho Orunmilá tirou de Elegbara o direito de matar qualquer animal.",234]],"curiosities":[]},"ire":{"p":193,"text":"uma mudança inesperada no estado de espírito e na sensibilidade da pessoa abre o caminho para a concretização dos potenciais."},"ibi":{"p":193,"text":"o caos interno conduz à isolação familiar e dos antepassados, impedindo a plena realização dos potenciais."}},"5:6":{"alias":"OWÓNRINBARA","page":235,"phrase":"Owónrinbara puju ani losure kuripá igbá eni lowó oto Obara opopá eni logué oruwá koto koto ofiko kodie adifafun Bebé Orunmolé, ounkó, akukan, eiyele lebó.","sections":{"representation":[["Este é o Odu gerado pelo encontro de Owónrin e Obara.",235],["É um Odu que determina muito trabalho e dificuldades, mas, se a pessoa seguir corretamente as orientações dos Orixás e dos Eguns, as dificuldades tendem a desaparecer, ficando o signo em ire.",235]],"native":[["Para alcançar o poder o Awo deste signo tem que colocar, dentro do seu IgbaOsaiyn, um peixe bagre, e fazer o assentamento de seus Guias no meio de um pé de cabaceira.",236]],"reading":[],"care":[],"stories":[],"curiosities":[["Tudo isto está determinado neste signo que é também chamado \"Caminho de Bohio\".",236]]},"ire":{"p":200,"text":"uma revolução interior conduz à transformação e à liberação do ego."},"ibi":{"p":200,"text":"a desorientação e a perda de autoconfiança conduzem a uma espiral negativa do ego e a substituições compensatórias."}},"5:7":{"alias":"OWÓNRINKANRAN","page":237,"phrase":"Owónrin Pokanran Okana apuari aporón elebó animarú ebó oun babalawo lodafun eri lowó le ejá okue eran padán ni ansere joko Orunmilá pukuiye poran adifafun aombi akukó, eiyelé lebó. Maroraende abo, eure, eiyele lebo.","sections":{"representation":[["Este Odu é filho de Owónrin e Okanran.",237],["Este signo recomenda que a pessoa se afaste antes que a ponham para correr.",237]],"native":[],"reading":[["Assinala que um acontecimento, que tanto pode ser prejudicial quanto benéfico, já está a caminho.",237],["Assinala a existência de documentos ocultos ou atrapalhados.",237],["Indica, nas mulheres, suspensão precoce do fluxo menstrual.",237]],"care":[["A pessoa não deve se deixar arrastar pelos instintos nem pelo orgulho.",237]],"stories":[],"curiosities":[]},"ire":{"p":201,"text":"uma mudança inesperada abre o caminho para novos começos. A reorientação interior e a autoavaliação conduzem a novos amores, amizades e temas do coração."},"ibi":{"p":201,"text":"uma crise interior conduz ao isolamento, atrapalhando os assuntos do coração e levando boas oportunidades ao fracasso."}},"5:8":{"alias":"OWÓNRINGUNDÁ","page":239,"phrase":"Owónringundá Olofin apatakin Imolé Alakaiye osin bogbo Imolé. Olofin Axiro Egungun Awo Umbó axire ile Ifá. Igbo oro Obinin bidajun axiré Orun Anoná.","sections":{"representation":[["É filho de Owónrin com Ogundá.",239],["Este Odu fala de um menino bonito que ficava na janela de uma bela casa e que agora, a janela, que antes era baixa, ficou muito alta.",240]],"native":[],"reading":[["Quando este Odu surge para um consulente significa que esta pessoa não acredita nem respeita os adivinhos.",239],["Assinala dívidas com Omolú que devem ser pagas com muito respeito e boa vontade.",239]],"care":[["Se o cliente for homem, deve evitar qualquer tipo de problema com as mulheres.",240]],"stories":[["Neste caminho os débitos de amor são quitados.",240]],"curiosities":[]},"ire":{"p":201,"text":"uma revolução interior conduz à força de vontade e à força de ação, que são necessárias para a concretização de ideias, desejos, exigências e valores."},"ibi":{"p":201,"text":"conflitos internos vêm à tona, conduzindo a discussões interiores e exteriores, ou à passividade e à falta de força de ação."}},"5:9":{"alias":"OWÓNRINBOSÁ","page":241,"phrase":"Owónrinbosá ko pa to lotá ko ré to Owo Logunasiyeni lowo Orunmilá, akukó, adié, lebo. Owónrinbosá Bomosá adifafun Okun ato Obatalá. Ifá foré ire omó Exú ati Olofin.","sections":{"representation":[["Este Odu é filho de Owónrin com Osá.",241],["Este Odu fala de um rei que tinha muitos inimigos porque não era natural do país em que reinava.",242]],"native":[],"reading":[["Assinala problemas com a justiça, onde a pessoa é responsabilizada por uma tentativa de suicídio cometida por alguém.",241]],"care":[["A pessoa não deve sair de casa depois das 24 horas.",241]],"stories":[["Neste caminho os inimigos não queriam que a mulher de Orunmilá desse à luz.",241]],"curiosities":[]},"ire":{"p":202,"text":"uma revolução interior conduz a uma mudança exterior. A reorientação interior gera condições positivas inesperadas e êxitos no mundo exterior – de projetos, relacionamentos, entre outros."},"ibi":{"p":202,"text":"a resistência à transformação interior conduz à fragilidade de condições externas – como relacionamentos, projetos, etc."}},"5:10":{"alias":"OWÓNRINBIKÁ","page":243,"phrase":"Owónrinbiká otobale ademi ikabale adika awi adifafun ote tinxomo boixe tinxobo abure Eka Ada omó Olofin.","sections":{"representation":[["Este Odu é filho de Owónrin e Iká.",243]],"native":[["O Awo deste Odu também pode consultar com grãos de milho no lugar dos ikins.",243],["SEGREDO DESTE ODU As pessoas deste signo têm que assentar Osain num vaso de barro pintado com os seguintes signos de Ifá: Oxetura, Oxewónrin, Owónrinbiká e Oturaxe.",244]],"reading":[["Assinala disputa entre dois Awos por uma mulher.",243]],"care":[["Não deve se zangar por este motivo porque as visitas só lhe aumentam a sorte.",244]],"stories":[],"curiosities":[]},"ire":{"p":202,"text":"uma revolução interior conduz à força interior."},"ibi":{"p":202,"text":"o caos interior desestabiliza a força interior, a autoestima e o status da pessoa."}},"5:11":{"alias":"OWÓNRINTRUPON","page":245,"phrase":"Owónrintrupon iká kalere okolixirawo Omó Oluwo Popo. Viti Babaré ni Ifá Majeré Awo Omó Osain Moruburo. Owónrintrupon omó Okofá lawo gurande Ifá ni orefun Oiyá.","sections":{"representation":[["Este Odu é filho de Owónrin e Oturukpon.",245]],"native":[["O filho deste Odu tem que assentar Oiyá e Ibeji.",245],["O Awo deste signo tem que ensinar tudo o que sabe de Ifá aos seus afilhados, pois um deles o salvará de um grande perigo.",245],["Da mesma forma, os filhos deste Odu não podem entrar em grutas nem residir em casebres.",246]],"reading":[["Assinala uma tragédia provocada por ciúmes.",246]],"care":[["Não deve lançar maldições nem comer na casa de ninguém.",246],["Não deve maltratar os subalternos.",246]],"stories":[],"curiosities":[]},"ire":{"p":202,"text":"uma mudança inesperada conduz à necessidade de proteger-se de doenças."},"ibi":{"p":202,"text":"uma mudança inesperada provoca uma doença."}},"5:12":{"alias":"OWÓNRINTURÁ","page":247,"phrase":"Owónrinturá, Owónrin Alaketu xatiki nabo Olú Ará adifafun Orunmilá, tinxawó iyé olokumi lodafun Obanlá.","sections":{"representation":[["Este é o filho de Owónrin com Otura.",247]],"native":[["A segurança do filho deste Odu está em assentar Olokun.",247],["Quando morre um pavão na casa do Awo deste signo, tem-se que fazer itutu10 para o animal.",248]],"reading":[["Assinala domínio do padrinho sobre o afilhado e o desprezo deste pelos seus conselhos.",247]],"care":[],"stories":[["Foi por este Odu que, pela primeira vez, se esquartejou um corpo humano.",247]],"curiosities":[]},"ire":{"p":203,"text":"uma revolução interior abre os caminhos para a força da visão mística."},"ibi":{"p":203,"text":"o caos interior conduz a um mundo de ilusões e ao autoengano."}},"5:13":{"alias":"OWÓNRINBIRETE","page":249,"phrase":"Owónrinbirete akiti Babá Opeku adifafun Olofin. Apari adifafun Palakorei.","sections":{"representation":[["Este Odu é filho de Owónrin e de Irete.",249]],"native":[],"reading":[],"care":[["Deve evitar fazer as coisas ruins que lhe ocorrem para não ter problemas com a justiça.",250]],"stories":[],"curiosities":[]},"ire":{"p":203,"text":"uma revolução interior fortalece a determinação."},"ibi":{"p":203,"text":"o caos interior conduz à paralisia e à submissão."}},"5:14":{"alias":"OWÓNRINBOXE","page":251,"phrase":"Owónrinboxe Omó ni xé kaferefun Yemanjá ati Obatalá Babá Boefá Kolugo pudoinká lafexé korubó intori xeke losá Obinin Kamibaxé amarora Orixá Elegbara obofé Ogun Jobi.","sections":{"representation":[["Este Odu é filho de Owónrin e Oxe.",251]],"native":[["Para os Awo deste Odu, receber Igbadu11 é coisa vital.",252]],"reading":[],"care":[["Não deve ouvir tais conselhos para não se tornar extremamente infeliz.",252]],"stories":[],"curiosities":[]},"ire":{"p":203,"text":"uma revolução interior conduz à conexão espiritual e à plenitude."},"ibi":{"p":203,"text":"o caos interior conduz ao vazio, ao fracasso e à perda de confiança."}},"5:15":{"alias":"OWÓNRINBOFUN","page":253,"phrase":"Owónrinbofun Ire ajê omi bebe Onixegun jidú Obajelerú adifafun Akoni Yemanjá lodafun Apajá ati Obatalá.","sections":{"representation":[["Este Odu é filho de Owónrin e de Ofun.",253],["Este é o motivo dos seus fracassos.",254]],"native":[],"reading":[["Assinala, para a mulher, abandono pessoal.",253],["Assinala risco de doenças no sangue e falsa gravidez.",254]],"care":[["Não deve ser curiosa nem meter as mãos no que não lhe concerne para não sair machucada.",253],["Não deve discutir nem se alterar para não prejudicar a própria saúde.",254]],"stories":[],"curiosities":[]},"ire":{"p":204,"text":"uma revolução interior conduz à revelação."},"ibi":{"p":204,"text":"uma crise interior e o caos causam o fracasso. O destino não se cumpre, pois tanto as dúvidas em relação a si próprio, como também a desorientação, impedem a clareza de ideias."}},"6:6":{"alias":"OBARA MEJI","page":255,"phrase":"Obara Meji Oni Olabara ejebara kikate Awo Komakate Arajé Komakate ará Orun adafun bogbo Eiekó orofó lorubó bogbo tunuyen.","sections":{"representation":[["Este signo é masculino, filho de Olofin e de Anaxé.",255],["É um Odu de desmoralização e perda de prestígio.",256],["É um Odu de enganos e tragédias.",256]],"native":[],"reading":[["Fala de traição e de insegurança.",256],["Assinala traição e engano dentro de casa.",256],["Indica que a pessoa é vítima de injúrias e calúnias e que seu próprio cônjuge a engana.",256]],"care":[["A pessoa não deve demorar a fazer o que planeja sob pena de, quando resolver fazer, já ser demasiadamente tarde.",257]],"stories":[["Foi neste caminho que as mulheres aprenderam a fazer sexo oral.",255],["Neste caminho Osain come ajá.",255],["Foi aqui que o gato serviu a Orunmilá e a Obatalá.",255]],"curiosities":[["Seu nome significa \"Dois Reis\".",255]]},"ire":{"p":207,"text":"transformação interior e superação do ego."},"ibi":{"p":207,"text":"egoísmo e narcisismo. O processo de transformação falha, ou conduz a um caminho errado."}},"6:0":{"alias":"OBARABOGBE","page":259,"phrase":"Obarabogbe lantosi Omódu omi ke eboada felebó. Okilanfirú ekú, okilanfirú ejá, okilanfiru jio-jio. To iban Exú Sokoboni elebó.","sections":{"representation":[["Este Odu é filho de Obara e de Ogbe.",259],["Este Odu fala de encobrimento de coisas más.",260]],"native":[["As pessoas deste signo têm problemas com seus vizinhos e vivem cercadas de inimigos.",259]],"reading":[],"care":[],"stories":[["Neste caminho, por serem permissivistas, Obatalá e Xangô foram acusados de serem efeminados.",259]],"curiosities":[]},"ire":{"p":162,"text":"a transformação e a humildade abrem novos caminhos. Esse Odu representa a possibilidade de encontrar novos caminhos e de segui-los de forma adequada, através da superação do ego."},"ibi":{"p":162,"text":"o ego bloqueia a passagem para novos caminhos da vida. Esse Odu adverte que o egoísmo e o egocentrismo cegam, abrindo as portas para os caminhos inadequados e impedindo que um julgamento correto seja feito."}},"6:1":{"alias":"OBARAYEKU","page":261,"phrase":"Obarayekú kekeré omá Ajé, eri omi Ajé Aibo, omá Ajé Apuparere, apupe gogo Ikú opawéwé, Ikú apaxeré, Orunmilá lorugbo idá agutan, ebewá ajapá, akukó lebó.","sections":{"representation":[["Este Odu resulta do encontro de Obara e Oyeku.",261],["Este signo condena a mulher a viver atrelada ao homem.",261],["Este Odu proíbe que seus filhos subam em escadas de mão e que carreguem peso.",262]],"native":[["Os filhos deste Odu são proibidos de usarem meias marrons.",261],["No Ifá do Awo deste Odu tem que ter um punhal e uma mão de madeira.",261]],"reading":[["Assinala problemas no trabalho.",261],["Assinala perda de memória.",261]],"care":[],"stories":[["Foi neste caminho que Obatalá mandou chamar os macacos para dar-lhes Axe, mas eles, por se acharem cheios de defeitos, não compareceram diante do Orixá.",261],["Neste caminho Olofin ia colher ervas aromáticas e, extasiando-se com seus perfumes, deixava-se levar pelas fantasias da imaginação.",261],["Neste caminho o ajapá foi amaldiçoado.",262]],"curiosities":[]},"ire":{"p":172,"text":"a transformação do ego viabiliza a conclusão de temas. Uma nova consciência conduz a decisões claras e a separações."},"ibi":{"p":173,"text":"o ego conduz a perdas. O egocentrismo e a falta de disposição para transformar-se bloqueiam o êxito futuro."}},"6:2":{"alias":"OBARAIWORÍ","page":263,"phrase":"Obara Kori Anko nibe eran ko ekú ibá ewefá elebó. Obaraiworí adifafun Exú.","sections":{"representation":[["Este Odu resulta da interação de Obara com Iwori.",263]],"native":[["Os filhos deste Odu têm que assentar Osain e Oduduwa.",264]],"reading":[],"care":[],"stories":[],"curiosities":[]},"ire":{"p":180,"text":"uma transformação do ego conduz a uma nova identidade. O esforço e o preparo favorecem a formação de um “bom caráter”."},"ibi":{"p":180,"text":"o egoísmo e o egocentrismo impedem o desenvolvimento e a evolução da identidade."}},"6:3":{"alias":"OBARADI","page":265,"phrase":"Obaradi, Bara, Baradi, Bara, Baradi adifafun Awo Olubó okoroko omá xokojo éuré, owo lo meni elebó.","sections":{"representation":[["Este Odu é filho de Obara e Odi.",265],["Este é um signo de reflexão.",265]],"native":[["O Awo deste signo tem que assentar Iyá Kolobá e Oxá Bukan.",265],["O Awo deste Odu tem que beber água da quartinha da Oxun com obí ralado para tirar o vento ruim de seus caminhos.",266]],"reading":[["Fala de uma mulher de nádegas proeminentes e dente de ouro.",265],["Fala de uma menina que se perderá se não lhe puserem freio.",265],["Assinala impotência sexual no homem.",265]],"care":[["Não deve querer saber de tudo.",265],["A pessoa não deve revelar seus planos a ninguém, pois a inveja porá tudo a perder.",265]],"stories":[["Foi aqui que Olofin comeu cabra.",265]],"curiosities":[]},"ire":{"p":187,"text":"a força interior viabiliza a renovação."},"ibi":{"p":187,"text":"o ego impede a renovação."}},"6:4":{"alias":"OBARAKOSO","page":267,"phrase":"Obarakoso, Ifá duró, Ifá nire irekun kaferefun Orunmilá, Exú ati Ogun.","sections":{"representation":[["Este Odu é filho de Obara e Irosun.",267],["Este Odu indica que existe um assentamento de Omolú que foi tomado por um Egun.",267]],"native":[["O Awo deste Odu tem que receber pinado1rapidamente para que possa prosperar.",267]],"reading":[],"care":[["Quando sair não deve dizer aonde vai.",268]],"stories":[["Foi por este caminho que Orunmilá visitou a terra dos anaí.",267],["Neste caminho forra-se Osain com couro de tigre.",268]],"curiosities":[]},"ire":{"p":194,"text":"a transformação viabiliza a concretização dos potenciais e a conexão com a família e os antepassados."},"ibi":{"p":194,"text":"o egoísmo e o egocentrismo conduzem à resistência aos antepassados, à família e à encarnação."}},"6:5":{"alias":"OBARAWÓRIN","page":269,"phrase":"Obarawónrin, Obaranifé, juju omó Oluwo Atopolo. Obara Kelejé, Obara ni Wani, alejó otori laye osogbo. Oni Wani Elegbara Kubeyekun. Obara Oni Wani kotokun.","sections":{"representation":[["Este Odu é filho de Obara e Owónrin.",269],["Este é um signo de fracassos.",269]],"native":[],"reading":[["Quando surge o Awo tem que oferecer coco e água fresca a Xangô e, depois de três dias, um galo a Elegbara.",269]],"care":[],"stories":[["Neste caminho, quando um médio recebe um espírito, deve-se cobri-lo com um pano branco para que o espírito manifestado possa falar tudo o que tem a revelar.",269],["Foi neste caminho que Xangô foi mandado para o exílio e todos os seus seguidores foram humilhados e perseguidos.",269]],"curiosities":[]}},"6:7":{"alias":"OBARAKANA","page":271,"phrase":"Obarakana lodafun Orunmilá oni pate ki kodapá. Exú Ifá Elegbara latemi atele awo ati iwe esse nitasi adifafun Obara baniregun unbati la yolá ibeneku Osun ixú, agbado, akukó elebó. Ifá ni kaferefun Xangô ati Oiyá.","sections":{"representation":[["Este Odu é filho de Obara e Okanran.",271],["Este Odu indica que a pessoa não sabe o que quer nem que caminho deve tomar na vida.",272]],"native":[["Para salvar a própria cabeça, o filho deste Odu tem que oferecer um carneiro para Xangô.",271],["Quando o Awo deste Odu receber pinado coloca, sobre a cabeça do carneiro, um eleké de Obatalá, um de Elegbara, um de Xangô e um de Orunmilá.",271],["O Awo deste signo deverá consagrar uma mão pequena de Ifá3 Deverá ter sempre uma tigelinha cheia de moedas ao lado de seu Elegbara e um inhame diante de Orunmilá.",272]],"reading":[],"care":[["Quando este signo surge para alguém na iniciação de Awofakan, é preciso que se tenha muita atenção porque, se o iniciando for filho de Xangô, não deve ser consagrado como Babalawo porque Xangô não dá permissão.",271]],"stories":[["Neste caminho Xangô foi vendado e preso dentro de um quarto onde ficou, por muito tempo, sem saber o que fazer.",272]],"curiosities":[]},"ire":{"p":207,"text":"uma transformação interior abre novas oportunidades e o coração."},"ibi":{"p":207,"text":"o egoísmo conduz ao isolamento, à falta de empatia e à insensibilidade. Novas oportunidades são perdidas e interrompidas."}},"6:8":{"alias":"OBARAGUNDÁ","page":273,"phrase":"Obaragundá, Xangô abiti intori Oiyá, intori Ogun Ofé ni omun, intori otí ni Obinin ofo iná lobá kaferefun Oxun, lodafun Xangô ati Oiyá.","sections":{"representation":[["Este Odu é filho de Obará e Ogundá.",273],["Este Odu fala do cisne que passa pelo lodo e não se suja.",273]],"native":[],"reading":[["Fala de cirurgias delicadas, de tumores na cabeça que tanto podem ser internos como externos.",273],["Avisa que a pessoa ficará sem ter onde morar.",273],["Assinala que a pessoa cometeu um incesto.",273]],"care":[],"stories":[["Neste caminho Ogun preparou uma armadilha para capturar um homem que havia roubado uma de suas esposas.",274]],"curiosities":[]},"ire":{"p":208,"text":"uma transformação interior e a humildade conduzem à resolução de conflitos e à realização de desejos e valores pessoais."},"ibi":{"p":208,"text":"o egoísmo e a estagnação conduzem a conflitos e disputas."}},"6:9":{"alias":"OBARASÁ","page":275,"phrase":"Obarasá kukute kuku adifá joko kunie, adifá joko koni nibóguelê aroro ló uró sikotá ekodidé, eiyele meji.","sections":{"representation":[["Este Odu é filho de Obará e Osá.",275]],"native":[],"reading":[["Assinala escândalo e descrédito público.",275]],"care":[],"stories":[["Neste caminho cobre-se Orunmilá com um pano branco, oferece-se um veado a Elegbara e coloca-se, junto dele, uma frigideira com água.",275]],"curiosities":[]},"ire":{"p":208,"text":"uma transformação interior conduz a mudanças exteriores. Uma nova consciência e a humildade conduzem a mudanças radicais e à reorganização de relações externas."},"ibi":{"p":208,"text":"o egoísmo e a estagnação conduzem ao caos e à interrupção de projetos, relacionamentos ou fases."}},"6:10":{"alias":"OBARAKÁ","page":277,"phrase":"Obara Kasiká legun omodé Olofin. Ika lele aramanama akatampó adifafun Oleyé, adifafun Exiyé omó Olofin Agboran limelé akati axetelewa Olofin. Xangô unbó wa belefunade Olofin lodafun agungun Orun ni malé.","sections":{"representation":[["Este Odu é filho de Obara e Iká.",277],["Este Odu assinala que as pessoas recorrem e utilizam a ajuda dos adivinhos e, depois que se pegam servidas, saem falando mal por qualquer motivo e tornam-se suas inimigas.",277]],"native":[],"reading":[["Assinala traição dos filhos-de-Santo ou dos afilhados.",277],["Assinala que, nas consagrações de Ifá, a presença de Olofin é imprescindível.",277]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":208,"text":"uma transformação interior conduz à força interior."},"ibi":{"p":208,"text":"o egoísmo e a estagnação interior conduzem à perda de soberania e da autoconfiança."}},"6:11":{"alias":"OBARATRUKPON","page":279,"phrase":"Obara Tunbun niendé adifafun Babá Lontobi omá aretó yu ebó omá suneke nangá.","sections":{"representation":[["Este Odu resulta do encontro de Obara e Oturukpon.",279]],"native":[],"reading":[["Quando surge este signo se dá peixe fresco a Ogun e duas galinhas para Orunmilá comer junto de Oiyá.",280]],"care":[["A pessoa não deve comer na casa dos outros para que não lhe dêem algum feitiço no alimento.",280],["Não deve comer coco nem arroz.",280],["A pessoa não deve se impor pela força bruta.",280]],"stories":[["Foi neste caminho que Ajapá Tiroko perdeu uma filha.",280]],"curiosities":[]},"ire":{"p":209,"text":"uma transformação interior favorece o crescimento e a saúde."},"ibi":{"p":209,"text":"o egoísmo e a falta de disposição para a transformação interior atrapalham o crescimento, podendo prejudicar a saúde."}},"6:12":{"alias":"OBARATURA","page":281,"phrase":"Obara Kuxiyo aké euré ahoboni bo uro gulanda Barabaniregun Orunmilá Lorugbo.","sections":{"representation":[["Este Odu é filho de Obara e Otura.",281]],"native":[["O filho deste Odu não pode pegar cabras de frente nem pela cauda a não ser se for oferecê-la ao seu Ifá.",282]],"reading":[["Fala de caldeirões de bruxos, de macumbeiros e feiticeiros.",281],["Fala de dureza de coração.",281],["Assinala a chegada de uma boa notícia.",282]],"care":[["Se for mulher, não deve relaxar com sua aparência pessoal por causa dos problemas da vida.",281]],"stories":[["Neste caminho oferece-se, a Orunmilá, ewe onibara (Melão de São Caetano) com suas frutas.",282]],"curiosities":[]},"ire":{"p":209,"text":"uma transformação interior e a humildade abrem as portas para visões interiores."},"ibi":{"p":209,"text":"o egoísmo conduz ao autoengano."}},"6:13":{"alias":"OBARAKETE","page":283,"phrase":"Obarakete Ifá Oni retewá adifafun axewitá intori Awá xobu lori okuni sini Olokun.","sections":{"representation":[["Este Odu é filho de Obara e Irete.",283],["Este é o Odu da vitória régia.",283]],"native":[],"reading":[],"care":[["Não deve dar ouvidos a comentários para não se envolver numa desgraça.",284],["Evite o bisturi dos médicos.",284]],"stories":[],"curiosities":[]},"ire":{"p":209,"text":"uma transformação interior conduz à determinação"},"ibi":{"p":209,"text":"o egoísmo conduz à subordinação. lrete – Obara"}},"6:14":{"alias":"OBARAXE","page":285,"phrase":"Obaraxe Ofuyere, Obara Xeke mi xeké Odilará korubó oguxé. Awo Obara Obaxe, Awo Eiyele, Awo Aun, Awo kaferefun Obá, kaferefun Odu, kaferefun Orunmilá.","sections":{"representation":[["Este Odu resulta da interação de Obara com Oxe É o caminho, através do qual, o discípulo observa o mestre.",285],["Este Odu fala do desenvolvimento do sexto sentido.",286]],"native":[],"reading":[["Fala de ciúmes e de calúnia.",285]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":210,"text":"uma transformação interior conduz à prosperidade, à plenitude e à conexão."},"ibi":{"p":210,"text":"o egoísmo e a estagnação conduzem à ganância, ao vazio e à falta de conexão espiritual."}},"6:15":{"alias":"OBARAFUN","page":287,"phrase":"Obarafun iki Awo Inle adó irere, Awo ibá asesi adabá, Awo bó eté etá obinin xawo ibá iro adifafun Olofin luba omó ada ibi abeboadie meji elebó.","sections":{"representation":[["Este Odu é filho de Obara e Ofun.",287]],"native":[["A pessoa deste signo não pode comer inhame nem farinha.",287]],"reading":[["Fala de um filho que saiu de casa por causa de um irmão.",287],["Fala de nervosismo e intranqüilidade.",287],["Fala de danos causados pela ingestão de alimentos.",287]],"care":[],"stories":[["Neste caminho o Awo sempre terá o que fazer.",287]],"curiosities":[]},"ibi":{"p":210,"text":"o egoísmo e a estagnação impedem que o destino se cumpra, revelando o fracasso dos grandes objetivos."}},"7:7":{"alias":"OKANRAN MEJI","page":289,"phrase":"Okanran Meji, Oni Kanran Okanran ni okute, Okanran Meji ni Exú Bi Eboadá, Exú Bi pakikó, adie onadere Okanran Meji. Okanran ire Ifá, Okanran Ire Awo, Okanran ire Xangô, Okanran ire Exú Bi okan ni. Oni Kanran unbatí Osode botalokununló.","sections":{"representation":[["Este é um Odu feminino, filho de Sedikoroú e Ajantakú.",289],["Representa coisas encadeadas, uma sucessão de acontecimentos a partir de uma ocorrência significativa.",289],["Este é o caminho do perdão.",290]],"native":[["Os filhos deste Odu são grandes oradores, conseguem convencer através da palavra.",289],["O Awo deste signo tem jogar no mar uma corrente do seu tamanho.",291]],"reading":[["Prenuncia a morte repentina de três pessoas.",290],["Quando este Odu surge em Atefá, a pessoa tem que fazer Ifá rapidamente para que não venha a morrer.",290],["Assinala dores nas costas e nos rins.",290]],"care":[["Não deve beber nenhum tipo de bebida alcoólica, por mais suave que seja.",290]],"stories":[["Neste caminho os mortos preparam armadilhas para os vivos.",290],["Foi neste caminho que Elegbara comeu akukó pela primeira vez.",291]],"curiosities":[]},"ire":{"p":212,"text":"o coração está aberto, com empatia. Novas relações e novos projetos têm sentido e relevância."},"ibi":{"p":212,"text":"o coração está fechado, há frieza e isolamento social. Os projetos seguem apenas objetivos materiais e tendem a fracassar. Oportunidades e pessoas interessantes se distanciam."}},"7:0":{"alias":"OKARANLOBE","page":293,"phrase":"Okanranlogbe, Okanasode ole mejila titi efón malu ilé ni olé iyalagun Oba Xonxon ole Sode nitá Orunmilá opalaiye Okanran jun.","sections":{"representation":[["Este Odu é filho de Okanran e Ogbe.",293],["Este Odu é caminho de Egun.",293],["Este signo determina que a pessoa tenha um Egun assentado com suas próprias mãos de acordo com as orientações do próprio Egun.",293]],"native":[["Os filhos deste Odu não podem dar chapéus de presente para ninguém, sob pena de perderem a sorte e a força de suas cabeças.",293]],"reading":[["Fala de um espírito que está ressentido porque a pessoa fez um trato com ele e não cumpriu.",293],["Quando surge este Odu para uma mulher, indica que tem relações clandestinas e secretas ou as teve antes de se casar.",294],["Indicado para solucionar problemas de justiça e de documentos.",294]],"care":[],"stories":[["Neste caminho se dá cabra a Orunmilá.",293]],"curiosities":[]},"ire":{"p":163,"text":"o trajeto a uma nova direção abre o caminho. Esse Odu ressalta a chance aberta por novos desafios."},"ibi":{"p":163,"text":"a nova direção não conduz ao êxito. Esse Odu adverte que as consequências de novos desafios fracassados podem ser negativas. Para encontrar novos caminhos é necessário, antes de tudo, trans-formar-se e não simplesmente começar de novo. Possivelmente, não é um bom momento para um novo começo."}},"7:1":{"alias":"OKARANIYEKU","page":296,"phrase":"Okanraniyeku Ifá Arufin Arudá akitifá bogbo wa laxe axeto. Akitibonbo Orunmilá nare Baba xe Orun Arufin Arudá. Okanraniyeku obere obere leré Olokun Babá Kaxiré, Oluwo Popo oberé leré Omayere axe bogbo Orunmale likotun, bogbo Orunmale yikosi to iban Exú.","sections":{"representation":[["Este Odu é filho de Okanran e Oyeku.",296]],"native":[["O Awo deste Odu tem que ter um okpele especial.",297]],"reading":[],"care":[["Não deve lançar maldições nem se envolver em fofocas.",297]],"stories":[["Neste caminho Orunmilá e Xangô eram macumbeiros, mexiam com Eguns e faziam trabalhos com pólvora e coisas de feitiçaria, mas foram obrigados a abandonar estas atividades.",296]],"curiosities":[]},"ire":{"p":173,"text":"um novo começo encerra uma fase. O início de algo novo encerra algo antigo."},"ibi":{"p":173,"text":"uma nova direção leva a perdas. Um novo começo fracassa, encerrando uma fase. Não há mais caminho de volta."}},"7:2":{"alias":"OKARANIWORI","page":298,"phrase":"Okanraniwori agarofí adifafun Osain Obanixawo maferefun Xangô, abo, akukó, etú lebó.","sections":{"representation":[["Este Odu é filho de Okanran e Iwori.",298],["Este Odu fala de um rapaz que é andarilho.",299]],"native":[],"reading":[["Assinala deformação no ventre da mulher.",299]],"care":[["Este dinheiro não deve ser gasto com outra finalidade para que não ocorra um grande mal.",298],["Tem que ter muito cuidado com o fogo e não deve pensar em dar fim à própria vida.",298],["Não deve comer comida requentada e tem que cuidar dos rins e do estômago.",298]],"stories":[["Foi neste caminho que a Terra tomou forma.",298]],"curiosities":[]},"ire":{"p":181,"text":"o desenvolvimento de uma nova identidade é sustentado por um novo começo e pela condução dos desejos do coração."},"ibi":{"p":181,"text":"os assuntos do coração não são levados adiante ou estão bloqueados, impedindo a descoberta interior da identidade."}},"7:3":{"alias":"OKARANDI","page":300,"phrase":"Okanrandi tobato efán kare beiya adifafun Olodofá toloyó loxelé abe elebó, iwo Obinin kan tolefin eiyelé akukó lebó. Okanrandi Ifá xirê kaferefun Xangô, Oxalá ati Exú.","sections":{"representation":[["Este Odu é filho de Okanran e Odi.",300],["Este Odu fala dos movimentos da terra e das sete correntes de água doce que correm no fundo do oceano.",300],["Este Odu dá posição e riqueza, mas nega amor.",301]],"native":[["Os filhos deste Odu são muito ligados aos Eguns, quer sejam seus familiares ou seus protetores.",300]],"reading":[],"care":[],"stories":[],"curiosities":[]},"ire":{"p":187,"text":"novos caminhos ou a abertura do coração conduzem à renovação."},"ibi":{"p":187,"text":"caminhos bloqueados e o coração fechado impedem a renovação."}},"7:4":{"alias":"OKARANROSUN","page":302,"phrase":"Okanaroso adifafun okuni aratoko ole exon Osain nile Kaferefun Orunmilá.","sections":{"representation":[["Este Odu é filho de Okanran e Irosun.",302],["É um Odu de maldição, seus ebós são despachados no alto do morro.",302]],"native":[],"reading":[],"care":[],"stories":[["Neste caminho Omolú vive nos cantos das paredes e Xangô anda errante.",303]],"curiosities":[]},"ire":{"p":194,"text":"uma nova direção, uma reviravolta ou um novo amor viabiliza a concretização do destino, a reunião familiar e a realização dos potenciais."},"ibi":{"p":194,"text":"o isolamento, o coração fechado e oportunidades perdidas conduzem ao conflito e à resistência às tarefas da vida e da família."}},"7:5":{"alias":"OKARANWÓNRIN","page":304,"phrase":"Okanayabile Okawa wa wa adifafun obó loiye adie elén lebó. Kure kure, euré, ekú lebó.","sections":{"representation":[["Este Odu é filho de Okanran e Owónrin.",304]],"native":[],"reading":[["Assinala armadilhas de Babalawo contra Iyalorixá e Babalorixá.",304],["Assinala discórdias em família.",304],["Assinala disputas entre irmãos por um terreno deixado como herança.",304]],"care":[["A pessoa não deve falar de seus planos para que possa realizá-los.",305]],"stories":[],"curiosities":[]},"ire":{"p":201,"text":"um novo começo, um novo amor ou um novo projeto conduz à revolução interior."},"ibi":{"p":201,"text":"o isolamento, o fim de uma relação amorosa ou de assuntos do coração produz caos interior, gerando dúvidas em relação a si próprio e causando desorientação."}},"7:6":{"alias":"OKARANBARA","page":306,"phrase":"Okanranbara Olodafun Orunmilá oni pataki ko dafá. Exú Ifaeledoiya, Elegbara Latile miatele Awo anatiwo atele ese adifafun Onibarabaniregun anbatele iyolaibeneku asunxé agbado. Akukó lebó. Kaferefun Xangô Ati Oiyá.","sections":{"representation":[["Este Odu é filho de Okanran e Obara.",306],["Este é o caminho onde se provam as habilidades de aspirantes a um cargo.",307]],"native":[],"reading":[],"care":[["Não deve emprestar dinheiro, pois dificilmente o receberá.",306],["Não deve chorar miséria para que seus protetores possam ajudá-la.",307]],"stories":[["Neste caminho Elegbara e Osain traíram Xangô.",306]],"curiosities":[]},"ire":{"p":208,"text":"o momento é oportuno para assuntos do coração e para novos caminhos, que conduzirão à transformação interior, à reflexão e à humildade."},"ibi":{"p":208,"text":"o isolamento, a passividade, a insensibilidade e a falta de empatia conduzem ao egoísmo e à resistência à transformação interior."}},"7:8":{"alias":"OKARANGUNDÁ","page":308,"phrase":"Okanrangundá xukudu ile didé abaxé keredi irewo xaxá. Awo Elepanapa eiyele lebó.","sections":{"representation":[["Este Odu é filho de Okanran e Ogundá.",308],["Este signo fala dos planetas e de suas influências sobre os seres humanos.",308]],"native":[["Os filhos deste Odu geralmente terminam suas vidas afastados de todos.",308]],"reading":[],"care":[["Deve ter cuidado com uma armadilha que vão lhe preparar.",309],["Deve ter cuidado para não fazer uso indevido delas.",309]],"stories":[],"curiosities":[]},"ire":{"p":212,"text":"um novo caminho e o coração aberto eliminam barreiras, deixando o caminho livre para a realização de novas ideias, desejos e relações."},"ibi":{"p":212,"text":"o isolamento e o cancelamento de oportunidades conduzem ao conflito e à disputa."}},"7:9":{"alias":"OKARANSÁ","page":310,"phrase":"Okanransá mokusi bilari oni Babalawo bilari, bilari oma, Babalawo lorun lorun lobosu laya, lorun lorun ebó kabolosí. Okanransá koxé Xangô ebó ada mokisí bilari kongún gun gun adifafun Oluwo Ikoko.","sections":{"representation":[["Este Odu é filho de Okanran e Osa.",310]],"native":[],"reading":[],"care":[["Não deve abusar de nenhuma mulher e tem que amar e respeitar à sua.",311]],"stories":[["Neste caminho Ogun come veado, Elegbara come cotia e Xangô come rato-do-mato.",310],["Foi neste Odu que Atlântida desapareceu.",311]],"curiosities":[]},"ire":{"p":213,"text":"um novo caminho e o coração aberto conduzem a melhoras radicais no mundo exterior."},"ibi":{"p":213,"text":"o isolamento e a recusa de oportunidades conduzem ao ostracismo, a cancelamentos e a transformações radicais na vida exterior."}},"7:10":{"alias":"OKARANKA","page":312,"phrase":"Okanranká adifafun Kana Kana tinxoloiya eyé akomean ijajú eiyelé lebó, akukó, eure lebó.","sections":{"representation":[["Este Odu é filho de Okanran e de Iká.",312]],"native":[],"reading":[],"care":[["Deve ter cuidado com um filho e uma questão de falso testemunho.",313]],"stories":[["Foi neste caminho que Obatalá trocou as vestimentas negras pelas brancas.",312]],"curiosities":[]},"ire":{"p":213,"text":"novos caminhos e novas parcerias fortalecem o status e o equilíbrio interior."},"ibi":{"p":213,"text":"o recuo de projetos e pessoas enfraquecem o status e a força interior."}},"7:11":{"alias":"OKARANTRUKPON","page":314,"phrase":"Okanrantrukpon Ikanifori Ikaniyu ni masukú logué ni Olorun Obinin.","sections":{"representation":[["Este Odu é filho de Okanran e Oturukpon.",314],["Este signo fala de comércio e de negócios.",314]],"native":[],"reading":[],"care":[["Não deve comer na casa de ninguém.",314]],"stories":[["Neste caminho falam Elegbara e Xangô.",314]],"curiosities":[]},"ire":{"p":213,"text":"o coração aberto e novas oportunidades curam antigas feridas, conduzindo ao crescimento espiritual e material."},"ibi":{"p":213,"text":"o isolamento e a desistência conduzem a retrocessos e ao fracasso, podendo também prejudicar a saúde."}},"7:12":{"alias":"OKARANTURA","page":316,"phrase":"Okanaturale Ifá Ire Okana nimaseku logueni Olorun ami binú kaferefun Olorun ati Orunmilá. Adifafun Obatalá ati Oxun.","sections":{"representation":[["Este Odu é filho de Okanran e Otura.",316],["Este Odu é caminho de Xangô, Yemanjá e Elegbara.",317]],"native":[],"reading":[["Assinala dívida e falta de respeito com os Orixás.",316],["Assinala separação em família.",316],["Quando este Odu surge para uma mulher fala de rompimento do útero.",316]],"care":[["A pessoa não deve aceitar convites sem antes fazer ebó, porque pode adoecer e ficar inutilizada de duas coisas.",316],["Não deve ingerir bebidas alcoólicas.",317]],"stories":[["Neste caminho a pessoa se comunica com seu Guia Espiritual e deve invocá-lo na alegria e na dor.",317]],"curiosities":[]},"ire":{"p":214,"text":"o coração aberto e o crescimento criam espaço para visões."},"ibi":{"p":214,"text":"a recusa e o recuo de novas oportunidades conduzem ao autoengano e a visões sombrias."}},"7:13":{"alias":"OKARANRETE","page":318,"phrase":"Okanawete Okanran beko ejá okó bebere koféobafun okú Iyá aro ikofé odo lorun axaiye ekú, ejá, otá, lagoni lodafun Ogun kaferefun Obatalá.","sections":{"representation":[["Este Odu é filho de Okanran e Irete.",318],["É filho de Obatalá e Oxun.",319]],"native":[],"reading":[["Quando surge este signo em Awofakan ou Ikofá, a pessoa tem que dar um ganso ao seu Elegbara e fazer Orixá.",318]],"care":[["Não deve dar nenhuma de suas roupas, pois a sua sorte muda para o lado do presenteado.",318],["A pessoa não deve contar com seus familiares para nada.",319]],"stories":[["Foi neste caminho que a mulher do ganso se apaixonou pelo pavão real.",318],["Neste caminho a própria família e os amigos mais chegados traem a pessoa.",319]],"curiosities":[]},"ire":{"p":214,"text":"um novo caminho ou uma nova relação pode ser levado adiante com determinação."},"ibi":{"p":214,"text":"o fracasso de um relacionamento ou de novos projetos conduz à passividade."}},"7:14":{"alias":"OKARANXE","page":320,"phrase":"Okana Xe oiyen mama muyó irolé ori efiniyan otá obani fe aba nimi abamó kaferefun Oxun, Elegbara, ati Orunmilá.","sections":{"representation":[["Este Odu é filho de Okanran e Oxe.",320],["Este é um signo de loucuras.",320],["Este signo fala do sentimento de mais profundo amor do homem pela mulher e do sacrifício supremo em nome do amor.",320]],"native":[],"reading":[["Assinala inveja e traição.",320],["Assinala a existência de uma mulher que, por vaidade e capricho, deseja separar um casal e adquirir para si o amor do homem.",320],["Assinala maldições e feitiços feitos há muito tempo.",320]],"care":[],"stories":[["Foi neste Odu que Xangô abandonou Oiyá, ficando depois com complexo de culpa por sua morte.",320]],"curiosities":[]},"ire":{"p":214,"text":"um novo caminho e uma nova relação conduzem à plenitude e à conexão espiritual."},"ibi":{"p":214,"text":"o isolamento e a falta de perspectivas conduzem ao vazio, à inveja e à perda de confiança."}},"7:15":{"alias":"OKARANFUN","page":322,"phrase":"Okanafun Aye lobí oiyn onan tosa aguko adifafun Inle Abatá lala tinxoman Oba Alejo ajeri kobori ejá oro, omi losan. Kaferefun Oxalá, Ogun, Iya Tobi. Maferefun Elegbara ati Inle Abatá.","sections":{"representation":[["Este Odu é filho de Okanran e de Ofun.",322],["Este é um Odu de perseguições.",322]],"native":[],"reading":[["Assinala doenças nas vistas, infecções, inflamações e glaucomas.",322],["Fala de deslocamento de retina, miopia, astigmatismo e cegueira noturna.",322],["Assinala desobediência ao Orixá, separação em família e erupções cutâneas.",323]],"care":[["Não deve portar armas para não ficar em osogbo.",323]],"stories":[["Neste caminho a pessoa é perseguida por seu cônjuge, pelos inimigos ou pela justiça.",322]],"curiosities":[]},"ire":{"p":215,"text":"um novo caminho ou uma nova relação se evidencia como um milagre e conduz à revelação."},"ibi":{"p":215,"text":"o isolamento conduz ao fracasso, impedindo que o destino se cumpra. Projetos e relacionamentos revelam não ter sentido algum."}},"8:8":{"alias":"OGUNDA MEJI","page":324,"phrase":"Ogunda Meji, Ogunda Siro, owo iyolokun, Oxalá biriniwá, Obatalá Obataisá, Hekpa Oba Igbo odobaleni Ogun Onire iyo lokun. Oxóssi Ogunda Meji eyeni eyeraruna okualorun Obatalyana tiwa Elegbara awa lawa Oluwo Xiwosi Orunmilá Kayé mariwo maferefun Oduduwa Orubó.","sections":{"representation":[["Este é um Odu masculino, filho de Okó e Awounsi.",324],["Representa um punhal, a justiça, a lei.",324],["Este Odu é portador da maldição de Afebile, um Orixá Funfun que vibra na atmosfera.",326]],"native":[["O Awo deste Odu recebe sorte e proteção de Ogun.",324]],"reading":[["Assinala doenças venéreas, impotência sexual masculina, doenças vaginais, enfermidades na cabeça e no aparelho genital.",324],["Assinala a existência de um pênis muito avantajado que, ao invés de proporcionar prazer, lesiona a mulher.",325],["Assinala, para a mulher, prática de prostituição que deve ser imediatamente abandonada.",325]],"care":[],"stories":[["Neste caminho falam Ogun, Xangô, Obatalá, Oxóssi, Ibejis, Babá Oke, Elegbara e Egun.",324],["Neste caminho, quando chegar o momento, a pessoa terá que assentar Obaluaye e Yewá.",325],["Neste caminho Aroni e Osain ensinam as virtudes das ervas para curar enfermidades e consagrar os Orixás.",326]],"curiosities":[]},"ire":{"p":218,"text":"há energia, força de vontade e capacidade suficientes para a concretização de planos. As barreiras desaparecem, as visões podem ser realizadas com sucesso."},"ibi":{"p":218,"text":"há conflitos e disputas sem sentido. A falta de capacidade de ação, de força de vontade e de energia impedem que temas sejam levados ao fim."}},"8:0":{"alias":"OGUNDAGBE","page":329,"phrase":"Ogundabiode igará ni gará foroforo ajabó omó nimu omi iyeru omó leri okan garanife ekú elebó afaterete emi laiboa gbelega lodafun aiya okunlá ti ole Igará.","sections":{"representation":[["Este Odu é filho de Ogunda e Ogbe.",329],["Este Odu determina que a pessoa tenha que fazer Ifá antes de morrer.",329]],"native":[["O Ogun do Awo deste signo tem que ter um boneco de ferro, um okpele do mesmo metal e um opon pequeno de cedro.",331],["As pessoas deste signo não podem dar murros ou tapas sobre a mesa porque desperta os mortos que podem se apresentar.",331]],"reading":[["Quando este Odu surge em ikofá ou atefá, coloca-se uma mão de 21 búzios dentro de Orunmilá ou junto com a mão maior de Ifá2.",330]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":163,"text":"novos planos serão concretizados com sucesso. Esse Odu indica que há condições favoráveis para a concretização de novas etapas da vida e novos temas."},"ibi":{"p":163,"text":"conflitos impedem a concretização de novos temas. Esse Odu alerta para a falta de força de vontade que impede a realização das condições necessárias para novos projetos."}},"8:1":{"alias":"OGUNDAYEKU","page":332,"phrase":"Ogunda ariku agogô abonó lodafun ariku adifafun Iyalode, kaferefun Orunmilá.","sections":{"representation":[["Este Odu é filho de Ogundá e Oyeku.",332],["Este Odu traz mais triunfos durante a noite do que de dia.",332],["Este Odu representa Orunmilá sobre a terra.",332]],"native":[],"reading":[["Assinala amarração feita por mulher.",332],["Fala de mulher e de dinheiro.",332],["Assinala visão ineficiente.",332]],"care":[],"stories":[["Neste caminho a cerejeira brigou com o poço e causou-lhe muitos aborrecimentos, esquecendo-se de que vivia bela e frondosa graças à água que o poço lhe oferecia.",332]],"curiosities":[]},"ire":{"p":173,"text":"a força de vontade permite que temas, projetos, relacionamentos ou etapas sejam concluídos."},"ibi":{"p":173,"text":"a falta de força de vontade conduz a perdas, cancelamentos, interrompe fases e projetos e leva ao fim de relacionamentos."}},"8:2":{"alias":"OGUNDAIWORI","page":334,"phrase":"Ogundawori Ogunda Alapo Iwori Olofá kaxapo iyero adifafun akatampó tolosi iyawa eleye elebó. Akukó, ejá-oro lebó. Ogundawori Ifá lodafun Olokun kaferefun Xangô.","sections":{"representation":[["Este Odu é filho de Ogunda e Iwori.",334]],"native":[],"reading":[["Quando surge prenuncia tragédias na rua.",334],["Assinala uma tragédia dentro de casa.",334],["Assinala separação do casal.",334]],"care":[["A pessoa não deve dar fotos suas a ninguém para não sofrer uma bruxaria.",334],["Não deve permitir que pisem em sua sombra e tem que ter cuidado para que não a usem para fazerem um feitiço.",334],["Não deve permitir brigas em sua casa nem participar delas para evitar a ira de Ogun que, intervindo, poderá ocasionar uma desgraça.",334]],"stories":[["Neste caminho Elegbara é enganador, tanto pratica o bem quanto o mal.",334]],"curiosities":[]},"ire":{"p":181,"text":"a eliminação de obstáculos conduz à transformação."},"ibi":{"p":181,"text":"conflitos e disputas impedem a transformação."}},"8:3":{"alias":"OGUNDADI","page":336,"phrase":"Ogunda Abatambá Odi adalará adifafun Ayê nabi eiyelé, igbá ere, ewefá, akukó lebó.","sections":{"representation":[["Este Odu é filho de Ogunda e Odi.",336]],"native":[["A pessoa deste Odu não deve dormir em completa escuridão.",336],["O filho deste Odu tem que assentar Awán Ajonú, que se arruma dentro de um alguidar, modelando-se uma cabeça de barro cujo lado direito é masculino e o esquerdo é feminino.",337]],"reading":[["Assinala que a mulher é infiel.",336],["Quando este Odu aprendeu Ifá, brigou com seu padrinho e com quem o ensinou.",337]],"care":[["A pessoa deste Odu não deve dormir em completa escuridão.",336]],"stories":[["Neste caminho, Exú Awán Ajonú, colocou uma máscara para destruir o mundo.",337]],"curiosities":[]},"ire":{"p":188,"text":"a força de ação e a força de vontade são a base da renovação."},"ibi":{"p":188,"text":"há carência de força de ação e de vontade para mudar."}},"8:4":{"alias":"OGUNDA ROSO","page":339,"phrase":"Ogundakoroso kukuté kuku adifafun eni tinxerú Osa ebebo lebó. Aiyonnú lebó abonun imbo ubé Osá olosú unxéwá gari adifafun la xude eti soman Orixá kivin eiyelé lebó, eure lebó.","sections":{"representation":[["Este Odu é filho de Ogunda e Irosun É neste caminho que Ogun e Oxun andam juntos Foi aqui que Yemanjá comeu carne de porco frita com rodelinhas de banana verde pela primeira vez.",339],["Este é o signo do pelicano.",339],["Este Odu proíbe a ingestão de bebidas alcoólicas.",340]],"native":[],"reading":[["Quando surge este Odu para um Babalawo ou para um Babalorixá, tem que oferecer dois pombos à cabeça, independente de trazer osogbo ou ire.",339],["Assinala ineficiência ou falta de habilidade para realizar o coito.",340],["Assinala que a pessoa tem vontade de mudar-se do lugar onde vive ou trabalha.",340]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":194,"text":"a eliminação de barreiras e a realização das exigências pessoais favorecem a concretização dos potenciais."},"ibi":{"p":195,"text":"a falta de força e de capacidade de ação conduz à resistência ao destino, a novos conflitos familiares e à não realização dos potenciais."}},"8:5":{"alias":"OGUNDAWÓNRIN","page":341,"phrase":"Ogundaleni Anaraté adifafun eiyelé tinlósilé anué, eiyelé lebó, akukó lebó. Kaferefun Exú, Ogun ati Oxóssi.","sections":{"representation":[["Este Odu é filho de Ogunda e Owónrin.",341],["É um Odu de poder de decisão.",341],["Este é o Odu da força sexual.",343]],"native":[["O Awo deste Odu não pode fazer Ifá em ninguém.",342]],"reading":[["Fala de indigência por má orientação da própria cabeça da pessoa.",342]],"care":[["A pessoa não deve se meter no que não é da sua conta.",341],["Não deve nunca, apelar para a violência.",341]],"stories":[["Foi neste Odu que Olofin fez com que o pombo perdesse a voz.",342]],"curiosities":[]},"ire":{"p":201,"text":"a eliminação de barreiras e a realização das exigências pessoais protegem de mudanças inesperadas ou induzem uma reorientação interior positiva."},"ibi":{"p":201,"text":"conflitos, discussões ou a passividade e a inatividade conduzem ao caos interior e à sobrecarga, gerando dúvidas sobre si próprio."}},"8:6":{"alias":"OGUNDABARA","page":344,"phrase":"Ogundabara Ogunda Sá Obara ban adifafun bombo tolobina adié mewá abemú, owó meewá, kaferefun Orunmilá.","sections":{"representation":[["Este Odu é filho de Ogunda e Obara Aqui nasceu a briga de galos.",344]],"native":[],"reading":[["Assinala problemas, com pessoas mais velhas, no âmbito religioso.",345]],"care":[],"stories":[["Neste caminho Orunmilá fez Ifá em Obatalá e ganhou muito dinheiro com isto.",344]],"curiosities":[]},"ire":{"p":208,"text":"a eliminação de barreiras conduz à transformação interior."},"ibi":{"p":208,"text":"o conflito conduz ao egoísmo."}},"8:7":{"alias":"OGUNDAKANRAN","page":346,"phrase":"Ogundako oke alafia ekodidé afike lori kowá ale axé ata ouniyen bogbo araje apadá senio ekú, ejá, agbado.","sections":{"representation":[["Este Odu é filho de Ogunda e Okanran.",346]],"native":[["O Awo deste Odu tem que oferecer um galo a Exú de dois em dois meses.",346]],"reading":[],"care":[],"stories":[["Neste caminho fizeram Ifá para o crocodilo.",346]],"curiosities":[]},"ire":{"p":213,"text":"a concretização de interesses abre o caminho do coração. Novas oportunidades surgem quando os obstáculos são eliminados."},"ibi":{"p":213,"text":"o conflito conduz ao isolamento, fechando as portas para novos caminhos."}},"8:9":{"alias":"OGUNDAMASÁ","page":348,"phrase":"Ogundamasá awará wará sokende awará wará. Lereiyé awará wará Olorun Aiye adifafun gunugun ni aundi ebé koru.","sections":{"representation":[["Este Odu assinala muito ciúme.",348],["Este Odu é domínio de Oxun.",349]],"native":[],"reading":[["Assinala que a pessoa teve Guerreiros assentados e que se desfez deles.",348]],"care":[],"stories":[["Neste caminho os filhos comem as próprias mães.",348]],"curiosities":[]},"ire":{"p":218,"text":"a capacidade de ação e a força de vontade viabilizam mudanças radicais no exterior."},"ibi":{"p":218,"text":"conflitos sem sentido conduzem a grandes perdas. A passividade, a falta de resistência e a fraqueza conduzem o mundo exterior ao desvio."}},"8:10":{"alias":"OGUNDAKÁ","page":350,"phrase":"Ogunda Kalare odafá egbe eiyele lebó. Marora intori itá. Ogundaká kan adofá iyanle adifafun abe. Kaferefun Ogun, eiyele lebó marora, intori Iya ekodidé, ekú, ejá elebó.","sections":{"representation":[["Este Odu é filho de Ogunda e Iká.",350]],"native":[["Segredo do Odu: O Awo deste Odu quando recebe Olofin, tem que fazer três ebós nas margens de um rio para proteger sua própria sombra.",351]],"reading":[["Assinala maldade, morte e injustiça.",350],["Assinala separação e afastamento.",350],["Assinala roubos, violências e abusos sexuais.",351]],"care":[["Não deve permitir que estranhos durmam em sua casa, muito menos em sua cama.",350]],"stories":[],"curiosities":[]},"ire":{"p":219,"text":"a concretização de objetivos pessoais fortalece a posição e a convicção interior."},"ibi":{"p":219,"text":"os conflitos ou a passividade enfraquecem a posição e conduzem eventualmente à perda da convicção interior e da força."}},"8:11":{"alias":"OGUNDATURUKPON","page":352,"phrase":"Ogundaturukpon Baba Toto adifafun Alagbedé omi ladelorubó kana situ lasi oni ketebó akukó, adie, yarako, ajá keke elegbo. Intori ejó Obinin pupá marora.","sections":{"representation":[["Este Odu é filho de Ogunda e Oturukpon.",352]],"native":[],"reading":[["Assinala uma guerra da qual a pessoa sairá vitoriosa.",352]],"care":[["Não deve ingerir bebidas alcoólicas porque, estando alcoolizada, fica à mercê de seus inimigos.",352]],"stories":[],"curiosities":[]},"ire":{"p":219,"text":"a concretização de ideias e desejos, como também a força de vontade, conduzem ao crescimento e à saúde."},"ibi":{"p":219,"text":"tanto a falta de capacidade para realizar interesses pessoais, como também os conflitos que consomem energia, provocam doenças e o fim de relações e de processos."}},"8:12":{"alias":"OGUNDATURÁ","page":353,"phrase":"Ogunda Tetura adifona adifafun Bantijó jojé iguí, akukó lebó, kukute kuku adifafun Omi Ixeri, akete lebó, bebe otun, bebe osi, adifafun Ori, eiyele, agadá lebó.","sections":{"representation":[["Este Odu é filho de Ogunda e Otura.",353],["Este é um signo de transformações.",354]],"native":[],"reading":[["Quando este Odu aparece, a pessoa tem que fazer ebó tendo, durante todo o tempo da cerimônia, um frango na mão.",353]],"care":[["Por este motivo Oiyá recebeu o título de Adikun e o óleo adi passou a ser tabu para Exú.",353],["A pessoa deve ter cuidado para não ser escravizada por outrem.",353]],"stories":[["Neste caminho, Xangô, com seu escravo Abo, encontrou abrigo na casa de Oni Bombo Orá que é uma árvore e, por isto, seu ibá é feito em gamelas de madeira.",353]],"curiosities":[]},"ire":{"p":219,"text":"a realização de interesses fortalece a visão."},"ibi":{"p":219,"text":"conflitos sem sentido bloqueiam a visão e roubam a energia necessária para novas visões com sentido."}},"8:13":{"alias":"OGUNDAKETE","page":355,"phrase":"Ogunda Kete gumigui Awo Ori ara akanaribo wo Ori axi tentere Awo oun meteta ni xoma Ikú Ifá Orunmilá.","sections":{"representation":[["Este Odu é filho de Ogunda e Irete.",355],["Este Odu pode levar seu padrinho à miséria.",357],["Este Odu explica porque os homossexuais têm um grande poder de assimilação dos segredos da religião, mas suas consagrações, mais cedo ou mais tarde são prejudiciais para eles mesmos.",357]],"native":[["As pessoas deste Odu são teimosas e obstinadas.",355],["O awo deste Odu tem que ter um pedaço de iguí irôko em cada uma das suas mãos de Ifá.",357]],"reading":[["Assinala pouca firmeza de caráter na pessoa.",355],["Assinala falta de caráter na pessoa e de mulheres que criam grandes problemas.",357]],"care":[["Não deve dar nem emprestar suas roupas e seus chapéus.",356],["O homem não deve comer doces para não ser dominado pela mulher.",356]],"stories":[["Neste caminho não se acredita nos Babalawos.",356],["Neste caminho Obatalá come junto com Orunmilá.",357],["Neste caminho Ogun e Oxóssi andavam sempre juntos.",357]],"curiosities":[]},"ire":{"p":220,"text":"a realização dos interesses pessoais e a força de vontade são essenciais para transformar o mundo exterior com determinação."},"ibi":{"p":220,"text":"conflitos fictícios, ou a passividade e a falta de energia, impedem uma reorientação."}},"8:14":{"alias":"OGUNDAXE","page":358,"phrase":"Ogunda Monixe Olofin oun obe kaferefun Orunmilá, Olofin, Exú, Xangô ati Obaluayiemi.","sections":{"representation":[["Este Odu é filho de Ogunda e Oxe.",358],["Este Odu determina que o Awo possa receber Olofin em qualquer idade.",358],["É um Odu de mascaramentos.",359]],"native":[["No kuanado do Awo deste Odu as facas são de madeira.",358]],"reading":[["Assinala dívida com Orunmilá.",358],["Quando surge em atefá, pega-se uma panela de barro cheia de água, acende-se uma brasa bem grande e apaga-se na água da panela.",358],["Assinala desentendimentos e má interpretação de atitudes ou palavras.",358]],"care":[],"stories":[["Neste caminho Ogun foi descriminado, por este motivo, Ogundaxe não tem direito de fazer matanças.",358]],"curiosities":[]},"ire":{"p":220,"text":"a realização exitosa de interesses traz a plenitude espiritual, emocional e material."},"ibi":{"p":220,"text":"conflitos conduzem a perdas e à falta de orientação."}},"8:15":{"alias":"OGUNDAFUN","page":360,"phrase":"Ogundafun wewe yeye, wewe yeye oni rewó omo Osain kuelese kan kuelese meji.","sections":{"representation":[["Este Odu é filho de Ogunda e Ofun.",360],["É um Odu de guerras e o homem deve ter cuidado, pois sua vida está ameaçada.",360],["Este Odu assinala gravidez.",360]],"native":[],"reading":[["Quando este Odu surge numa consulta, o Awo que o sacou tem que fazer rogação para a sua própria cabeça para livrar-se das negatividades do cliente.",361],["Assinala dívidas com um parente morto, missas ou preces.",361]],"care":[["A mulher que se consulta deve ter cuidado com seu casamento, pois não ama seu marido.",360],["É um Odu de guerras e o homem deve ter cuidado, pois sua vida está ameaçada.",360],["A pessoa deve ter cuidado com uma menina que lhe trará problemas com a justiça.",361]],"stories":[],"curiosities":[]},"ire":{"p":220,"text":"a eliminação de barreiras e a concretização de visões revelam uma nova fase, parceria ou aprendizagem."},"ibi":{"p":220,"text":"conflitos sem sentido revelam que os objetivos e a orientação estão equivocados, conduzindo as visões ao fracasso."}},"9:9":{"alias":"OSÁ MEJI","page":362,"phrase":"Osá Meji Ifá joko adafun Ogue dire iyun kode akasa fará tefiko digbe kale Ifá.","sections":{"representation":[["Rege as relações entre a Terra e o Sol e a Terra e a Lua.",362],["Rege o sangue e todos os homens, porque possuem sangue, estão sob sua influência de forma idêntica.",362],["Representa o domínio da mulher sobre o homem e por isto todos os trabalhos de amarração de homens são feitos através dele e sua figuração indicial deve ser traçada no local onde serão feitos os sacrifícios necessários.",362]],"native":[["Os filhos deste Odu sobrevivem aos seus irmãos e participam de seus funerais.",363],["O Awo deste Odu não deve comer nada que lhe seja mandado por outra pessoa.",364]],"reading":[["Assinala problemas de saúde relacionados com o sangue, paralisias, artrites, suspensão ou excesso de menstruação, hemorragias de todas as origens (principalmente as vaginais), inflamações da garganta, tuberculoses, úlceras intestinais e hemorróidas.",363],["Assinala traição, viagens, prisão, inveja, obtenção de alguma coisa e vitória nos objetivos.",363],["Assinala neurastenia e enfermidades nos ossos.",363]],"care":[["O Awo deste Odu não deve comer nada que lhe seja mandado por outra pessoa.",364]],"stories":[["Neste caminho fazem-se oferendas e acendem-se velas para as árvores, pois é através deste Odu que os espíritos das árvores inspiram e orientam os homens.",363],["Neste caminho Oxun entrega seu filho à Yemanjá para que o salve.",364],["Foi aqui que a pomba transmitiu doença a Xangô.",364]],"curiosities":[]},"ire":{"p":224,"text":"mudanças radicais trazem purificação e renovação."},"ibi":{"p":224,"text":"mudanças radicais conduzem à destruição, ao rompimento e a perdas."}},"9:0":{"alias":"OSÁLOGBE","page":366,"phrase":"Osalogbe laminagada tori yampo be lampe Xangô kawo kabiesile laminagada adifafun Exú Ijelú Oba lonan, Oba Exú Ijelú, yeneye ni, Yewá ni, Olokun eni Ifá. Exú Ijelú Piriti Piriti omóde Alará lampe Xangô laminagandá.","sections":{"representation":[["Este Odu é filho de Osá e Ogbe.",366],["É um Odu de mal agradecidos.",369]],"native":[["Os filhos deste Odu não podem comer ovos, acelga, chocolate, pepino e nenhum alimento remozo.",367],["A felicidade do filho deste Odu será encontrada ao lado de uma mulher que tenha sido muito leviana ou até mesmo prostituta e que tenha se regenerado.",367],["O Awo deste Odu tem que ter Oduduwa assentado, pois é seu servidor e recebe seu poder na terra e no céu.",367]],"reading":[["Assinala pressão alta, dermatoses, psoríase e problemas cardíacos.",367],["Fala de pessoas de duas caras.",367],["Quando este Odu surge para qualquer Awo numa consulta para si mesmo, ele terá que dormir, durante sete dias, numa esteira aos pés de Orunmilá.",367]],"care":[["Não deve guardar dinheiro de ninguém para não passar por um grande aborrecimento.",368],["Ensina que o Awo não deve resolver os problemas das pessoas de uma só vez.",369]],"stories":[["Neste caminho é que se aprende que somente o Babalawo que tenha Olofin7pode assentar qualquer Orixá para os outros.",367],["Neste caminho é Oduduwa que dá a memória ao Awo.",367]],"curiosities":[]},"ire":{"p":164,"text":"uma mudança exterior abre caminhos. Esse Odu afirma que algo conquistado chegará ao fim para que algo novo, mais enriquecedor, possa começar."},"ibi":{"p":164,"text":"a desintegração de estruturas existentes bloqueia caminhos. Esse Odu adverte que uma mudança exterior dificulta a realização de novos projetos e etapas. Possivelmente haverá perdas materiais ou de apoio exterior."}},"9:1":{"alias":"OSÁYEKU","page":370,"phrase":"Osayeku Awo Bako idá adifafun oun abeboadie, ori, efun, ebetá owo unbó.","sections":{"representation":[["Este Odu é filho de Osá e de Oyeku.",370]],"native":[],"reading":[["Fala de uma pessoa que tem chagas nos pés e, por ter sido de muita valia, não pode ser esquecida ou desprezada.",370],["Assinala desentendimento e ameaças entre cônjuges.",371]],"care":[["Não deve dormir logo após ter feito uma refeição.",370]],"stories":[["Neste caminho não se dá a atenção e o atendimento necessários aos Orixás.",370],["Foi neste caminho que Olofin repartiu tudo o que havia criado com os Orixás, dando a cada um deles um reino.",371]],"curiosities":[]},"ire":{"p":173,"text":"uma mudança súbita encerra um ciclo."},"ibi":{"p":174,"text":"uma mudança inesperada e incontrolável conduz a perdas e interrupções."}},"9:2":{"alias":"OSÁIWORI","page":372,"phrase":"Osáwo abati edeyela ninimu adifafun etú tinxoma olu bebé akukó, abo lebó.","sections":{"representation":[["Este Odu é filho de Osá e Iwori.",372]],"native":[],"reading":[["Assinala desenvolvimento natural.",372]],"care":[],"stories":[["Neste caminho o tigre não pode comer o cabrito.",372]],"curiosities":[]},"ire":{"p":181,"text":"uma súbita mudança externa conduz a uma transformação e a uma nova identidade."},"ibi":{"p":181,"text":"uma súbita mudança negativa conduz a conflitos internos e a uma crise de identidade."}},"9:3":{"alias":"OSADI","page":374,"phrase":"Osadi ixé ixeri boxe koloma tabati ixé gbele ibgba lafimunu adifafun Babá bokun banti po re ki akukó, eiyelé lebó.","sections":{"representation":[["Este Odu é filho de Osá e Odi.",374]],"native":[],"reading":[["Assinala atraso e destruição por ação de Egun.",374],["Assinala que a mulher gosta de outro homem e que o homem gosta de outra mulher.",375],["Assinala traição dentro de casa.",375]],"care":[],"stories":[["Neste caminho a pessoa trabalha em favor de quem não merece.",374]],"curiosities":[]},"ire":{"p":188,"text":"mudanças radicais e o caos externo abrem o caminho para uma novidade."},"ibi":{"p":188,"text":"o caos ou a mudança radical impede a renovação."}},"9:4":{"alias":"OSAROSUN","page":376,"phrase":"Osároso kukute kuku adifafun eni tinxelú Osá Aderé adie lebó ogbo nian imbebe.","sections":{"representation":[["Este Odu é filho de Osá e Irosun.",376]],"native":[["As pessoas deste Odu não podem deixar louças e panelas sujas de um dia para o outro para que a doença não venha se alimentar em sua casa.",376],["As pessoas deste signo não podem quebrar espelhos.",376]],"reading":[["Assinala fraqueza sexual, fraqueza nos ossos, cãibras e problemas circulatórios.",376],["Assinala que uma mulher que gosta de beber poderá ficar louca se insistir nesse costume.",377]],"care":[["Ifá recomenda que, quando isto acontecer, a pessoa não deve retrucar nem perder a calma e desta forma sairá vitoriosa.",377],["Se o cliente for homem, deve ter cuidado para não morrer por causa de uma mulher que deseja estar ao seu lado.",377]],"stories":[["Neste caminho se dá carneiro para Xangô para abrir os caminhos.",376],["Neste caminho colocam-se quatro guizos em Oxun.",376]],"curiosities":[]},"ire":{"p":195,"text":"uma mudança inesperada abre o caminho para a realização do destino e para a harmonia de temas familiares."},"ibi":{"p":195,"text":"uma mudança inesperada e desagradável conduz à insatisfação com o destino e, eventualmente, a conflitos familiares."}},"9:5":{"alias":"OSAWÓNRIN","page":378,"phrase":"Osá Loni Owónrin oni Egun, Osá ni Oye omó Begbe nijó Ifá omó Oni Xangô, Awo Oni Owónrin Ogun Awoni omó Alará.","sections":{"representation":[["Este Odu é filho de Osá e Owónrin.",378],["Este é o caminho do arco-íris, aqui nasceu a cosmonáutica.",378],["Este Odu determina que seus filhos não podem comunicar a ninguém os nomes de seus Orixás e dos seus Guias Protetores para que não lhe roubem a sorte.",379]],"native":[],"reading":[["Assinala mortandade de Babalawo.",378],["Quando este Odu sai como regente do ano indica que durante ele morrerão muitos Babalawos.",378],["Fala de desavenças entre compadres e comadres.",378]],"care":[["O seu filho não deve andar no meio de multidões e nem fazer exercícios sob o Sol.",380]],"stories":[["Foi aqui que o monstro veio á superfície das águas.",379]],"curiosities":[]},"ire":{"p":202,"text":"uma revolução exterior conduz à reorientação interior. Fracassos, como também encontros, situações ou projetos inesperados, abrem o horizonte para a vida interior."},"ibi":{"p":202,"text":"o caos exterior gera caos interior. Mudanças inesperadas no exterior prejudicam a vida interior, gerando dúvidas sobre si próprio e conduzindo à depressão e à desorientação."}},"9:6":{"alias":"OSÁBARA","page":381,"phrase":"Osabara, Osáxepe, Osá ba ni yerekun, Oba ni Xangô, Osá jire Awo Awa Awanilaye Inle, Osáxepe Onilekun.","sections":{"representation":[["Este Odu é filho de Osá e Obara.",381],["Este é o caminho de Aganjú.",381],["Este Odu proíbe que seus filhos passeiem em praças públicas.",381]],"native":[],"reading":[["Assinala desmoralização pública.",381],["Fala de uma jovem que tem dois namorados e que será desvirginada por um deles.",382]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":208,"text":"uma mudança exterior conduz à transformação interior."},"ibi":{"p":208,"text":"mudanças radicais aumentam o egoísmo e prejudicam o desenvolvimento interior."}},"9:7":{"alias":"OSÁKANRAN","page":383,"phrase":"Osákanran obapana ori Egun adifafun Dadá Baiyani, owo, eiyele, ounkó lebó.","sections":{"representation":[["Este Odu é filho de Osá e Okanran.",383]],"native":[["Os filhos deste Odu têm que estar sempre reverenciando Oiyá e alimentando os Eguns.",383],["O Awo deste Odu, além do fio de contas de Orunmilá normal, deve ter outro com oito contas amarelas e oito contas verdes alternadas por nove contas de Oiyá.",383]],"reading":[["Assinala doenças cardíacas.",384],["Quando este Odu sai para uma mulher, determina que ela tem que assentar Olokun, fazer Santo e que não deve fazer abortos, sob pena de perder a vida ou a saúde para sempre.",384]],"care":[["Quando este Odu sai para uma mulher, determina que ela tem que assentar Olokun, fazer Santo e que não deve fazer abortos, sob pena de perder a vida ou a saúde para sempre.",384]],"stories":[["Neste caminho Elegbara descompõe as coisas.",383]],"curiosities":[]},"ire":{"p":213,"text":"tudo passará – a transformação abre o caminho para novas oportunidades e novas relacões."},"ibi":{"p":213,"text":"a devastação descontrolada de relacões e projetos conduz ao isolamento, impedindo que novas oportunidades possam ser enxergadas."}},"9:8":{"alias":"OSÁGUNDÁ","page":385,"phrase":"Oságunda Omó re leboadifafun ojo akan fun kueni Oluwo Tinxomó mo lo Olofin gura gura aiyo gbeka arun adifafun Axomarare, adifafun Oko Akará lebó amaiyara loiyá.","sections":{"representation":[["Este Odu é filho de Osá e Ogundá.",385]],"native":[],"reading":[["Assinala sacrifício de mãe.",385],["Assinala que a pessoa possui herança espiritual ou de Orixás deixada por um ancestral.",385],["Fala de uma mulher que sofre por que tem marido.",385]],"care":[["Quando este signo sai em Awofakan determina que a pessoa não deve chegar a Babalawo.",385],["Não deve dar fiança a ninguém.",386]],"stories":[["Foi aqui que Oiyá, para salvar seus filhos, deixou de comer carneiro entregando-o a Xangô.",385],["Neste caminho os Awos acumulam papeis com ensinamentos secretos, mas não os estudam.",385],["Neste caminho só se oferece, no borí, peixe que possua a língua bem grande.",385]],"curiosities":[]},"ire":{"p":218,"text":"mudanças radicais requerem a realização de objetivos pessoais. Novas condições fortalecem a posição necessária para a ação e para a eliminação de barreiras."},"ibi":{"p":219,"text":"a instabilidade exterior conduz a conflitos e, eventualmente, a disputas sem sentido. Há perigo de haver uma perda total, fraqueza, ou uma subestimação das próprias forças."}},"9:10":{"alias":"OSÁKA","page":387,"phrase":"Osáká iwani okutele kolé adifafun Ariinló ejuá jolé elanjó ejuá akukó lebó, ounko lebó, ori ebó, adie, ewe yokulá unló, axó funfun ikan lowá.","sections":{"representation":[["Este Odu é filho de Osá e de Iká.",387],["Este é o signo do cavalo cansado.",387]],"native":[["Quando um filho deste Odu morre, coloca-se em sua boca uma moeda de prata para que possa ir ao Orun.",387]],"reading":[],"care":[],"stories":[],"curiosities":[]},"ire":{"p":224,"text":"mudanças radicais e processos de purificação avigoram a força interior."},"ibi":{"p":224,"text":"uma destruição inesperada e instabilidade conduzem à uma perda inconveniente de força interior e de autoconfiança."}},"9:11":{"alias":"OSÁTURUKPON","page":389,"phrase":"Osáturukpon ariburú Osá rulú Oturukpon oma eiyelé elodi odefá abá tinxomó elú Osá Kuna Oturukpon oma eiyelé lodi adafun pakere tinxomó olubo Osáturukpon Osá Laiye.","sections":{"representation":[["Este Odu é filho de Osá e Oturukpon.",389]],"native":[["O filho deste Odu tem que ter seu próprio negócio.",389]],"reading":[["Assinala um aborrecimento ocasionado por um falso testemunho.",390]],"care":[["Não deve guardar embrulhos sem saber o seu conteúdo.",390],["Não deve dar ouvidos a intrigas para não ter problemas.",390],["Não deve comer na casa de ninguém que a convide.",390]],"stories":[],"curiosities":[]},"ire":{"p":225,"text":"mudanças drásticas conduzem ao crescimento e à saúde."},"ibi":{"p":225,"text":"mudanças drásticas e instabilidade podem levar a deteriorações e a problemas de saúde."}},"9:12":{"alias":"OSATURÁ","page":391,"phrase":"Osá Kare kujé kure adifafun Manguini Idoroko Odé. Eiyele lebó, ewe eri metá, enú laguení lodafun Detixé Olokun, lodafun Moiye tinxomó Orotoponifé. Kaferefun Obatalá ati alafia.","sections":{"representation":[["Este Odu é filho de Osá e Otura.",391],["Este Odu fala do descanso da Terra.",392]],"native":[],"reading":[["Assinala enfermidades cardíacas e doenças nos ossos.",392],["Assinala doenças venéreas e hidrocele.",393],["Assinala um bem que deve ser compartilhado com seus irmãos e com sua mãe.",393]],"care":[],"stories":[["Neste caminho Elegbara exibia suas partes sexuais, sendo por isso considerado imoral.",391],["Foi aqui que Ikú comeu carne humana pela primeira vez.",392],["Foi neste caminho que Obatalá trocou o ouro pela prata.",392]],"curiosities":[]},"ire":{"p":225,"text":"uma mudança radical inicia um processo de encontro da visão interior."},"ibi":{"p":225,"text":"uma mudança radical conduz ao autoengano e à ilusão."}},"9:13":{"alias":"OSARETE","page":394,"phrase":"Osárete kaferefun Odu, Osain, Orun, Ologun. Osárete Siarete Egun Baba Barado Afefe Ikú Orun omosabi boxe afefe Baba tibayá iye Olokun Lorun omá jibé Egun Mayebé oumbo Axixi Inle kafun awá awe ma fun magbá iguí, mafun magbá agbona bailorun, Egun Bailorun.","sections":{"representation":[["Este Odu é filho de Osá e Irete.",394]],"native":[["O fio de contas de Orunmilá das pessoas deste Odu leva uma noz moscada.",394],["A pessoa deste Odu não pode comer nenhum tipo de banana que esteja verde.",394],["As pessoas deste signo nunca estão satisfeitas com nada que lhe façam.",395]],"reading":[["Assinala separação matrimonial.",394],["Assinala, para a mulher, gravidez de um filho macho.",394],["Assinala doenças no sangue e na garganta.",394]],"care":[["Não deve visitar doentes para que não troquem sua cabeça.",395]],"stories":[["Foi aqui que a Terra se lavou com o dilúvio.",394],["Neste caminho os homens não cumprem os compromissos assumidos com as mulheres.",395],["Neste caminho Obatalá abrigou as rãs, que não tinham onde morar, em sua própria casa.",395]],"curiosities":[]},"ire":{"p":225,"text":"mudanças radicais são levadas a cabo com determinação e vistas como oportunidades."},"ibi":{"p":225,"text":"mudanças radicais conduzem à teimosia e à rigidez."}},"9:14":{"alias":"OSAXE","page":396,"phrase":"Osaxe Oni Xelí lodafun okó intorí Ogboni iwá ire omó.","sections":{"representation":[["Este Odu é filho de Osá e Oxe.",396],["Este Odu fala de amarrações.",396],["Este signo salva o padrinho.",396]],"native":[["Os filhos deste Odu, vivenciando seu osogbo, são pessoas falsas, traidoras e que não cumprem com a palavra.",398]],"reading":[["Fala de um homem que não possuía sombra.",396],["Assinala impotência sexual no homem.",397],["Assinala a inconformidade das mães diante do casamento de seus filhos.",397]],"care":[["Não deve permitir que as mulheres ponham as mãos em suas costas.",396]],"stories":[],"curiosities":[]},"ire":{"p":225,"text":"mudanças radicais conduzem à plenitude e à conexão. Há indício de fertilidade."},"ibi":{"p":226,"text":"a instabilidade e mudanças drásticas conduzem à perda de confiança e de condução interior, à desconexão e ao vazio. Há indício de infertilidade."}},"9:15":{"alias":"OSAFUN","page":399,"phrase":"Osafun obere imiro eró Olofin yeye oroni eru Olofin tete beru omó Oloyá eji elê omó Olofin kukuru oji ilê akukó metá elebó.","sections":{"representation":[["Este Odu é filho de Osá e Ofun.",399]],"native":[],"reading":[],"care":[],"stories":[["Neste caminho os jovens não querem respeitar os mais velhos.",400]],"curiosities":[]},"ire":{"p":226,"text":"mudanças radicais conduzem ao estado desejado de revelação de talentos, de visões e de resultados."},"ibi":{"p":226,"text":"mudanças radicais levam à ruína de ilusões e de utopias."}},"10:10":{"alias":"IKÁ MEJI","page":401,"phrase":"Iká Meji Igbo Ejioko ogué enegue okpague ede meji obede meji okunin iyebre ebó eiyé afuku xuorere adafun gbalami alafun arokoko orabo gbameli koruje elebute orubo Oyeku xigui afiyere xeun aro.","sections":{"representation":[["Este é um Odu masculino, filho de Katienadebú e de Katiebú.",401],["Representa a serpente mítica e sagrada.",401],["Representa segurança para o Awo.",401]],"native":[["O Awo deste signo, se lhe convier, pode chegar a ser um poderoso feiticeiro ou bruxo negro.",402],["Ao assentar Osain para um afilhado o Awo deste Odu tem que ter muito cuidado para não torná-lo mais poderoso que ele próprio.",402],["Os filhos deste Odu não têm amigos e não acreditam em ninguém.",402]],"reading":[["Assinala bruxarias e armadilhas.",401],["Assinala defeitos nas pernas e muito sofrimento ocasionado por cãibras.",403]],"care":[],"stories":[["Neste caminho falam Oxumarê, Ibeji, Xangô, Ogun, Iroko, Orunmilá e Nanã.",401]],"curiosities":[]},"ire":{"p":229,"text":"forte posição interior e possivelmente um forte poder da palavra."},"ibi":{"p":229,"text":"Fraqueza interior e colapso. Abuso da palavra."}},"10:0":{"alias":"IKABEMI","page":404,"phrase":"Babá Adelé Babá Fowoo ni Emité mabimú babá Adelé babá Fayani. Emité mabimu Babá Adelé Babá Fowaó vi eni lelé mabinú Ire bogbo bowebá feé bo layé enité mabinú.","sections":{"representation":[["Este Odu é filho de Iká e Ogbe.",404],["É um Odu de narcisismo e de ilusões, onde o que parece bom na realidade é mau.",404]],"native":[["A pessoa deste Odu tem medo da noite e tapa a cabeça na hora de dormir.",405]],"reading":[["Fala de um Egun familiar que está magoado com a pessoa e deseja destruí-la.",404],["Quando este Odu traz Osogbo, a primeira pessoa que neste dia chegar à casa do Awo tem que assentar Orunmilá para não morrer.",405],["Assinala problemas de embolias.",405]],"care":[["Determina que se deve ter cuidado com pessoas albinas, mulatas ou de pele manchada que representam os Arajés.",404],["O dono deste Ifá não deve ter afilhados para que estes não o destruam.",404],["Deve ter cuidado com escorregões e hérnias.",405]],"stories":[],"curiosities":[]},"ire":{"p":164,"text":"a contemplação conduz a um caminho aberto. A paciência é uma condição da felicidade. É possível reconhecer o caminho adequado através da essência, do centro."},"ibi":{"p":164,"text":"a incompreensão da essência conduz a decisões equivocadas. Esse Odu representa incompreensões e desvios dos elementos centrais de uma questão que conduzem a decisões equivocadas e à má condução de caminhos futuros."}},"10:1":{"alias":"IKÁYEKU","page":406,"phrase":"Iká Biku iyelerete Koleyuré yerú wara akunara ayé adifafun Oyeku, adifafun Iká Ikaborugbo eyedá Ogbado kukute kukú adifafun Oyeku umbati lomba olobote kaxé, owunko lebó, ekurú, etá lebó.","sections":{"representation":[["Este Odu é filho de Iká e Oyeku Fala de morte e de suicídio, uns nascem e outros morrem.",406],["Este Odu assinala que tanto o homem quanto a mulher têm dificuldades para encontrar seu par.",406]],"native":[],"reading":[],"care":[],"stories":[],"curiosities":[]},"ire":{"p":174,"text":"a força interior viabiliza a conclusão ativa de um ciclo."},"ibi":{"p":174,"text":"a dúvida e a fraqueza interior conduzem à má conclusão e ao fim."}},"10:2":{"alias":"IKÁIWORÍ","page":409,"phrase":"Ikaiworí, Iká Iborí. Iká Ioguifun, maferefun Yemanjá, adifafun Orunmilá, maferefun Oxun.","sections":{"representation":[["Este Odu é filho de Iká e Iwori.",409]],"native":[["SEGURANÇA PARA O AWO DESTE ODU.",410]],"reading":[["Assinala que a pessoa tem uma coisa que vai e vem de forma inconstante.",409]],"care":[["Não deve esperar agradecimento pelos favores que faça.",410]],"stories":[],"curiosities":[]},"ire":{"p":182,"text":"a força interior e uma posição segura favorecem a transformação e a descoberta da identidade."},"ibi":{"p":182,"text":"a força interior e uma posição segura colapsam, conduzindo a uma crise de sentido ou a uma estagnação."}},"10:3":{"alias":"IKADI","page":411,"phrase":"Ikadi Olofin Olowá Olorun simifun ejó ma kpé intori tiwo tixé eji afi wobú ni, bogbo eran ati ni, bogbo eran egbé moré niwo unjé lejó aijaré bogbo.","sections":{"representation":[["Este Odu é filho de Iká e de Odi.",411],["Este signo é a brasa do fogo de todos os demais Odu.",412]],"native":[["O Awo deste Odu tem que ter 16 crânios de galinha em cada uma de suas mãos de Ifá.",411]],"reading":[["Assinala que a pessoa encontrará a felicidade e desfrutará dela por toda a vida, mas para que isto aconteça, tem que dar comida a Xangô e agradecer-lhe por tudo.",411],["Assinala a morte de um chefe ou de uma autoridade de cargo muito elevado.",411],["Fala de uma doença que provoca picadas pelo corpo e que leva à morte.",412]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":188,"text":"a força interior favorece a renovação."},"ibi":{"p":188,"text":"a insegurança, a posição vulnerável e a falta de força impedem a renovação."}},"10:4":{"alias":"IKAIROSUN","page":413,"phrase":"Ikaroso Ikarabolá meniyeyé, Ikarabolá meni Iyá Omi Kesesé. Adifafun Orunmilá barabá niregun, opá elebó.","sections":{"representation":[["Este Odu é filho de Iká e de Irosun.",413],["Este Odu sempre estava presente nas reuniões dos Babalawos.",413],["É um Odu de roubos, amarrações, corrupção, contrabando e enganos.",414]],"native":[["Para que o Awo deste Odu não fique na miséria, tem que fazer ebó com seis moedas de prata, pois se o seu dinheiro acabar, virá a doença e a morte.",413]],"reading":[["Quando este Odu traz osogbo arun ou Ikú5, faz-se ebó com um galo e uma garrafa de aguardente.",413],["Assinala que existe um Orixá que é herança de família e que nunca foi cuidado por ninguém.",413],["Assinala que os irmãos mais velhos têm inveja do mais novo.",414]],"care":[],"stories":[["Neste caminho os homens se transformaram em gigantes, mais altos que as mais velhas palmeiras, aprenderam a linguagem dos animais e com os poderes que adquiriram, transformaram-se em grandes feiticeiros.",413],["Foi aqui que roubaram as vacas de Obatalá.",414]],"curiosities":[]},"ire":{"p":195,"text":"a força interior é a base para a realização dos potenciais e para a conexão familiar."},"ibi":{"p":195,"text":"a fraqueza interior impede a conexão familiar e a aceitação do destino."}},"10:5":{"alias":"IKÁWÓNRIN","page":415,"phrase":"Ikawónrin, Iká Wáwá adifafun Iká Odi ofuneke ounkó, akukó, eiyelé lebó.","sections":{"representation":[["Este Odu é filho de Iká e Owónrin.",415],["Este Odu proíbe seus filhos de comerem milho.",415]],"native":[["Os filhos deste Odu têm a cabeça muito grande e poderosa.",415],["As cabeças das pessoas deste Odu não podem receber sangue de nenhum animal.",415]],"reading":[["Fala de uma guerra que precisa acabar para que reine a paz e a cordialidade.",415],["Assinala falta de consideração.",415],["Fala de três qualidades de Orixá-Funfun: Talabí, Salakó e Talade.",415]],"care":[["Para evitar guerras a pessoa não deve se preocupar se o que possui é melhor ou pior que aquilo que os outros possuem.",415],["Esta é a sua mais grave interdição e seu maior tabu.",415]],"stories":[],"curiosities":[]},"ire":{"p":202,"text":"há força interior suficiente para a realização de revoluções no interior, como também para resisti-las."},"ibi":{"p":202,"text":"devido à fraqueza interior, a pessoa não consegue resistir ao caos interior. Há perigo de haver depressão ou uma “ruína total”."}},"10:6":{"alias":"IKABARA","page":417,"phrase":"Ikabara monxowo jilé xilopé adifafun Orogbé. Orogbé ekuré ejéré lebó. Iká Awo ojó Obara. Ile Awo jo adié lebó. Exú eiyelé, akukó lebó.","sections":{"representation":[["Este Odu é filho de Iká e Obara.",417]],"native":[],"reading":[["Assinala disputa de posição entre irmãos.",417],["Assinala troca de feitiços entre eles.",417],["Fala de um filho de Orixá e um macumbeiro que queria tirar o que era dele.",417]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":208,"text":"a força interior favorece uma transformação interior."},"ibi":{"p":209,"text":"um bloqueio interior, a falta de vontade e a fraqueza aumentam o egoísmo."}},"10:7":{"alias":"IKAKANRAN","page":419,"phrase":"Ikakanran Ifá Awo omó Okanran bogbo omó a laiye Elegbara ofo lodê akana suajú makenian lodafun Orunmilá.","sections":{"representation":[["Este Odu é filho de Iká e Okanran.",419]],"native":[],"reading":[],"care":[],"stories":[["Neste caminho o gato perseguiu a galinha d'angola até a casa de Obatalá.",419]],"curiosities":[]},"ire":{"p":213,"text":"a força interior e o poder da palavra criam espaço para o desenvolvimento do coração."},"ibi":{"p":213,"text":"o desequilíbrio interior, a fraqueza e um status frágil conduzem ao isolamento e à desistência."}},"10:8":{"alias":"IKÁOGUNDÁ","page":421,"phrase":"Ikagundá adifafun Osain, akukó lebó.","sections":{"representation":[["Este Odu é filho de Iká e Ogundá.",421],["Este Odu representa um barco e assegura a proteção de Inle e de Osain.",421]],"native":[["O Awo deste signo tem que dar comida à sua sombra.",421]],"reading":[],"care":[],"stories":[["Neste caminho Osain construiu ruas e abriu picadas.",422],["Neste caminho as promessas feitas não são cumpridas.",422]],"curiosities":[]},"ire":{"p":219,"text":"a força interior, a convicção e o poder da palavra favorecem a realização dos objetivos."},"ibi":{"p":219,"text":"a falta de convicção e a fraqueza interior conduzem à ruína ou à passividade."}},"10:9":{"alias":"IKÁSÁ","page":424,"phrase":"Ikásá adifafun Orunmilá, adifá joko matekun awe tinxiyawo odiê tinxiyá aguikó ofi osile onxe re Fá meofó, otá, epô, ewe.","sections":{"representation":[["Este Odu é filho de Iká e Osá.",424],["Este Odu fala de nostalgia.",425],["Este Odu nunca mais irá exigir sacrifícios de cabras.",425]],"native":[],"reading":[["Assinala infecções sangüíneas, problemas do coração e lepra.",425]],"care":[],"stories":[["Neste caminho Oiyá acorrentou os habitantes de Takpá e os apresentou em praça pública sob a acusação de haverem lhe negado sapotís.",424]],"curiosities":[]},"ire":{"p":224,"text":"a força interior ajuda o ser humano a enfrentar mudanças radicais."},"ibi":{"p":224,"text":"a fraqueza interior conduz à instabilidade e a processos inesperados que não podem ser contidos."}},"10:11":{"alias":"IKÁTURUKPON","page":426,"phrase":"Ikatrupon kukuté kukú adifafun Orunmilá, adifafun Olá Niká, eiyelé lebó.","sections":{"representation":[["Este Odu é filho de Osá e Oturukpon.",426]],"native":[["O Awo deste Odu tem que ter três Elegbara.",427]],"reading":[["Assinala fogo uterino e problema na barriga.",426],["Quando este Odu traz Osogbo no Itá, prepara-se um xeré11 de cabaça para ficar junto com o Elegbara da pessoa.",427]],"care":[["A pessoa praticou uma má ação e deve ter cuidado para não se meter em encrencas.",426],["Deve ter cuidado com um engano que produziu ou deseja produzir.",426]],"stories":[["Neste caminho soltaram os cães contra Orunmilá que para defender-se teve que subir num pé de louro.",426]],"curiosities":[]},"ire":{"p":229,"text":"a força interior supera fases complicadas e conduz à saúde e ao crescimento."},"ibi":{"p":229,"text":"a fraqueza interior e o mau uso da palavra conduzem à doença, ao recuo e ao retrocesso."}},"10:12":{"alias":"IKÁTURÁ","page":428,"phrase":"Ikáturá, Iká Foguero, kombú, kombó, adifafun oni biní eiyelé lebó. Kaferefun Oiyá, Alá, ati Olorun.","sections":{"representation":[["Este Odu é filho de Iká e de Otura.",428],["Este Odu proíbe seus filhos de possuírem cães ou tê-los em suas casas.",429]],"native":[],"reading":[["Assinala impotência para o homem jovem.",428],["Assinala que a pessoa, na velhice, ficará inutilizada da cintura para baixo e morrerá do coração.",428],["Assinala insegurança e falta de tranqüilidade pelo futuro dos filhos.",428]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":229,"text":"a força interior viabiliza as visões interiores."},"ibi":{"p":230,"text":"a fraqueza interior conduz à falta de visão, à ilusão e ao autoengano."}},"10:13":{"alias":"IKÁRETE","page":430,"phrase":"Ikarete omó Oluxe, Irete Oma, ileké kiri kiri banlá abanijé batitu eure, eiyelé lebó.","sections":{"representation":[["Este Odu é filho de Iká e Irete.",430],["Este Odu prende as pessoas.",430]],"native":[],"reading":[["Quando surge este Odu tem que se tocar o peito com o punho esquerdo.",430],["Fala de infiltrações pulmonares que levam à morte.",430]],"care":[],"stories":[["Foi aqui que Orunmilá disse a Obatalá que fosse colher inhames e que os descascasse e jogasse as cascas na rua para que tivesse boa sorte.",430]],"curiosities":[]},"ire":{"p":230,"text":"a força interior é a base para uma ação com firmeza."},"ibi":{"p":230,"text":"o colapso interior e a fraqueza interior impedem a pessoa de agir com determinação."}},"10:14":{"alias":"IKÁXE","page":432,"phrase":"Ikaxe ninxé, Iká miro kiri, Iká mu kirí, adifafun Orunmilá. Kiopeyé, ounkó, agutan lebó.","sections":{"representation":[["Este Odu é filho de Iká e de Oxe.",432],["É um Odu de sacrifícios que jamais são reconhecidos.",433]],"native":[["As pessoas deste Odu devem usar coral junto do corpo.",432]],"reading":[["Quando este Odu aparece numa consulta, cobre-se Exú com folhas que depois se despacha para a rua.",432],["Assinala morte por problemas cardíacos.",432]],"care":[],"stories":[["Neste caminho surgiu a controvérsia sobre a preferência de Olofin entre o azeite de dendê e o óleo de algodão, ficando estabelecido que o óleo de algodão é o preferido de Olofin.",432]],"curiosities":[["Por este motivo Ikaxe é também chamado de Ikafá.",432],["Por este motivo este Odu é também conhecido como Ikáselá.",432]]},"ire":{"p":230,"text":"a força interior conduz a uma forte conexão espiritual, como também à plenitude, à abundância e à fertilidade."},"ibi":{"p":230,"text":"uma desavença interna e a fraqueza conduzem à ganância, ao vazio e à falta de conexão."}},"10:15":{"alias":"IKÁFUN","page":434,"phrase":"Ikafun loroní kiyaté adifafun Abiregún akukó, eiyelé lebó.","sections":{"representation":[["Este Odu é filho de Iká e de Ofun.",434]],"native":[],"reading":[["Quando este Odu surge na consulta de uma mulher, é Orunmilá ordenando que ande com os cabelos soltos durante sete dias.",434]],"care":[],"stories":[["Neste caminho agrada-se a Ogun com três obís, sendo que um é untado com mel, o outro com ori-da-costa e o terceiro com azeite de dendê.",435]],"curiosities":[]},"ire":{"p":230,"text":"a força interior conduz à revelação."},"ibi":{"p":230,"text":"a fraqueza interior impede a revelação e conduz os grandes objetivos da vida ao fracasso."}},"11:11":{"alias":"OTURUKPON MEJI","page":437,"phrase":"Oturukpon Meji oboro ni xoro logun ni faderé ni xado oku ni, faderé ni xoro, oku no faderé Babalawo todi fun tokutu axoro ekun. Oloro toroxo adifafun ekun.","sections":{"representation":[["Representa a gravidez, as inchações e de forma geral, tudo o que é arredondado - rostos redondos, seios grandes, protuberâncias anormais como hérnias, elefantíase, furúnculos, tumores e inchações diversas.",437],["É um Odu ligado às Ajés1e segundo dizem, foi o criador da diarréia.",437],["Este Odu trouxe ao mundo os pigmeus e os anões.",439]],"native":[["Os filhos deste Odu são pessoas destinadas ao sucesso, a galgarem altos postos, devendo para isso submeterem-se com muito boa vontade aos sacrifícios exigidos.",438],["Quando o Awo deste Odu faz ebó, é sua mãe, se for viva, quem deve despachá-lo.",439],["O Awo deste Odu não deve permitir que a mulher o morda na hora de fazer sexo pois isto compromete seu interesse pelo sexo.",440]],"reading":[["Fala de inversões sexuais e de bruxarias feitas através de comidas ou bebidas.",438],["Indica que a mulher trai o marido e que se ainda não o fez, é por falta de oportunidade.",438],["Assinala inversão sexual, enfermidades e bruxarias por comidas e bebidas.",438]],"care":[["O Awo deste Odu não deve permitir que a mulher o morda na hora de fazer sexo pois isto compromete seu interesse pelo sexo.",440]],"stories":[["Foi por este caminho que Orunmilá transmitiu sua ciência aos sábios para que eles pudessem ensinar aos homens comuns.",439]],"curiosities":[["Oturukpon Meji, décimo segundo signo na ordem de chegada em Ifá e último de uma série de forças misteriosas que, segundo se afirma, estão associadas aos signos do zodíaco.",440]]},"ire":{"p":234,"text":"crescimento e saúde."},"ibi":{"p":234,"text":"retrocesso, cancelamentos e doença."}},"11:0":{"alias":"OTURUKPONLOGBE","page":443,"phrase":"Oturukponbekonwa apupá palapá adifafun Xangô kukute kukú adifafun Alun Oloje tinxoma Olofin eleiye lebo. Adifafun Ibán ajará akukó lebó. Kpagefe iyele kofelé adó iyu omigun adifafunreré. Awoeure lebó, eiyelé lebó.","sections":{"representation":[["Este Odu é filho de Oturukpon e Ogbe.",443],["Este é o signo dos piratas.",443],["Neste signo nasceu a roda.",445]],"native":[],"reading":[["Assinala dívidas com Xangô.",443],["Assinala sofrimento do estômago, da barriga, dos pulmões.",443]],"care":[["Não deve comer nem beber nada que lhe dêem tampado.",444]],"stories":[["Neste caminho existe um Egun que foi carroceiro e que guia a pessoa pelos caminhos da vida, seu nome é Aborotifá Egun Laiye Afefe.",444],["Neste caminho a pessoa tem que cultuar Xangô, Orixaoko e cuidar do Egun Afefe Laiye.",444]],"curiosities":[]}},"11:1":{"alias":"OTURUKPON YEKU","page":446,"phrase":"Oturukpon Yeku, Oyekuyé, Ikú Yeye adifafun Iroko.","sections":{"representation":[["Este Odu é filho de Oturukpon e Oyeku.",446],["Este Odu assinala sempre enfermidades, mesmo quando traz ire.",447]],"native":[["As pessoas deste signo não podem usar roupas nem objetos negros.",446]],"reading":[["Assinala ressentimento entre irmãos carnais, de Santo ou de Ifá.",446],["Assinala a presença de Abíkú.",447]],"care":[["A pessoa não deve comer em casa estranha.",446]],"stories":[],"curiosities":[]},"ire":{"p":174,"text":"o crescimento e a saúde são boas condições que viabilizam a conclusão de etapas necessárias."},"ibi":{"p":174,"text":"a doença ou a estagnação impedem que etapas sejam concluídas, ou levam à má conclusão."}},"11:2":{"alias":"OTURUKPONIWORÍ","page":448,"phrase":"Otrupon Adawene fun alabe tisayo Awo ipomega guida mefa adifafun Baba Olojo, lebó eleiyé, akukó lebó.","sections":{"representation":[["Este Odu é filho de Oturukpon e Iwori.",448],["Este signo assinala vida curta.",448],["Este Odu rouba dez anos de vida ao padrinho e, para que isto não aconteça, tem que fazer um grande orô para Oiyá.",449]],"native":[["Quando o Awo deste signo sai do Igbodun Ifá, tem que assentar Oduduwa imediatamente.",449]],"reading":[["Quando surge numa consulta de okpele, o Awo joga seu rosário no chão fora da esteira e pede a uma donzela que o pegue, vai até a porta de entrada e dali, arrasta o okpele pelo chão até o local onde lhe foi entregue.",448],["Quando surge num atefá, coloca-se a mão com que se esteja marcando Ifá no solo e se sopra Otí e mel antes de continuar a consulta.",448],["Assinala que a pessoa vai receber a notícia da morte de alguém que saiu em viagem na companhia de outras pessoas.",449]],"care":[["Não deve viajar nem sair muito de casa, existe alguém que espera o momento para matá-la.",449]],"stories":[["Neste caminho, o Awo tem que ter uma foice? com um cabo do seu tamanho.",449]],"curiosities":[]},"ire":{"p":182,"text":"um crescimento exterior favorece a formação interior da identidade e a transformação."},"ibi":{"p":182,"text":"um colapso exterior ou uma estagnação conduzem ao conflito interno e à crise de sentido."}},"11:3":{"alias":"OTURUKPONDI","page":450,"phrase":"Oturukpondi tajéun ni na awo aiye ni kanlé komo adifafun Ojoko Arere. Adie lebó, akukó. Adifafun Orunmilá, akukó, eni adié, abo lebó.","sections":{"representation":[["Este Odu é filho de Oturukpon e Odi.",450]],"native":[],"reading":[["Assinala existência de um espírito que faz parte da vida da pessoa.",450],["Assinala impotência e intervenções cirúrgicas.",450]],"care":[["Quando sai este Odu, a pessoa para quem sair não deve comer pescado nem carne de caça durante sete dias.",450],["Não deve comer nenhum tipo de comida enlatada.",450]],"stories":[],"curiosities":[]},"ire":{"p":188,"text":"o novo crescimento conduz à renovação e ao renascimento."},"ibi":{"p":189,"text":"a doença ou o retrocesso impede a mudança e a renovação."}},"11:4":{"alias":"OTURUKPONROSUN","page":452,"phrase":"Otrupon Koso ako anejó komado adifafun Ladutá, eleiye oguedé lebó. Akukó, eiyelé lebó. Kaferefun Xangô Obatalá ati Orunmilá.","sections":{"representation":[["Este Odu é filho de Oturukpon e Irosun.",452],["Este é o Odu dos irmãos e dos cavalos.",453]],"native":[],"reading":[["Fala de um homem que dava muita sorte com as mulheres e, havendo conquistado a filha do rei, acabou destruído pelos ciúmes das outras que havia desprezado.",453]],"care":[["Não deve subir ou descer escadas correndo e se montar a cavalo, não deve correr com sua montaria.",453]],"stories":[],"curiosities":[]},"ire":{"p":196,"text":"o novo crescimento e a saúde favorecem a realização dos potenciais e uma nova conexão com a família e com o destino."},"ibi":{"p":196,"text":"o retrocesso e a doença impedem a realização dos potenciais e perturbam a harmonia familiar."}},"11:5":{"alias":"OTURUKPONWÓRIN","page":454,"phrase":"Otruponwáni deni midi xenimoni otá keké Orunmilá olodafun Odé, akukó, eiyelé, adie lebo.","sections":{"representation":[["Este Odu é filho de Oturukpon e Owónrin.",454]],"native":[["O Awo deste Odu não pode quebrar cocos.",455]],"reading":[["Assinala armadilhas no matrimônio.",454],["Assinala um segredo sobre a paternidade de um membro da família.",454],["Assinala perdas em todos os setores da vida, ocasionadas por um Egun enviado por alguém para este fim.",454]],"care":[],"stories":[["Foi por este caminho que os Eguns materializarem-se com formas humanas para participarem do banquete, sendo descobertos e desmascarados por Orunmilá.",454]],"curiosities":[]},"ire":{"p":202,"text":"uma saúde forte protege a pessoa de mudanças inesperadas."},"ibi":{"p":202,"text":"a doença gera caos."}},"11:6":{"alias":"OTURUKPONBARA","page":456,"phrase":"Oturukpon Obaraifé ojugbolo kan uá okú eni lodafun Orunmilá luba onlé ile Onifé eiye ejá lodenben Okanran ingará okaji aunbarin aiye obe loda kaferefun Orixaoko, Xangô, Orunmilá ati Ogun.","sections":{"representation":[["Este Odu é filho de Oturukpon e Obará.",456]],"native":[],"reading":[["Assinala perdição de homem por causa de mulher e de mulher por causa de homem A pessoa tem que dedicar especial atenção às suas pernas, sofre de dores nos pés, de hérnias e do coração.",456],["Assinala desavença em casa.",457],["Assinala desordens cerebrais.",457]],"care":[["Não deve fazer mal a ninguém, tampouco deve ajudar a quem quer que seja para que sua vida não se atrase.",456]],"stories":[["Foi neste caminho que o bode, por fazer favores, perdeu a cabeça.",456]],"curiosities":[]},"ire":{"p":209,"text":"o crescimento e uma saúde forte viabilizam um processo de transformação interior."},"ibi":{"p":209,"text":"uma saúde frágil e a deterioração de projetos e relacionamentos inviabilizam uma transformação interior, conduzindo ao egoísmo e ao narcisismo."}},"11:7":{"alias":"OTURUKPONKANRAN","page":458,"phrase":"Otruponkana Karán Oturukpon Olokanran guni bedi oxika tane kobe Axé araí batá fun Babalawo lodafun kuobá tiere oibo leri.","sections":{"representation":[["Este Odu é filho de Oturukpon e Okanran.",458]],"native":[],"reading":[["Prenuncia morte em qualquer circunstância.",458]],"care":[],"stories":[["Neste caminho Exú e Ogun pedem ebó ejé.",458],["Neste caminho se faz ebó para espantar Ikú com uma cabaça, um pedaço de fígado bovino, mariwo picado e duas estacas de madeira.",458]],"curiosities":[]},"ire":{"p":214,"text":"a saúde e o crescimento favorecem os projetos do coração e dão força para novos temas e relações."},"ibi":{"p":214,"text":"doenças e retrocessos conduzem ao isolamento, bloqueando caminhos. O momento não é oportuno para começar novos projetos."}},"11:8":{"alias":"OTURUKPONGUNDÁ","page":461,"phrase":"Oturukpon Anguedé Obinin kan lonló, Obinin, okuni lofé opá ekó umbó maferefun Orunmilá ati Iyalode. Lodafun Ogun ati Obinin.","sections":{"representation":[["Este Odu é filho de Oturukpon e Ogundá O grande inimigo da pessoa é do sexo feminino.",461],["Este Odu assinala presença de Abíkú.",461]],"native":[],"reading":[["Assinala destruição do lar por agressão mútua entre os cônjuges.",461],["Assinala doenças nos pés, na cabeça ou nas vistas.",461]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":219,"text":"a saúde e o crescimento são excelentes condições para futuras controvérsias e para a realização de objetivos pessoais."},"ibi":{"p":219,"text":"uma saúde frágil, negócios não rentáveis e o fim de relações desfavorecem a posição necessária para a realização dos objetivos pessoais."}},"11:9":{"alias":"OTURUKPONSÁ","page":463,"phrase":"Oturukponsá Ofun lorugbó ejó kolose akiti legbo abiyé mala mala adifafun Loko tinxoma Orixá irin auní xexun ofidan eiyelá lebó. Kafarefun Omofá, Orunmilá ati Exú.","sections":{"representation":[["Este Odu é filho de Oturukpon e Osá.",463],["Este Odu assinala a existência de um Orixá adquirido por herança.",463]],"native":[["Os filhos deste Odu são indômitos, não gostam de ser mandados.",463]],"reading":[["Fala de um Egun chamado Adokino que em vida era efeminado.",463],["Assinala que todos aqueles que hoje depreciam a pessoa, amanhã se arrastarão aos seus pés.",463],["Assinala que a pessoa, por questões emocionais, tranca-se em casa a chorar e por este motivo pode sofrer um mal súbito e passar por um grande susto.",464]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":225,"text":"a pessoa tem uma boa constituição para enfrentar turbulências purificadoras que estão por vir."},"ibi":{"p":225,"text":"a má condição da pessoa e pilares frágeis não conseguem conter as mudanças que estão por vir."}},"11:10":{"alias":"OTURUKPONKÁ","page":465,"phrase":"Oturukponká Oturupando, Oturupanko, adifafun ana omó Ogun ke Akukó lebó. Ka Oturukpon ká adifafun Obá ounko, akukó lebó.","sections":{"representation":[["Este Odu é filho de Oturukpon e Iká.",465]],"native":[],"reading":[["Assinala morte e destruição em família.",465]],"care":[],"stories":[["Foi por este caminho que a árvore iroko se negou a servir de cabo para o machado, sabendo que isto seria o fim de todas as árvores.",465]],"curiosities":[]}},"11:12":{"alias":"OTURUKPONTURÁ","page":467,"phrase":"Otrukponturá ire nifá pori Ifá ni kaferefun Obatalá ati Xangô.","sections":{"representation":[["Este Odu é filho de Oturukpon e Otura.",467],["Este Odu criou as dores do parto.",467]],"native":[],"reading":[],"care":[["Para que a sorte chegue até ela, não deve maldizer, renegar ou discutir com ninguém.",467]],"stories":[],"curiosities":[]},"ire":{"p":234,"text":"uma boa constituição e o crescimento são uma boa base para novas visões."},"ibi":{"p":234,"text":"uma saúde vulnerável ou uma doença conduz ao autoengano e às ilusões."}},"11:13":{"alias":"OTURUKPONBIRETE","page":469,"phrase":"Oturukponbirete Ifá Ajalú Xixé xé adifafun Ajalú pueté morubó Omó Xenxe xé ni Oló Babalawo adifá Babalawo Olofin. Jelú puelú oda Osain morubó. Owunko xelú, akukó lebó.","sections":{"representation":[["Este Odu é filho de Oturukpon e Irete.",469],["Este Odu fala do encontro do rio com o mar.",469],["Este é um Odu de desmanches.",470]],"native":[["Os filhos deste Odu não podem comer pescado.",469]],"reading":[["Assinala, para o Babalawo, que uma pessoa que está a caminho necessita receber fio de contas de Orixá e assentar Orunmilá.",469]],"care":[],"stories":[["Neste caminho o mar fez ebó e por isto se limpou.",469],["Neste caminho os pescadores capturavam os peixes tão longe da costa que, quando regressavam, os peixes estavam podres.",470]],"curiosities":[]},"ire":{"p":235,"text":"uma boa constituição e o crescimento estimulam a ação externa. As condições estão favoráveis para a concretização de novos temas."},"ibi":{"p":235,"text":"a tendência negativa dos negócios e das relações, como também uma saúde frágil, conduzem à letargia ou a ações exageradas."}},"11:14":{"alias":"OTURUKPONXE","page":471,"phrase":"Oturukponxe Ifá Elá rudalé Awo Obá nitepá ileké olá nitepá oxede odafun bogbo Irunmolé tinló okú akasá eiyelé, adié, lebó.","sections":{"representation":[["Este Odu é filho de Oturukpon e Oxe.",471]],"native":[],"reading":[["Assinala risco de problemas relacionados a documentos.",471],["Fala de denúncias, demandas e assuntos de justiça.",471],["Assinala cobrança de dívidas.",471]],"care":[["A pessoa não deve permitir que um acontecimento desgastante de sua vida volte a acontecer.",471],["Não deve confiar em ninguém e conferir todos os documentos que lhe digam respeito antes de recebê-los ou assiná-los.",471]],"stories":[],"curiosities":[]},"ire":{"p":235,"text":"uma boa constituição e o crescimento conduzem à plenitude espiritual, material e emocional."},"ibi":{"p":235,"text":"os negócios em mau andamento e a falta de condicionamento físico conduzem a perdas."}},"11:15":{"alias":"OTURUKPONLOFUN","page":473,"phrase":"Oturukponbalofun Babá Bato, Babá Fetó lodafun Inle. Lodafun Olonú adifafun Obatalá, Oiyá, ati Orunmilá lorugbó.","sections":{"representation":[["Este Odu é filho de Oturukpon e Ofun.",473]],"native":[],"reading":[["Assinala covardia e suicídio.",473],["Assinala que foi feito uma promessa diante de um morto, quer seja de vingá-lo quer seja de terminar alguma coisa que ele deixou inacabada.",473]],"care":[["Não deve fazer mais favores e tudo o que fizer deve ser cobrado.",473]],"stories":[["Neste caminho se oferece sacrifício de ejé a Xangô no meio de quintal e deixa-se ali por quatro dias.",473],["Neste caminho o punhal é o primeiro a provar tudo e, desta forma, corta o que é bom e o que é ruim.",473]],"curiosities":[]},"ire":{"p":235,"text":"uma boa constituição e o crescimento conduzem à revelação e ao objetivo desejado."},"ibi":{"p":235,"text":"a doença, os fracassos e a falta de condicionamento físico conduzem ao fracasso de objetivos e ao colapso de utopias."}},"12:12":{"alias":"OTURA MEJI","page":475,"phrase":"Kerenxele agbo nipapo, lodafun Inle nipapo, gere, gere, nipapo lorubo gere gere nipapo kite joro lodafun osukun adifun nibeti un kagbalori. Peronxele agbo nipapo lodafun kekere papo lapo papo lorubo kekere Orunmilá lofo untori bogbo tenijé lorubo.","sections":{"representation":[["Este Odu ensina aos homens os poderes e os segredos das raízes e dos ramos das árvores.",476],["É um Odu de vida curta, no entanto recebe o título de Pai da Vida.",476],["Este é o Odu da sabedoria, das saudações e das reverências.",476]],"native":[["As pessoas deste signo não devem agir de forma destemida, é com inteligência e calma que derrotam seus inimigos.",476],["Os Awo deste signo têm que fazer um trabalho para neutralizar o mal que as mulheres lhes ocasionam naturalmente.",478]],"reading":[["Assinala abandono e descuido.",476],["Assinala pureza de sentimentos, elevação espiritual e material, conquista de altas posições, a cólera dos homens, sofrimento por viver-se entre feras, lucros obtidos em viagens e morte prematura ocasionada por doença repentina.",476],["Assinala grande proteção de Xangô.",477]],"care":[["Não deve guardar objetos de ninguém em sua casa para não se ver envolvida com a lei.",477]],"stories":[["Neste caminho falam Obatalá, Elegbara, Oduduwa, Aje Xaluga, Orunmilá e Xangô.",475],["Foi neste caminho que o homem dominou a todos os animais, sendo então declarado por eles, rei e senhor da criação.",476],["Neste caminho a desobediência se paga com a morte.",477]],"curiosities":[["Otura Meji é o décimo terceiro Odu na ordem de chegada de Ifá, sendo conhecido também como Otuwa entre os nagôs, termo que, em yorubá, significa: \"Tu estás de volta\".",475]]},"ire":{"p":238,"text":"a força de visão e de criação estão em equilíbrio com o destino pessoal."},"ibi":{"p":238,"text":"ilusão, autoengano, utopia."}},"12:0":{"alias":"OTURAGBE","page":479,"phrase":"Oturaniko liko ikorewá, liko ikobié kosi, adifafun Daduro, abo ati otí elebó.","sections":{"representation":[["Este Odu é filho de Otura e Ogbe.",479],["Este signo não admite demoras.",479],["Este Odu é capataz de Egun.",479]],"native":[["As pessoas deste Odu não podem matar insetos.",479],["Os filhos deste Odu não podem viver na companhia de filhos de Iyemanjá.",480],["AXÉ DE SEGURANÇA PARA AS PESSOAS DESTE ODU Pega-se um alguidar pequeno e marca-se dentro os signos de Oxetura, Oturagbe e Oturaxe.",481]],"reading":[["Assinala, nas pessoas de luz, o poder de fazer o mal.",479],["Fala de evolução espiritual.",479],["Quando surge osogbo Ikú por este caminho, é muito difícil que haja salvação.",479]],"care":[],"stories":[["Neste caminho Orunmilá viveu na terra Ijexá.",479]],"curiosities":[]},"ire":{"p":165,"text":"a visão interior lúcida conduz a um percurso consciente do caminho, em equilíbrio com o destino. Esse Odu representa o equilíbrio entre as visões do interior e a vida."},"ibi":{"p":165,"text":"a falta de visão interior impede que os caminhos se abram. Esse Odu adverte que pode haver desorientação, caso as visões do interior estejam bloqueadas."}},"12:1":{"alias":"OTURAYEKU","page":482,"phrase":"Oturayeku malu awoniká adifafun Oniká akukó lebó aguiubó abure kokó ogo, adifafun Aki umbatinló lowo balá ayelegun lebó agutan, eiyelé, etú lebó.","sections":{"representation":[["Este Odu é filho de Otura e Oyeku.",482]],"native":[["Quando a pessoa deste signo vive o seu osogbo, é perseguida por Exú que a castiga atrapalhando toda a sua vida.",483]],"reading":[],"care":[],"stories":[["Foi neste Odu que Lucifer tentou Jesus Cristo mostrando-lhe, do alto de uma montanha, todos os reinos deste mundo.",482]],"curiosities":[]},"ire":{"p":174,"text":"uma forte visão permite que projetos e fases sejam realizados."},"ibi":{"p":174,"text":"a falta de visão encerra temas, relacionamentos e etapas."}},"12:2":{"alias":"OTURAIWORI","page":484,"phrase":"Oturaiwori adifafun Iyami Ajé, Iyemanjá ofó Orixá imole orubo, Babá Olokun fimideregbé, Egun Olona Okun Mayewa lelé ofo leri, ofo eledá. Kaferefun Olokun, lodafun Orunmilá.","sections":{"representation":[["Este Odu é filho de Otura e Iwori.",484],["Este Odu fala de uma rainha que, depois de destronada, foi recolocada em seu trono por vontade do povo.",484]],"native":[],"reading":[["Indica que a pessoa tem problemas com a memória, com as vistas e com o estômago.",484]],"care":[],"stories":[["Neste caminho Elegbara se consagrou no rio.",484]],"curiosities":[]},"ire":{"p":182,"text":"a visão interior conduz à transformação e à descoberta da identidade."},"ibi":{"p":182,"text":"o autoengano conduz a conflitos internos e à crise de sentido."}},"12:3":{"alias":"OTURADI","page":486,"phrase":"Oturadí adifafun Elegbara Abeyalini, Inle Omode Osain abayebe Awo Iyá ni Osain mowani Elegbara unbiwasije Awo Ifá Moya re Osain Ajapá lebó.","sections":{"representation":[["Este é o Odu filho de Otura e Odi.",486],["É um Odu de traições, onde as pessoas confirmam seus segredos a outras que, de forma traiçoeira os tornam públicos.",486],["Este Odu é o caminho dos trovões, sempre que aparece troveja antes de decorrerem sete dias.",486]],"native":[],"reading":[["Quando surge este Odu, pergunta-se se Orunmilá dá autorização para se fazer ebó para o consulente.",487]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":189,"text":"a visão interior conduz ao renascimento e à renovação."},"ibi":{"p":189,"text":"uma ilusão conduz a decisões ou interpretações equivocadas. A renovação é impedida ou falha. A ilusão cria motivos falsos para a renovação e provoca o apego."}},"12:4":{"alias":"OTURAROSUN","page":488,"phrase":"Oturarosomun adawá dirosun oyerawo odeyasi malaluxero. Biwo esé burukú Olorun ojú ri wón.","sections":{"representation":[["Este Odu é filho de Otura e Irosun.",488],["É um Odu de possuir muitos cônjuges não importando se é homem ou mulher.",488]],"native":[["Os filhos deste Odu não podem deitar-se ou sentar-se no chão.",488],["O Awo deste Odu tem que levar um pedacinho de galho de moruro (Psychotria brownel - A.",489],["O Awo deste signo não pode praticar sexo oral para não perder seu Axé.",489]],"reading":[],"care":[["A pessoa não deve esperar nenhum crédito relativo a qualquer bom ato que tenha praticado.",488]],"stories":[["Neste caminho não se oferece sacrifícios de sangue, só os adimús são permitidos.",488],["Neste caminho a salvação vem através de Oduduwa.",488]],"curiosities":[]},"ire":{"p":196,"text":"a visão mística interior conduz à realização dos potenciais."},"ibi":{"p":196,"text":"o autoengano conduz à resistência e à má interpretação do destino, como também a conflitos familiares."}},"12:5":{"alias":"OTURAWONRIN","page":490,"phrase":"Otuwonrin Awolé Awoxololo Awo Olele. Alaketu Oni owayé adifafun Olofin, Exú, Exú Bi.","sections":{"representation":[["Este Odu é filho de Otura e Owónrin.",490]],"native":[],"reading":[["Fala de seqüelas provocadas por fraturas nas pernas.",490],["Assinala a presença de Abíkú.",490],["Assinala que a pessoa está implorando aos Santos por dinheiro, um homem ou uma mulher que se foi.",490]],"care":[["O mais novo dos três, vendo o que haviam feito aos seus irmãos, correu a consultar Ifá, e na consulta surgiu Oturawonrin e Orunmilá então lhe disse: - “Vá para casa e evite contato com pessoas jovens.",491]],"stories":[],"curiosities":[]},"ire":{"p":203,"text":"a visão interior protege e conduz durante um processo de revolução interior."},"ibi":{"p":203,"text":"a ilusão e o autoengano causam revoluções interiores fora de controle."}},"12:6":{"alias":"OTURABARA","page":492,"phrase":"Oturabara, Oturamuni, Iyá woloni Ifá lowa lewá xilekun ariku Baba wá.","sections":{"representation":[["Este Odu é filho de Otura e Obara.",492],["Este Odu assinala sadismo.",492],["Neste signo nasceu Exú Laboni, resultado da união de Obatalá com Oxun.",493]],"native":[],"reading":[["Fala de Eguns que vivem em pântanos e lodaçais.",492],["Fala de um adivinho muito feio ao qual Xangô, por inveja, mandou que o ajapá comesse os testículos.",492]],"care":[],"stories":[["Foi neste caminho que Exú Laboni tocou pela primeira vez na porta dos Orixás.",492],["Foi neste caminho que teve inicio a guerra entre Osain e Obaluaye.",492],["Neste caminho faz-se ebó com uma cinta bem apertada.",492]],"curiosities":[["Neste Odu nasceu Averekete, também chamado Houla ou Xomafo.",492]]},"ire":{"p":209,"text":"uma visão conduz à transformação interior e à humildade."},"ibi":{"p":209,"text":"o autoengano fomenta e aumenta o egoísmo."}},"12:7":{"alias":"OTURAKANRAN","page":494,"phrase":"Oturatiku leri Awo monanã abelulojé birá ború Ikú awele.","sections":{"representation":[["Este Odu é filho de Otura e Okanran.",494]],"native":[["As pessoas deste Odu não podem viver com filhos de Xangô.",494]],"reading":[["Quando surge numa consulta abre-se e fecha-se por três vezes a porta de casa e as três primeiras pessoas que chegarem tem que fazer ebó.",494],["Assinala o início da cerimônia de Olofin.",494],["Assinala morte precoce para quem se consulta.",494]],"care":[["A pessoa tem tendências a se resfriar com excessiva facilidade, por este motivo não deve andar descalça nem se expor à friagem.",494],["A pessoa não deve lançar maldições e nem permitir que ninguém o faça dentro de sua casa.",495]],"stories":[["Neste caminho, as mães não acreditavam em Olofin e nem ouviam os conselhos de seus próprios filhos e, por este motivo, morriam jovens e deixavam os filhos órfãos e desamparados.",494]],"curiosities":[]},"ire":{"p":214,"text":"novas visões abrem novas perspectivas."},"ibi":{"p":214,"text":"o autoengano e o pessimismo conduzem à desistência e ao isolamento."}},"12:8":{"alias":"OTURAGUNDÁ","page":496,"phrase":"Oturagundá ire ajê Timbelaye, ire ilé Osain. Oturairá Ogundá ire Ogun Alagbedé Inle mopun, Ogun jé, Ogun jé, Ogun jé mowa Iye Ogun Onire. Orunmilá Obarabaniregun ire metá ebó axegun otá lese Ogun.","sections":{"representation":[["Este Odu é filho de Otura e Ogundá.",496],["Este é um Odu de espíritas e de grandes videntes.",496]],"native":[["Os filhos deste Odu são pouco considerados pelos seus semelhantes.",496],["Os Awo deste Odu devem ser evitados porque roubam a sorte das pessoas que andam em sua companhia.",496],["SEGREDO DO ODU O Ogun do Awo deste signo tem que levar 101 ferramentinhas.",497]],"reading":[["Prenuncia problemas de justiça e operações cirúrgicas.",496],["Assinala a existência de um Egun que faz com que a pessoa seja inimiga de sua própria mãe.",497]],"care":[],"stories":[["Foi neste caminho que a mãe de Ogun o criava entre efeminados.",496],["Foi aqui que certo Awo fez o primeiro Axé Osain e por isto ganhou muito dinheiro e mil ajapás.",496]],"curiosities":[]},"ire":{"p":220,"text":"uma visão interior convicta é essencial para a concretização dos ideais, eliminando barreiras externas."},"ibi":{"p":220,"text":"o autoengano e ilusões conduzem a conflitos e à passividade."}},"12:9":{"alias":"OTURASÁ","page":498,"phrase":"Oturasá impojampô, gueguerê nifá, impojampô Owe omó Lampé Xangô, Lampé Olorun. Oturasá owo epô okojoni.","sections":{"representation":[["Este Odu fala de fenômenos meteorológicos.",498],["Este é um Odu de bruxarias.",499]],"native":[["Os filhos deste Odu têm que botar em Oiyá uma máscara com cara de leão, um dente e uma garra deste animal.",498],["Para que o Awo deste Odu não morra de forma súbita e precoce tem que fazer um boneco cujo tamanho seja correspondente à distância exata de seus joelhos ao seu coração.",499],["As pessoas deste Odu não podem viver na companhia de filhos de Ogun.",499]],"reading":[],"care":[["É amaldiçoado pelas mulheres, não deve viver com mulher branca e morre ferido pelas costas.",498]],"stories":[["Neste caminho Yewá destruiu a terra de Oturasá com folhas de salsa.",498],["Neste caminho Ogun come ajapá e se oferece inhame a Obatalá. cercadas de áreas mais escuras provocadas por má distribuição do pigmento cutâneo.",498]],"curiosities":[]},"ire":{"p":225,"text":"a força de visão interior conduz durante um processo de mudanças radicais."},"ibi":{"p":225,"text":"o autoengano e ilusões conduzem ao desequilíbrio e a graves mudanças."}},"12:10":{"alias":"OTURAKA","page":500,"phrase":"Oturaká adifafun Obanilá Koade wowé eni weré bogbo mabinú unbó wá Orunmilá lofobani Exú mafun Oturaká adê lebó.","sections":{"representation":[["Este Odu é filho de Otura e Iká.",500],["Este signo assinala impotência.",500],["Este Odu assinala a existência de um morto que deseja ajudar a pessoa, mas não consegue por lhe faltar luz suficiente, o que lhe causa grande sofrimento.",501]],"native":[["O Awo deste signo tem que ter um obé de madeira da árvore do pó-de-mico junto de seu Elegbara.",500]],"reading":[],"care":[["Não deve ser tão inflexível, deve agir com mais calma e observar que algumas coisas não são tão graves como parecem à primeira vista.",501]],"stories":[],"curiosities":[]},"ire":{"p":230,"text":"a visão interior eleva a força interior."},"ibi":{"p":230,"text":"as ilusões e o autoengano enfraquecem o estado e a força interior."}},"12:11":{"alias":"OTURATRUPON","page":502,"phrase":"Babá Turukpé Awo ado Katobina, Awo Alaketu, ajá adifafun falofun, adifafun a loma abaso alagbá bomó aledodô ajakolo nilé igbín kalolô komikolo aro mabomo lodó ajankanlenile.","sections":{"representation":[["Este Odu é filho de Otura e Oturukpon.",502],["Trata-se do espírito de um indígena (caboclo) muito poderoso.",502],["Este é o caminho de Awo Falolu e da pérola negra.",503]],"native":[["A pessoa deste Odu tem que assentar Olokun e dar comida a Iyemanjá e a Elegbara.",503],["Os filhos deste signo não podem maltratar pessoas de Iyemanjá porque perdem a sorte.",503]],"reading":[["Assinala que a pessoa está enferma e passando por dificuldades.",502]],"care":[["Não deve criar filhos dos outros, pois depois de crescidos se transformarão em seus maiores inimigos.",502]],"stories":[["Foi neste caminho que Xangô fez com que seu oxê explodisse e se transformasse em chamas diante de todos e a partir de então passou a ser o mais temido entre seu povo.",502],["Neste caminho Elegbara tornou-se prisioneiro.",503]],"curiosities":[]},"ire":{"p":234,"text":"uma visão interior conduz ao crescimento."},"ibi":{"p":234,"text":"a ilusão e o autoengano conduzem ao fracasso. Em relação a temas de saúde, a pessoa não admite ou não aceita o seu estado verdadeiro."}},"12:13":{"alias":"OTURARETE","page":504,"phrase":"Oturarete, Oturatiju, tiju, lapé lobomini Yewá kurotio Exú Laroye, adifafun Exú Lario.","sections":{"representation":[["Este Odu é filho de Otura e Irete.",504]],"native":[["O Awo deste Odu tem que fazer ebó todas as vezes que participar de uma iniciação de Babalawo, Akofá ou Awofakan.",505],["O filho deste Odu tem um guia espiritual árabe.",505]],"reading":[["Assinala altos e baixos na vida da pessoa.",504],["Quando este Odu surge numa consulta o Awo tem que ter muito cuidado com o ebó, pois não é assegurado o resultado.",504]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":238,"text":"a visão e a fé na capacidade pessoal de criação favorecem a concretização consciente de ações necessárias."},"ibi":{"p":238,"text":"ilusões conduzem ao fanatismo, à teimosia e à rigidez."}},"12:14":{"alias":"OTURAXE","page":506,"phrase":"Oturaxe Baba Yengue idá kudá irú kukú isé kuté obere ketá oni Babalawo to iban Exú.","sections":{"representation":[["Este Odu é filho de Otura e Oxe.",506],["Este Odu assinala que foram cumpridas as determinações de Olofin.",506],["Este Odu é da Terra Fulani.",507]],"native":[["O eleké de Orunmilá do Awo deste Odu tem que levar um pedaço de osso da mão direita de um Egun.",506]],"reading":[],"care":[["Deve ter cuidado com hérnias abdominais.",507],["Deve evitar uma situação embaraçosa ocasionada por roubo ou aberração sexual.",507]],"stories":[],"curiosities":[]},"ire":{"p":239,"text":"a força de visão conduz à plenitude mental, emocional e espiritual."},"ibi":{"p":239,"text":"as ilusões e o autoengano conduzem a perdas, à ganância e ao egoísmo."}},"12:15":{"alias":"OTURAFUN","page":508,"phrase":"Otura Foká adafase adafata, ewe odafafá akpa Orun adifá kokan ori, preté korugbo awaté borí exesí orugbo exesí meje.","sections":{"representation":[["Este Odu é filho de Otura e Ofun.",508],["Este Odu determina que a pessoa tenha que fazer Ifá, receber kuanado, assentar Iyansã, Osain e Omolú.",508],["Este Odu assinala que a pessoa é violenta e pode até matar.",509]],"native":[["A coisa mais importante para as pessoas deste Odu é o sono.",509],["Quando um filho deste Odu estiver dormindo, para despertá-lo, tocam-se suavemente os pés para que não se torne violento.",509]],"reading":[["Avisa que um amigo ou parente vai ser preso.",508],["Quando este Odu surge em atefá, a primeira coisa que se faz é lavar as duas mãos de Ifá com omieró, depois, quando terminar o Itá, o padrinho, o Ojugbona, o Obá e o Awo têm que tomar borí com uma cotia.",508],["Quando surge este Odu num jogo de okpele, passa-se epô no okpele antes de continuar a consulta.",508]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":239,"text":"a criação se transforma em revelação. A força interior se transforma em uma manifestação externa."},"ibi":{"p":239,"text":"ilusões se desmoronam, destruindo utopias."}},"13:13":{"alias":"IRETE MEJI","page":510,"phrase":"Ejelembere akoré ajaré Eyelembere ladifá Ejelemere asarei fenixe ki Ifá Aje adifafun Orunmilá. Adifafun Oxun. Adifafun poroyé.","sections":{"representation":[["Este é o 14º Odu na ordem de chegada do sistema de Ifá.",510],["É um Odu masculino, filho de Elemere Wasá e Olomú.",510],["Este signo não deve jamais ser mencionado na companhia de Oxe Meji. \"Bokonon ma do o\" (Um adivinho jamais pronuncia este nome), o que significa dizer que os amolu gerados pelo encontro destes dois signos, não podem ser mencionados pelos seus verdadeiros nomes.",510]],"native":[["O Awo deste Odu tem que ser muito corajoso e necessita fazer ebó em si mesmo com muita constância, para livrar-se da influência negativa dos seus arajés.",510],["O Awo deste Odu oferece um galo a Elegbara dentro de um cesto.",511],["Os filhos deste Odu são pessoas cheias de graça e dulçura e, por isto, costumam ser vaidosas e suas palavras em relação aos outros costumam ser cheias de ironia e sátira.",511]],"reading":[["Quando surge numa consulta, oferece-se 16 akarás a Olofin e durante 16 dias faz-se rogações e dorme-se com um gorro verde e branco.",512],["Assinala que a pessoa que se consulta tem que fazer Santo ou tomar obrigação antes que decorra um ano.",512]],"care":[["Este signo não deve jamais ser mencionado na companhia de Oxe Meji. \"Bokonon ma do o\" (Um adivinho jamais pronuncia este nome), o que significa dizer que os amolu gerados pelo encontro destes dois signos, não podem ser mencionados pelos seus verdadeiros nomes.",510]],"stories":[["Neste caminho as mulheres andam em busca de carinho.",511],["Neste caminho Orunmilá avisa ao Awo a chegada de sua morte com dezesseis dias de antecedência.",511],["Foi neste caminho que Ogun ficou embrutecido e ensina porque os filhos de Ogun não interpretam Ifá.",512]],"curiosities":[["Este é o 14º Odu na ordem de chegada do sistema de Ifá.",510]]},"ire":{"p":242,"text":"determinação, orientação e ação."},"ibi":{"p":242,"text":"passividade, ações frenéticas, fanatismo e falta de objetivo."}},"13:0":{"alias":"IRETELOGBE","page":514,"phrase":"Irete Entebe more abiri kolo omolubo abata ati Kotopó omó lubo owará yaniyé omolubó meta laba pari ati meta laba merin lodafun Igbani, lodafun Laniyé.","sections":{"representation":[["Este Odu é filho de Irete e Ogbe.",514],["Este Odu traz doenças tais como: cirrose, problemas intestinais, hemorróidas, infecções da garganta, problemas com o sangue e com os ossos.",515],["Este Odu é caminho de Abíkú.",516]],"native":[["O Awo deste signo tem a virtude de conseguir burlar a justiça.",514],["As pessoas deste signo não devem prestar favores, pois ninguém lhes demonstrará gratidão.",514],["A pessoa deste signo, seja de que forma viva, sempre será vítima de inveja e de calúnias.",515]],"reading":[["Quando surge este Odu, sopra-se água por três vezes e depois otí, também por três vezes, na porta de casa.",514],["Indica que a pessoa pode ser presa, mesmo que seja por engano, mas, que no fim, tudo se resolverá de forma satisfatória.",515],["Assinala fenômenos marinhos, como ressacas que fazem com que o mar, aliado à Ikú, invada a terra e venha retomar o que um dia já foi seu.",515]],"care":[["A pessoa deve evitar alimentos muito condimentados, enlatados e embutidos, pois tem tendências a sofrer das hemorróidas.",514],["A pessoa não deve permitir que donzelas durmam em sua casa em trajes sumários, pois pode perder a cabeça e cometer uma violação.",514],["Não deve cortar ervas depois das 18 horas.",514]],"stories":[],"curiosities":[]},"ire":{"p":166,"text":"o momento é favorável e tem boas condições para a concretização das visões do interior. Esse Odu promete êxito na realização dessas visões."},"ibi":{"p":166,"text":"não há motivação e força suficientes para a concretização de visões interiores – as visões fracassarão. Esse Odu adverte que o acesso às visões do interior está bloqueado. Quando levados sem visão, todos os projetos se limitam ao material e não contribuem para o crescimento espiritual."}},"13:1":{"alias":"IRETEYEKU","page":517,"phrase":"Ireteyeku abadá bi abadá. Abadá bi abadá adifun wenwelé xé letixoma aiyá lorugbo.","sections":{"representation":[["Este Odu é filho de Irete e Oyeku.",517],["Este é um Odu de muita felicidade.",518]],"native":[["O verdadeiro ebó do Awo deste Odu; consiste em pegar seu Ifá e passá-lo em volta de sua própria cabeça.",517]],"reading":[["Assinala que, por inveja, os Orixás se uniram em guerra contra Orunmilá.",518],["Avisa que, na hora do perigo, os aliados da pessoa a deixarão sozinha.",518]],"care":[["A pessoa não deve continuar vivendo no local onde mora porque não é ali que encontrará a felicidade.",518],["Não deve usar presentes que lhe sejam dados, pois podem ter sidos trabalhados para a sua destruição.",518]],"stories":[["Foi aqui que, por não seguir as orientações de Orunmilá, um general teve seu exército derrotado e dispersado pelo inimigo, não podendo, jamais, voltar a reuni-lo.",518]],"curiosities":[]},"ire":{"p":175,"text":"a determinação e a ação encerram um ciclo."},"ibi":{"p":175,"text":"a rigidez, a estagnação e a falta de ação conduzem a fracassos e interrupções."}},"13:2":{"alias":"IRETEIWORI","page":519,"phrase":"Ireteyero Orunmilá lorubó to iban Exú. Telebo ibo kobo Babá Olorun. Babá adukpé to iban Exú.","sections":{"representation":[["Este Odu é filho de Irete e Iwori.",519],["Este Odu indica que a pessoa tem que fazer Ifá.",519],["É um Odu mensageiro, através do qual, Oxun traz suas mensagens exatamente ao meio-dia.",520]],"native":[["O Awo deste signo só deve iniciar sete pessoas em Ifá, porque depois da sétima começa a perder as suas forças.",519],["Os filhos deste signo têm que raspar seus corpos de dez em dez dias e podar as árvores de suas casas todos os anos.",520],["O Awo deste Odu tem que prestar juramento em Orun3.",520]],"reading":[["Assinala que existe gente trabalhando às escondidas para roubar uma mulher.",519],["Fala de enfarte do miocárdio, problemas na vesícula biliar e nos ossos.",520]],"care":[["A pessoa não deve maltratar a nenhuma menina que esteja debaixo de seu domínio ou de seu marido.",520]],"stories":[["Neste caminho existiam dezesseis pavões reais, mas de todos, só treze se salvaram, os outros sucumbiram nos caminhos da vida.",519],["Neste caminho os pais isolam suas filhas do mundo para que ninguém as vejam nem as namorem.",521]],"curiosities":[]},"ire":{"p":183,"text":"a determinação e a ação conduzem à transformação e a uma nova identidade."},"ibi":{"p":183,"text":"a obstinação ou a incapacidade de ação conduzem a conflitos internos."}},"13:3":{"alias":"IRETEDI","page":523,"phrase":"Irete Untedi amadá nimi adifafun awan lori tanxelú alare osi amudi Awo Borí Osá Ifá ni kaferefun Olofin, Iyemanjá, Obatalá, Orunmilá ati bogbo kaleno Oxá.","sections":{"representation":[["Este Odu é filho de Irete e Odi.",523],["É um Odu de aborrecimentos.",523],["Este Odu fala com mais ênfase das pessoas iniciadas em Ifá a menos de quinze anos.",523]],"native":[["As pessoas deste signo devem usar o idé de Elegbara.",523]],"reading":[["Assinala problemas cardíacos.",523],["Assinala dívidas com Omolú por causa de uma criança.",524]],"care":[["Não deve confiar em ninguém.",524],["Deve ter cuidado para não adquirir algum tipo de doença sexual.",524]],"stories":[["Foi neste caminho que Elegbara trocou tudo por um saco cheio de chifres.",523],["Neste caminho oferece-se ganso a Ogun e pato à Iyemanjá.",523]],"curiosities":[]},"ire":{"p":189,"text":"a determinação e a clareza favorecem a renovação."},"ibi":{"p":189,"text":"a indecisão, ou a teimosia, é a causa dos apegos e das renovações malsucedidas."}},"13:4":{"alias":"IRETEROSUN","page":525,"phrase":"Ireteloso adifafun Oba Ikú, Inle Arere, Ogun Arebe, Obaluaye Oba Egun lese, Iguí Oba Telé omó Egun, lodafun Orunmilá. Kaferefun Egungun.","sections":{"representation":[["Este Odu é filho de Irete e de Irosun.",525]],"native":[["O Awo deste signo tem que colocar um barquinho de iguí yáita (Bassia albeenses) dentro da sua segunda mão de Ifá.",525]],"reading":[["Assinala problemas nas pernas que podem ser sanados com o sacrifício de uma franga a Elegbara.",525]],"care":[],"stories":[["Foi neste caminho que os Awo prepararam uma armadilha para a babosa e ela, invocando os quatro ventos, logrou salvar-se.",525]],"curiosities":[]},"ire":{"p":196,"text":"a determinação e a ação favorecem a realização dos potenciais e harmonizam as relações familiares."},"ibi":{"p":196,"text":"as hesitações alimentam os conflitos familiares pendentes, impedindo o uso dos potenciais. Há tendência para um comporta-mento determinista."}},"13:5":{"alias":"IRETEWORIN","page":527,"phrase":"Iretewónrin Odubiri fobó adifafun Orunmilá Obarabaniregun wanká win win Osain yoro yoro.","sections":{"representation":[["Este Odu é filho de Irete e Owónrin.",527],["Este Odu traz calvície para seus filhos.",527],["Este Odu proíbe que se possuam pássaros presos em gaiolas.",528]],"native":[],"reading":[["Fala de rios transbordantes e de redemoinhos.",527],["Assinala viagens a lugares distantes.",527],["Fala de uma mata onde vive um Egun que reconhece a pessoa pelo seu assobio.",527]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":203,"text":"a determinação e a força de vontade conduzem durante um processo de revolução interior e reorientação."},"ibi":{"p":203,"text":"a paralisia, a passividade e a submissão inviabilizam uma revolução interior, ou conduzem ao caos interior."}},"13:6":{"alias":"IRETEBARA","page":529,"phrase":"Irete Obá bijé lodafun Orunmilá, Iyalode ati Obinin. Akukó, owunkó lebó, intorí Ikú, intorí arun, afie lebó. Maferefun Xangô. Kaferefun Oiyá.","sections":{"representation":[["Este Odu é filho de Irete e Obara.",529]],"native":[],"reading":[["Assinala a presença de sífilis.",529]],"care":[["A pessoa não deve guardar dinheiro nos bolsos.",529],["Se for convidada para uma festa ou um almoço, deve evitar que lhe toquem no rosto, pois é desta forma que será enfeitiçada.",529],["Deve ter cuidado com a sífilis ou com infecção numa das pernas.",530]],"stories":[],"curiosities":[]}},"13:7":{"alias":"IRETEKANRAN","page":531,"phrase":"Irete Kana berinlé bagogun bagbisan irun bogbo laodo laure akperé lorugbó.","sections":{"representation":[["Este Odu é filho de Irete e Okanran.",531],["Este Odu fala de problemas matrimoniais e separação dos cônjuges.",531]],"native":[["O Awo deste Odu deve cuidar da inveja de seus irmãos de Ifá que tudo farão para prejudicá-lo.",531],["Os filhos deste Odu gostam de provocar ciúmes.",531]],"reading":[["Assinala perda de memória.",531],["Quando este Odu surge num atefá, o padrinho tem que oferecer uma cabra a seu Ifá para que a negatividade trazida não chegue a ele.",531],["Assinala família numerosa.",531]],"care":[["A pessoa deve evitar mexer no que não lhe pertence para não passar por grandes decepções e vergonha.",532]],"stories":[["Foi neste caminho que tentaram levar a mulher de Iretekanran para o mal caminho.",531],["Foi aqui que nasceram as traições amorosas.",531]],"curiosities":[]},"ire":{"p":214,"text":"agir com determinação e força de vontade abre o caminho para novas relações e projetos."},"ibi":{"p":214,"text":"a subordinação e a passividade conduzem ao isolamento. Novas oportunidades não podem ser aproveitadas devido à falta de autoconfiança e de energia."}},"13:8":{"alias":"IRETEGUNDÁ","page":533,"phrase":"Iretegundá Kutan Obá Aiye. Orixá bi Kolé Orun ofé leí toxo Orixaye Osogbe Ile Axukpá, Awo Umbo bogbo Orixá Isalaye kolé, Aiye Obá, bogbo tenujé elebó erindilogun.","sections":{"representation":[["Este Odu é filho de Irete e de Ogundá.",533],["Este Odu recebe o nome de Alewajade, o exorcizador das folhas.",533]],"native":[["As pessoas deste signo não devem encarar no rosto de nenhum defunto para não serem perseguidas pelo mesmo.",534]],"reading":[["Assinala problemas dentro de casa.",533],["Fala de uma traição de parte de uma pessoa a quem se acolheu dentro de casa.",534]],"care":[],"stories":[["Neste caminho falam Obatalá e Oxun.",534]],"curiosities":[]},"ire":{"p":220,"text":"a determinação e um direcionamento claro são essenciais para a concretização exitosa de objetivos e interesses."},"ibi":{"p":220,"text":"a falta de empenhamento e de determinação conduz à perda de disputas."}},"13:9":{"alias":"IRETESÁ","page":536,"phrase":"Iretetomusá kere Awo mowaye omó Xangô. Omó Oiyá Ayeni Ifá oni Babalawo omó Obajonko banjoko. Ifá Bajoko, Orixá Bajoko, yenjoko jeni Ifá iyereni kaferefun Xangô, maferefun Orunmilá.","sections":{"representation":[["Este Odu é filho de Irete e Osá.",536],["Este é um Odu de infelicidade.",536]],"native":[["O osogbo deste Odu é a vaidade, por isto, o Awo deste signo não deve considerar-se melhor que ninguém.",536]],"reading":[["Assinala deficiência hormonal num dos cônjuges.",536],["Assinala doenças cardíacas.",538]],"care":[["O osogbo deste Odu é a vaidade, por isto, o Awo deste signo não deve considerar-se melhor que ninguém.",536],["Não deve brigar para não ser abandonada pela sorte.",538],["Não deve sentar-se em cadeiras quebradas.",538]],"stories":[["Foi neste caminho que Olofin pediu a Xangô que fizesse ebó para salvar o mundo, tendo Oduduwa como testemunha.",537],["Neste caminho Olofin tomou o oponifá de Xangô porque este só vivia metido em festas e orgias.",538]],"curiosities":[]},"ire":{"p":225,"text":"agir de forma consequente e com determinação é a bússola que conduz durante um processo de purificação necessário."},"ibi":{"p":225,"text":"a teimosia e a rigidez provocam catástrofes e impedem que as mudanças sejam levadas a cabo de uma forma flexível."}},"13:10":{"alias":"IRETEKÁ","page":539,"phrase":"Ireteká omá ni ateká adifafun Inure, adifafun Ateká lebó, eiyelé, akukó lebó.","sections":{"representation":[["Este Odu é filho de Irete e Iká.",539]],"native":[],"reading":[["Assinala proteção de Oxóssi, Obatalá e Xangô.",539],["Assinala que a pessoa vive uma luta constante pela vida e que não tem descanso nem de dia nem de noite.",539],["Assinala graves problemas familiares que só serão resolvidos se a pessoa, abandonando tudo, for viver longe de seus parentes.",540]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":230,"text":"ao agir com determinação e com um objetivo claro, a pessoa fortalece o seu interior."},"ibi":{"p":230,"text":"a hesitação e a falta de objetivo debilitam a força interior e podem levar a pessoa ao colapso."}},"13:11":{"alias":"IRETEBATRUKPON","page":541,"phrase":"Iretebatrukpon Awo Guele, Awo Obadé aditá oun Oxá oguiriná tiô lo guiyá, tinlo bini omá bini omá guegueré ejélé lebó, owo la mefá tontiefá, eiyelé, akukó lebó.","sections":{"representation":[["Este Odu é filho de Irete e Oturukpon.",541]],"native":[["Os filhos deste Odu têm que assentar Oduduwa e Osain.",541]],"reading":[["Assinala que para nascer, o corpo humano recebe um espírito que Ikú leva na hora em que bem entender.",541],["Assinala agressão física da mulher contra o marido.",541],["Assinala impotência no homem.",541]],"care":[["Para prosperar a pessoa não deve comer inhame.",541]],"stories":[["Neste caminho Osain come, de quando em vez, três pombos junto com Egun.",541]],"curiosities":[]},"ire":{"p":235,"text":"a ação e um direcionamento conduzem ao crescimento e à saúde."},"ibi":{"p":235,"text":"a letargia, o exagero ou a teimosia (por falta de orientação ou por má orientação) conduz ao fracasso, podendo eventualmente afetar a saúde."}},"13:12":{"alias":"IRETURÁ","page":543,"phrase":"Iretesuká apekankolá adifafun Akuperu oguere, odé obinin, kpaye obinin awá nifá Obarabaniregun mojeré ejebé. Ifá Orunmilá lorugbo.","sections":{"representation":[["Este Odu é filho de Irete e Otura.",543],["Este Odu é da Terra Madadá onde as pessoas não compreendiam o que falavam.",543]],"native":[["As pessoas deste signo sofrem muito por causa dos próprios filhos.",543]],"reading":[["Assinala problemas nos Órgãos reprodutores da mulher que podem se manifestar em forma de quistos ou hemorragias incontroláveis.",544]],"care":[],"stories":[["Neste caminho o Axé de Osain ultrapassa Orunmilá.",543],["Neste caminho a criada passa a ser senhora e dona de tudo.",544]],"curiosities":[]},"ire":{"p":238,"text":"agir com determinação, seguindo uma meta, é fundamental para o processo criativo pessoal."},"ibi":{"p":238,"text":"a indecisão e a passividade, ou a teimosia e o fanatismo, conduzem à ilusão e à utopia."}},"13:14":{"alias":"IRETEUNFÁ","page":545,"phrase":"Ireteunfá akoko oxe aro biriwo dogodó aiyá koxeká bi ajé adifafun oun Babalawo xelé eré lebó. Kaferefun Exú ati Iyalode.","sections":{"representation":[["Este Odu é filho de Irete com o Odu Oxe.",545],["Este Odu espalha a morte sobre a terra, mata as mulheres grávidas, não crê em nada e faz o mal por simples prazer.",545],["Este é o caminho do coche fúnebre manobrado por Alujá e que transporta os cadáveres para o cemitério.",545]],"native":[],"reading":[["Quando este Odu chegou à Terra, a primeira coisa que fez foi abrir as portas para a morte dizendo: \"Ago Ikú abilé\".",545],["Assinala separação familiar e que alguma coisa foi perdida.",546],["Fala de tuberculose, problemas do peito, da garganta e das pernas.",546]],"care":[["Seu verdadeiro nome não deve ser pronunciado porque traz uma grande carga de negatividade cada vez que é dito.",545]],"stories":[],"curiosities":[]},"ire":{"p":242,"text":"a determinação e a orientação conduzem à plenitude, ao bem-estar e à satisfação."},"ibi":{"p":242,"text":"a obstinação, a teimosia e ações frenéticas conduzem à ganância, ao egoísmo, a perdas e ao vazio."}},"13:15":{"alias":"IRETEFUN","page":547,"phrase":"Iretefile maferefun Xangô, Orunmilá malu iyamodé iyemureo. Xangô kabiesile, ori onle okunin bibelona, iyamode obinin lodê agogô meji la Ifá axekun otá. Kole ni adio Ojale Orunmilá Unxi xé ebó. Malu Xangô adobale.","sections":{"representation":[["Este Odu é filho de Irete e de Ofun.",547]],"native":[["As pessoas deste signo devem respeitar os pombos, não podem matá-los nem comer sua carne.",547],["Os filhos deste Odu têm como missão, tocar tambor.",547],["As pessoas deste Odu, quando quiserem saber quem são seus inimigos, devem pegar um prato branco e acender seis velas dentro dele.",548]],"reading":[],"care":[["Não deve viajar para fora de seu país.",547],["Ouve ruídos durante a noite, mas não deve assustar-se porque são produzidos por Eguns que a protegem.",548],["Não deve molhar-se na chuva.",548]],"stories":[],"curiosities":[]},"ire":{"p":243,"text":"a determinação e a clareza conduzem à revelação."},"ibi":{"p":243,"text":"a teimosia e o fanatismo conduzem à quebra de utopias."}},"14:14":{"alias":"OXE MEJI","page":549,"phrase":"Oxe Aladaxe Onibarabaniregun, Ifá Moloku Tiane, xenxé Moloku adifafun Oxun.","sections":{"representation":[["Este é um Odu masculino, filho de Atié e Athie.",549],["Representa a metade do mundo correspondente ao oriente.",549],["Este Odu está em guerra constante com seu irmão Irete Meji, por este motivo, sempre que surgem juntos, seja qual for a posição que ocupem na figura formada, o nome do Omo Odu resultante deste encontro não deve ser pronunciado dado a enorme carga de negatividade da qual é portador.",550]],"native":[["Ao contrário do que se afirma, os filhos deste Odu não tem cargo sacerdotal dentro do culto dos Orixás.",550],["Os filhos deste Odu não são compreendidos pelas demais pessoas, só eles sabem aquilo que realmente querem.",550],["As pessoas deste signo são repudiadas pela própria família que não lhe têm a mínima consideração nem o menor reconhecimento Podem ser traídas pelos melhores amigos.",551]],"reading":[["Prenuncia perdas de todos os tipos e em todos os setores da vida.",550],["Assinala feitiçaria, amarrações, briga em família, e separação de irmãos.",551],["Assinala estado de loucura transitório.",551]],"care":[["Este Odu está em guerra constante com seu irmão Irete Meji, por este motivo, sempre que surgem juntos, seja qual for a posição que ocupem na figura formada, o nome do Omo Odu resultante deste encontro não deve ser pronunciado dado a enorme carga de negatividade da qual é portador.",550]],"stories":[["Foi neste caminho que se jogou pela primeira vez o okpele sobre a esteira.",550],["Foi neste Odu que se jogou búzios pela primeira vez.",551]],"curiosities":[]},"ire":{"p":246,"text":"plenitude, condução interior e conexão espiritual."},"ibi":{"p":246,"text":"vazio, desorientação, ganância e egoísmo."}},"14:0":{"alias":"OXENILOGBE","page":553,"phrase":"Oxenilogbe otolaiye adifafun Oluwo Bueré. Ikú ko pa mi, ko pa mi, arun ko pa mi, ko pa mi, ejó ko pa mi, ko pa mi, Ogu ko pa mi, ko pa mi.","sections":{"representation":[["Este Odu é filho de Oxe e Ogbe.",553],["É um Odu de reis e governantes, neste caminho Oxun governa Xangô.",553],["Este Odu assinala que a pessoa pode perder a visão, para que isto não aconteça, tem que fazer Oxun que é o seu Orixá.",554]],"native":[["Os filhos deste Odu são traiçoeiros e maliciosos, por este motivo, não se confia a eles os segredos de Ifá.",553],["Aos Awo deste signo ensina-se pouco ou não se ensina nada, pois nunca acreditarão em Orunmilá e tornar-se-ão inimigos de seus mestres.",553],["Quando a mulher do Awo deste signo estiver grávida, tem que fazer três ebó.",553]],"reading":[["Assinala guerra com mulher feiticeira, bruxa ou macumbeira.",553],["Quando este Odu sair na consulta de um cliente, não se deve ensinar nada a ele sobre a religião, pois certamente ele irá cometer uma traição contra o adivinho.",554],["Assinala que quando a lua entra em quarto minguante, a mulher entra no sío, seu desejo sexual aumenta e fica necessitada de homem.",554]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":166,"text":"a conexão espiritual abre o caminho. Esse Odu ressalta a importância de confiar na condução espiritual para a concretização de projetos."},"ibi":{"p":166,"text":"a falta de confiança na condução espiritual conduz ao fracasso de projetos. Esse Odu adverte que os planos não estão em sintonia com o destino, pois estão sendo conduzidos pelo ego e não pelo mundo espiritual."}},"14:1":{"alias":"OXEYEKU","page":555,"phrase":"Oxeyeku boru, boxe. Yeku ibaí boro ona Obaiye bi Ifá. Oxeyeku bawaye be Ifá jonjo odara moloni, mololun Inle. Elegbara Oxeyeku Bawaiye be Ifá.","sections":{"representation":[["Este Odu é filho de Oxe e Oyeku.",555],["Este Odu é caminho de Iyemanjá e Aganjú.",555],["Este Odu fala de pessoa irresponsável, vadia e que não gosta de trabalhar.",556]],"native":[],"reading":[],"care":[["A pessoa não deve andar em grupos, pois somente se prejudicará com isto.",556],["A mulher deve ter cuidado especial com os seios.",556]],"stories":[["Foi aqui que os Bokonon3, que não tinham Orixá, tiveram que assentá-los para que os acompanhassem. tipo de ebó.",555]],"curiosities":[]},"ire":{"p":175,"text":"a prosperidade, a abundância e a conexão viabilizam a conclusão de um ciclo."},"ibi":{"p":175,"text":"o egoísmo, o vazio e a falta de conexão conduzem a perdas e interrupções de projetos."}},"14:2":{"alias":"OXEIWORI","page":557,"phrase":"Oxe Paure Yeyere Yewará omi Abanxelú Ofito. Mojá lodafun Oxe Paure.","sections":{"representation":[["Este Odu é filho de Oxe e Iwori.",557],["Este é um Odu exclusivamente de Egun.",558]],"native":[["As pessoas deste signo não dão assistência nem atenção aos seus pais e só se lembram deles quando precisam de alguma coisa.",557],["Os filhos deste signo devem usar um colar de pérolas.",557],["O Awo deste Odu tem que ter marfim e prata dentro de seu Ifá.",558]],"reading":[["Assinala problemas de vistas, sangue, artrites, bursites, pernas e pés.",557],["Assinalam bruxarias, atitudes violentas, dívidas com Oxun ou com outro Orixá e destruição do lar.",557],["Quando este Odu surge em atefá, o padrinho e o Ojugbona têm que oferecer um ejá oro4 aos seus respectivos Ifás; e o afilhado tem que fazer o mesmo assim que receber Kuanado.",558]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":183,"text":"a prosperidade ou a conexão espiritual favorece a transformação e o redirecionamento."},"ibi":{"p":183,"text":"a ganância conduz a conflitos."}},"14:3":{"alias":"OXEDI","page":559,"phrase":"Oxedi oko mode adifafun Orunmilá Oni Barabaniregun Ifá Nire. Ifá kaferefun Iyalode ati Obini.","sections":{"representation":[["Este Odu é filho de Oxe e Odi.",559]],"native":[],"reading":[["Assinala enfermidades no ventre que podem ocasionar intervenção cirúrgica.",560]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":189,"text":"o bem-estar conduz ao renascimento."},"ibi":{"p":189,"text":"a ganância, as perdas e a falta de conexão espiritual conduzem à estagnação."}},"14:4":{"alias":"OXEROSUN","page":561,"phrase":"Oxeleso olalu firi adifafun bá ale ile korugbo ire obo eiyelé lebó. Kaferefun Exú ati Iyalode.","sections":{"representation":[["Este Odu é filho de Oxe e de Irosun.",561]],"native":[["O Ôsun do Awo deste Odu come um galo junto com Egun.",561]],"reading":[["Fala de heranças e afirma que tanto se herda o bem como o mal.",561]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":197,"text":"a prosperidade, a generosidade, a plenitude e a conexão favorecem a realização dos potenciais e harmonizam as relações familiares."},"ibi":{"p":197,"text":"a inveja, o vazio e a ganância provocam resistências familiares e impedem que o destino se cumpra."}},"14:5":{"alias":"OXEWONRIN","page":563,"phrase":"Oxeroroniwo Boro Owónrin kokoroxe Awé Owónrin kokoró biajé eiyelé lebó. Oxe Moweyo Owónrin Akakaleiyé Obá Jobi Inú enu omó lalá Awo Okutá, Awo Leri Okutá.","sections":{"representation":[["Este Odu é filho de Oxe e de Owónrin.",563]],"native":[["As pessoas deste Odu devem ter sempre em suas casas, uma jaula com uma cotia dentro.",563],["Devem lavar suas casas com folhas de afoman O Awo deste Odu abre guerra com seu padrinho e depois que tem afilhados, estes se afastam desgostosos.",563],["As pessoas deste signo, sejam homens ou mulheres, preferem cônjuges muito mais jovens que elas e, para não perdê-los, fazem todas as suas vontades.",564]],"reading":[["Fala de três pessoas que se separam.",563]],"care":[],"stories":[["Neste caminho coloca-se Elegbara comendo junto com Ogun.",563],["Foi por este caminho que Osain chegou à terra.",563]],"curiosities":[]},"ire":{"p":203,"text":"a plenitude e a conexão favorecem a revolução interior e a confiança no caos."},"ibi":{"p":203,"text":"a ganância e o vazio conduzem ao caos interior fora de controle."}},"14:6":{"alias":"OXEBARA","page":565,"phrase":"Oxebara Awo Shexeré adifafun Lobá Fiferekú tolumá ku oguede Alafia.","sections":{"representation":[["Este Odu é filho de Oxe e Obara.",565],["Este Odu fala de um cofre cheio de moedas.",565],["Este Odu manda dar comida a Egun, periodicamente, na porta de casa.",566]],"native":[],"reading":[["Fala de um Egun que morreu de fome e que fica parado na porta da casa da pessoa esperando que lhe dêem comida.",565],["Assinala doenças como: Úlceras estomacais, problemas da vesícula, úlceras de duodeno, doenças cardíacas e das veias.",566]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":210,"text":"plenitude e conexão fortalecem a pessoa, preparando-a para os processos de transformação interior."},"ibi":{"p":210,"text":"a ganância, o vazio e a falta de orientação conduzem ao egoísmo e à falta de autoestima."}},"14:7":{"alias":"OXEKANA","page":567,"phrase":"Oxekana, Oxe Ipiliki afijé akolonan adifafun Sokun batinxé maiyexá ejá oro lebó.","sections":{"representation":[["Este Odu é filho de Oxe e Okanran.",567],["Este Odu fala de despreocupação com problemas familiares.",568]],"native":[],"reading":[["Fala de indiferença e insensibilidade diante dos sofrimentos alheios.",568]],"care":[["Não deve subestimar ninguém, pois aquele em que menos pensa é quem irá solucionar um grande problema.",567]],"stories":[["Neste caminho os resultados dos trabalhos só surgem depois de sete dias.",567]],"curiosities":[]},"ire":{"p":215,"text":"o bem-estar abre novas oportunidades."},"ibi":{"p":215,"text":"a ganância conduz ao isolamento."}},"14:8":{"alias":"OXEGUNDÁ","page":569,"phrase":"Oxe Omolu Oxewele Biawo wele. Oxe balaya Biawo akukó bodawa xé ajá baxere sinu oroinan oguese omi akoko wini okoko isuguese kileman Oxe Omolu, Oxe Omolu agadá mamelorun Este Odu é filho de Oxe e Ogundá.","sections":{"representation":[],"native":[],"reading":[],"care":[["Se for homem não deve faltar com o respeito nem a consideração com sua mulher para não ser abandonado pela sorte.",570]],"stories":[],"curiosities":[]},"ire":{"p":220,"text":"com plenitude e uma forte condução espiritual interior é possível realizar os interesses pessoais."},"ibi":{"p":220,"text":"o vazio e a ganância provocam guerras sem sentido ou conduzem à derrota nos conflitos necessários."}},"14:9":{"alias":"OXESÁ","page":571,"phrase":"Oxesá Awo obinin opú adifafun Ako. Akukó lebó. Akofá atitan erita merin elebó.","sections":{"representation":[["Este Odu é filho de Oxe com Osá.",571]],"native":[],"reading":[["Assinala artrite e problemas nas juntas ósseas.",571],["Assinala fogo dentro de casa que, para ser evitado, faz-se ebó com três ofás e três molhos de palha seca que são queimados sobre os ofás e têm as cinzas sopradas para fora de casa.",571]],"care":[],"stories":[["Foi neste caminho que o periquito foi visitar Orunmilá e no caminho seus inimigos lhe sopraram pós a base de osun para lhe fazerem mal.",571]],"curiosities":[]},"ire":{"p":226,"text":"a abundância e a plenitude, como também a boa condução interior, orientam durante um processo de purificação exterior."},"ibi":{"p":226,"text":"a ganância, o vazio e a falta de orientação conduzem à perda total, causando danos e mudanças drásticas."}},"14:10":{"alias":"OXEKÁ","page":573,"phrase":"Oxekaraká adifafun erú. Orunmilá umbatilope esé ibú losá omó erú. Oxun koyode oma unfo Oluwo, Ossain, Inle Akarabanijé oro kodadé.","sections":{"representation":[["Este Odu é filho de Oxe e Iká.",573]],"native":[],"reading":[["Quando surge este Odu, despacha-se a porta com água fria.",573],["Assinala asma e possibilidade de morte por afogamento ou sufocação.",573],["Assinala fraturas de braços ou pernas e morte súbita ocasionada por uma surpresa.",573]],"care":[["Quando sai este Odu numa consulta, a pessoa para quem sair, durante sete dias, deve evitar andar em qualquer tipo de veículo motorizado ou montar a cavalo para não sofrer um acidente.",574],["Uma mudança de trabalho não deve ser motivo de preocupações, pois só trará benefícios.",574]],"stories":[["Neste caminho Orunmilá praticava magia negra.",573]],"curiosities":[]},"ire":{"p":230,"text":"a plenitude e a abundância estimulam a força interior."},"ibi":{"p":230,"text":"a ganância, o egoísmo e a cobiça debilitam a força interior."}},"14:11":{"alias":"OXETURUKPON","page":575,"phrase":"Oxetrupon ikabagun mayá lalaya oun oyagunle ilowó tulé adifafun piti aretinlo laya tinxé arema owunko lebó. Ologun bante eiyelé, akukó lebó.","sections":{"representation":[["Este Odu é filho de Oxe e Oturukpon.",575],["Este Odu é caminho de Xangô e de Obatalá.",575],["Este é o ebó para problemas de dinheiro.",575]],"native":[["O padrinho da pessoa deste signo tem que tratá-la com muita atenção e sem reservas, pois, se esta pessoa resolver ir-se embora, arrastará consigo todos os seus irmãos, deixando o padrinho sem ninguém.",575]],"reading":[["Fala de um Egun de alguém que, em vida, teve uma discussão com a pessoa e que estava com a razão.",576]],"care":[["Por este motivo não deve alegrar-se com o mal de quem quer que seja, para não ser acusado de fazer o mal através de pragas e maldições.",576],["Não deve preocupar-se, pois viverá muitos e muitos anos.",576]],"stories":[["Neste caminho nasceu Babá Axó que ensinou os homens a usarem roupas e a arte da carpintaria.",576]],"curiosities":[]},"ire":{"p":235,"text":"a plenitude espiritual, emocional e material conduz ao crescimento interior e exterior."},"ibi":{"p":235,"text":"a ganância, o egoísmo e a falta de recursos conduzem a fracassos."}},"14:12":{"alias":"OXETURA","page":578,"phrase":"Oxetura lodafun Unbatinló leajá benifó tete no nixó inbá oiyni afere wewé. Aiyagbá didé afere wewé. Oxetura omi unsoro atie Axá Olodumare ebó omó Ire Odara.","sections":{"representation":[["Este Odu surgiu do encontro de Oxe com Otura.",578],["Este Odu é o resultado da interação deste poder com o poder genitor masculino, do qual Obatalá é o detentor, aqui representado pelo Axé contido nos dezesseis Agba Odu.",578],["É um Odu, como os outros 256 do elenco de Ifá, e não um Exú, como afirmam pessoas que nada sabem dos mistérios de Ifá.",578]],"native":[["As Pessoas deste Odu são colocadas em perigo de vida pela própria mãe ou esposa.",578]],"reading":[["Assinala enfermidades na boca e na garganta, aftas, faringites, laringites, etc.",579]],"care":[["A pessoa é achacada de roubos, não deve ter contato com ladrões e lava a culpa de coisas que não fez.",579],["Não deve construir castelos no ar, alimentar ilusões vãs, para não sofrer desilusões.",579]],"stories":[],"curiosities":[]},"ire":{"p":239,"text":"a plenitude é um terreno fértil para visões."},"ibi":{"p":239,"text":"o vazio conduz a ilusões e a utopias."}},"14:13":{"alias":"OXEBILE","page":581,"phrase":"Oxebili boroboro mofá Irete mokure.","sections":{"representation":[["Este Odu é filho de Oxe e Irete.",581],["É um Odu de heranças, por isto fala de doenças hereditárias.",582]],"native":[["As pessoas deste Odu morrem de afogamento ou de asfixia.",581],["O Awo deste signo tem que trabalhar em sua própria casa.",583],["O filho deste Odu não pode comer carne de animais pretos.",583]],"reading":[["Assinala guerra entre mulheres.",582],["Assinala a existência de uma propriedade que outros estão desfrutando.",582],["Fala de enganos de documentos legais, de falsos testemunhos, usurpação de direitos, propriedades ou cargos.",582]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":242,"text":"a plenitude estimula a determinação e a clareza da orientação e dos objetivos."},"ibi":{"p":242,"text":"o vazio, a ganância e o egoísmo conduzem à obstinação, ao fanatismo e à teimosia."}},"14:15":{"alias":"OXEFUN","page":584,"phrase":"Oxefun tefun Shefun. Shefun Babá Arerú. Orunmilá ni Aiyaxé ria ria Awo igbín okoto kilu osalakole Iká koye adafun loede ikokoyeye wofun Awo Onikako pewo omi kako orugbo iguí ni axó, erí, oni pejú tonpokolaro.","sections":{"representation":[["Este Odu é filho de Oxe e de Ofun.",584],["É um Odu impuro e perigoso.",584]],"native":[["As pessoas deste Odu quando lavam suas roupas não as devem torcer.",584]],"reading":[["Assinala dores estomacais ocasionadas por má digestão.",584],["Quando surge este Odu na consulta de um cliente não iniciado, esta pessoa não pode fazer Santo, mas deve ser iniciada em Ifá o mais depressa possível.",584]],"care":[],"stories":[["Neste caminho se vende aos inimigos.",584],["Neste caminho, quando se ganha dinheiro, tem-se que perguntar a Orunmilá de que forma se deve gastá-lo.",584]],"curiosities":[]},"ire":{"p":246,"text":"a plenitude e a condução espiritual conduzem à revelação do verdadeiro destino, dos verdadeiros valores, dos verdadeiros sentidos e objetivos."},"ibi":{"p":246,"text":"o vazio, a desorientação, a ganância e o egoísmo conduzem à quebra de utopias e ao fracasso dos objetivos da vida."}},"15:15":{"alias":"OFUN MEJI","page":586,"phrase":"","sections":{"representation":[["Este Odu rege homens e mulheres indiscriminadamente, é um signo ligada às Kenesi e as aves ligadas à feitiçaria são provenientes dele.",589],["Este Odu é tão perigoso que a maioria dos adivinhos omitem seu nome diante de profanos preferindo dizer \"Hekpa Baba\" (Baba significa papai e hekpa é uma exclamação que exprime pavor).",589]],"native":[["As pessoas deste signo devem vestir-se exclusivamente de branco, não podem andar sujas nem freqüentar lugares sujos.",589],["As pessoas deste Odu, por ódio ou revolta, lançam feitiços em sua própria família.",590],["Os filhos deste signo têm o poder de falar diretamente com a morte e exercerem controle sobre ela.",590]],"reading":[["Assinala o poder de Olofin sobre a terra.",589],["Assinalam fenômenos, bruxarias, maldições, aquisições, riqueza, força na palavra, morte ou vida longa.",590],["Quando este Odu surge em opolé e vem seguido do Odu do Awo, não se pode fazer nada pela pessoa que se consulta, muito menos fazer-lhe Ifá, pois Orunmilá está avisando que esta pessoa será a destruição do Awo.",590]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":249,"text":"revelação e realização."},"ibi":{"p":249,"text":"quebra de utopias e revelação de ilusões."}},"15:0":{"alias":"OFUNLOGBE","page":593,"phrase":"Ofunlogbe aujetre yiero ajeri gui ofá periguikí Obá. Oxun lodafun Ofun Odafo Obá Nubá Ogbe donlará Ofun, Ekodidé metá elebó. Ebejó owo elebó.","sections":{"representation":[["Este Odu é filho de Ofun e de Ogbe.",593]],"native":[["Os filhos deste Odu têm problemas estomacais e não podem comer cabra.",593],["As pessoas deste Odu não têm caminho em Ifá, não podem ser Babalawo, pois sua missão está dentro do culto de Orixás.",593]],"reading":[],"care":[],"stories":[["Neste caminho expulsaram Azawani do reino de Ulkuman, na terra Lukumi (Nagô).",593],["Neste caminho Obatalá leva oito otás em seu igbá e fica sempre mais alto que qualquer Orixá.",593],["Neste caminho coloca-se em Orunmilá um gancho de aço cromado.",594]],"curiosities":[]},"ire":{"p":167,"text":"uma vida nova é revelada. Esse Odu conecta o fim ao início. Uma vida nova surge a partir da revelação."},"ibi":{"p":167,"text":"não é possível começar um novo ciclo da vida sem concluir um ciclo anterior. Esse Odu adverte sobre a necessidade de dar sentido e conclusão à vida e a cada projeto, pois sem isso o desenvolvimento não é possível."}},"15:1":{"alias":"OFUNYEKU","page":595,"phrase":"Ofun Yemilo kunukú aberikulú ninxawo Inlé Olofin akalá mabo abigui Olorun ninxewo.","sections":{"representation":[["Este Odu é filho de Ofun e Oyeku.",595]],"native":[["Os filhos deste Odu devem se especializar no tratamento de Egungun.",595],["Os filhos deste Odu, por excesso sexual, podem ficar impotentes.",596]],"reading":[],"care":[],"stories":[["Neste caminho o Awo tem que fazer ebó em si mesmo antes de fazer para o cliente ou afilhado.",595],["Neste caminho, na cerimônia funeral de Akambí Obá, e segundo sua vontade, Ikú sentou-se à mesa todo vestido de negro, e na outra cabeceira sentou-se Olofin, vestido de branco e com sua resplandecente coroa sobre a cabeça, tendo Exú Axikpelu como guardião da porta.",595],["Neste caminho, as mulheres gostam de praticar sexo oral e anal.",596]],"curiosities":[]},"ire":{"p":175,"text":"o milagre, o reconhecimento e a revelação encerram uma fase."},"ibi":{"p":175,"text":"o fracasso e o erro encerram um ciclo, trazendo perdas. IWORI Iwori representa a transformação e a formação de identidade no ciclo interno da vida."}},"15:2":{"alias":"OFUNIWORI","page":597,"phrase":"","sections":{"representation":[["Este Odu é filho de Ofun e Iwori.",597],["Este Odu é acompanhado por quatro espíritos que são: Lebayemi, Omubi Lowo, Agbon Egun Kafo e Afinju Elegba.",597],["Este Odu recebeu o título de Ofun Gando por ter salvo o povo de Gando e coroado rei desta terra.",597]],"native":[["Os filhos deste Odu se possuírem mais de cinco dedos numa das mãos, são filhos de Oduduwa.",597],["Os filhos deste Odu não podem usar roupas de cores combinadas, é melhor que se vistam de branco.",598]],"reading":[["Assinala a perda das faculdades mentais por um trabalho feito.",597],["Assinala esterilidade na mulher.",597],["Assinala perda de um filho por falta de controle nos maus sentimentos.",597]],"care":[["Não deve meter as mãos em nada obscuro.",598]],"stories":[["Foi por este caminho que Olofin deu a Xangô reinado sobre o céu e a terra.",597]],"curiosities":[]},"ire":{"p":183,"text":"o milagre e as revelações conduzem a uma transformação interior e à descoberta da identidade."},"ibi":{"p":183,"text":"as falsas expectativas com o mundo espiritual e a espera passiva pela ajuda externa e o milagre não satisfazem as expectativas, conduzindo a crises de identidade ou à estagnação."}},"15:3":{"alias":"OFUNDI","page":599,"phrase":"Ofundi adifafun eri etú komobá. Ofundi oso to akukó, eiyelé, leri etú elebó.","sections":{"representation":[["Este Odu é filho de Ofun e Odi.",599],["Este Odu não se marca no opon porque representa a sujeira do anus.",599]],"native":[["Dizem que o Awo deste signo é pirata.",599]],"reading":[],"care":[],"stories":[["Neste caminho a mulher rouba.",599]],"curiosities":[]},"ire":{"p":190,"text":"o milagre, a conscientização e a revelação conduzem à renovação."},"ibi":{"p":190,"text":"a falta de revelação e de conscientização impede a renovação ou provoca sua má sucessão."}},"15:4":{"alias":"OFUNBIROSO","page":601,"phrase":"Ofunroso Ifá lodafun Obatalá, Osun, Iyemanjá. Maferefun Ofunroso soju exé gogoro Ogue Bara lodafun Olofin. Leri etú meji elebó.","sections":{"representation":[["Este Odu é filho de Ofun e Irosun.",601]],"native":[],"reading":[["Assinala perda de posição e de tudo o mais.",601],["Assinala angustia, penas, sofrimento silencioso.",601]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":197,"text":"o milagre, a conscientização e as revelações viabilizam a realização dos potenciais, através da conexão familiar e do reconhecimento do destino pessoal."},"ibi":{"p":197,"text":"os objetivos pessoais da vida fracassam. A frustração e uma suposta falta de sentido geram dúvidas, descrença e resistência à condução espiritual e à família."}},"15:5":{"alias":"OFUNWÓNRIN","page":603,"phrase":"Awo Kekeré ofá pepenin eianmi dé dé adifafun Obatalá umbatibini eiyelé lebó, ori, eyiele, akukó lebo. Kaferefun Exú.","sections":{"representation":[["Este Odu é filho de Ofun e Owónrin.",603]],"native":[["Quando morre um Awo deste signo, prepara-se água de ekó durante nove dias seguidos e seus familiares de sangue e de religião bebem desta água todos os dias.",603]],"reading":[["Assinala morte por acidente.",603]],"care":[["A pessoa não deve tomar Sol.",604],["Deve evitar, também, tomar ventos fortes, o que lhe causa dores de cabeça.",604]],"stories":[],"curiosities":[]},"ire":{"p":204,"text":"uma revelação conduz à reorientação interior."},"ibi":{"p":204,"text":"o desvio do destino e a revelação de um fracasso conduzem a uma profunda crise interior."}},"15:6":{"alias":"OFUNBARA","page":605,"phrase":"Ofunbara Ofun Sunsun olomori.","sections":{"representation":[["Este Odu é filho de Ofun e Obara.",605],["Este é o caminho da girafa.",605]],"native":[["Os filhos deste Odu não podem entregar seus corações à ninguém, caso contrário serão destruídos.",605]],"reading":[],"care":[],"stories":[],"curiosities":[]},"ire":{"p":210,"text":"o milagre e a revelação das verdades conduzem à transformação interior e à superação do ego."},"ibi":{"p":210,"text":"a revelação do fracasso conduz à autodestruição, fomentando o egoísmo e o narcisismo."}},"15:7":{"alias":"OFUNKANRAN","page":607,"phrase":"Ofiara koja abo miloso adifafun osoko laju oma aboiyo lebó eiyelé eyelebó kaferefun Obatalá ati Exú.","sections":{"representation":[["Este Odu é filho de Ofun e Okanran.",607],["Este é o Odu do rejeitado social.",607]],"native":[["As pessoas deste Odu têm que colocar azeviche na carga de seus Elegbaras.",607]],"reading":[],"care":[],"stories":[],"curiosities":[]},"ire":{"p":215,"text":"o milagre e as revelações conduzem a novas oportunidades e relações."},"ibi":{"p":215,"text":"a revelação da falta de sentido de relações e projetos conduz ao isolamento e ao retiro."}},"15:8":{"alias":"OFUNGUNDÁ","page":608,"phrase":"Ofun Fundá Ifá tinxomó Ikin unsoro bogbo kaleno Orixá umpé gbile tiyé Keviosô okutá edun ará okpá afafá Okoji Afá olé tokosi. Okpele Ifá adifafun Afafá kaferefun Ifá de.","sections":{"representation":[["Este Odu é filho de Ofun e Ogunda.",608]],"native":[["Os filhos deste Odu têm que ter um ajapá em suas casas.",608],["A pessoa deste Odu tem que ir às margens de um rio e ali pegar um otá e um pouco d'água e montar com isto e uma moeda de prata, uma segurança para toda a sua vida.",608]],"reading":[],"care":[],"stories":[["Foi neste caminho que Olodumare riscou, sobre uma pedra inteiramente branca, os dezesseis Odu Meji, entregando-os a Orunmilá e ensinando-lhe os seus segredos.",608]],"curiosities":[]},"ire":{"p":221,"text":"o milagre e a revelação de verdades favorecem a realização de convicções interiores."},"ibi":{"p":221,"text":"ilusões e a revelação do fracasso consomem a energia necessária para futuras disputas ou conduzem à sede cega de destruição."}},"15:9":{"alias":"OFUNSÁ","page":610,"phrase":"Ofunsá Alé nixé Omó Ikú oyina omó Orunmilá ale oyina lolé asuworun oyina lorubó.","sections":{"representation":[["Este Odu é filho de Ofun e Osá.",610]],"native":[["Os filhos deste Odu, quando nascem, trazem o cordão umbilical enrolado em seus pescoços.",610]],"reading":[["Assinala cirrose hepática.",610]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":226,"text":"revelações transformam o mundo exterior."},"ibi":{"p":226,"text":"utopias e ilusões sucumbem. IKA Ika representa a força interior e o poder da palavra."}},"15:10":{"alias":"OFUNKÁ","page":611,"phrase":"Fuká josi mono kegbe efuxé kayegbo.","sections":{"representation":[["Este Odu é filho de Ofun e Iká.",611]],"native":[],"reading":[["Quando este Odu surge numa consulta, o Awo tem que primeiro, fazer ebó para a esquina de sua casa e depois para o cliente.",611]],"care":[["Esta situação tem que ser revertida e a pessoa não deve permitir que ninguém mais se aproveite dela.",611]],"stories":[["Neste caminho os inimigos de Orunmilá tentaram prejudicá-lo com epô.",611]],"curiosities":[]},"ire":{"p":230,"text":"revelações podem estimular a força interior."},"ibi":{"p":231,"text":"o fracasso dos objetivos da vida e das grandes ilusões conduz ao colapso interior."}},"15:11":{"alias":"OFUNTURUKPON","page":613,"phrase":"Mojeto te mo mo tente mana ajoro unfó ke adifafun fejé tinxomá oro lebó eiye, oro eiyelé, etú lebó.","sections":{"representation":[["Este Odu é filho de Ofun e Oturukpon.",613],["Este é o caminho dos atentados.",613]],"native":[],"reading":[["Assinala falta de compreensão e de união.",613],["Assinala fraqueza sexual no homem.",613],["Indica traição no grupo religioso.",613]],"care":[],"stories":[],"curiosities":[]},"ire":{"p":235,"text":"revelações e o objetivo alcançado repercutem positivamente na saúde e no crescimento de projetos."},"ibi":{"p":235,"text":"o colapso de utopias e o fracasso dos objetivos traçados prejudicam a saúde e conduzem a mais retrocessos."}},"15:12":{"alias":"OFUNTUWÁ","page":615,"phrase":"Boju oba ponibio oku nibide adifafun alapani akukó, iguí langui, aunko alejo lebó.","sections":{"representation":[["É filho de Ofun e de Otura.",615]],"native":[],"reading":[],"care":[],"stories":[],"curiosities":[]},"ire":{"p":239,"text":"a revelação e o milagre conduzem a visões e ativam o poder de criação."},"ibi":{"p":239,"text":"a quebra de utopias e o fracasso de objetivos da vida conduzem a ilusões e ao autoengano."}},"15:13":{"alias":"OFUNRETE","page":616,"phrase":"Ofunbile nene xubo badeyá apolo abi nhankí adifafun laure umbatinló balé nifá akukó lebó. Abiyé adifafun Aminisi, ekodidé, eiyelé lebó.","sections":{"representation":[["Este Odu é filho de Ofun e de Irete.",616],["Trata-se de uma cabeça muito poderosa, maior do que a do adivinho que, antes de fazer-lhe qualquer coisa, tem que se fazer ebó para não sucumbir.",616]],"native":[["O Awo deste signo tem que relacionar-se com os demais para não ser totalmente ignorado.",616],["Quando o Awo deste Odu tem que assentar algum Orixá, quer seja para outro Awo, quer seja para qualquer pessoa, tem que, antes, tomar borí, oferecendo á sua cabeça obí omi tutu e depois etú meji ou eiyelé meji, de acordo com o que for determinado pelo jogo.",616]],"reading":[["Assinala epilepsia, principalmente quando a pessoa dorme.",616],["Quando este Odu surge numa consulta para um cliente, determina que a pessoa tem que fazer Santo ou Ifá (conforme for o caso).",616]],"care":[["Não deve olhar para trás quando estiver caminhando pela rua.",616]],"stories":[],"curiosities":[]},"ire":{"p":243,"text":"revelações estimulam a determinação, a ação e a orientação."},"ibi":{"p":243,"text":"a quebra de utopias conduz à teimosia e ao fanatismo ou à passividade e à resignação."}},"15:14":{"alias":"OFUNXE","page":618,"phrase":"Ofunxe adifafun Iyá, adifafun Orunmilá, adifafun Obatalá, adifafun Oxun okoxe loko akeji alaké lorubó.","sections":{"representation":[["Este Odu é filho de Ofun e de Oxe.",618],["Este signo criou e ensinou os homens a usarem roupas.",618]],"native":[],"reading":[["Assinala inveja e perda de memória.",618]],"care":[["Já está suficientemente claro que, seguindo as orientações contidas no tratado do seu Odu pessoal, o ser humano poderá prosseguir em sua vida com total segurança, evitando os percalços ocasionados pela quebra de tabus, que nos levam a situações inusitadas e indesejáveis de desconforto e infelicidade.",620],["Cabe-nos portanto a obrigação de, desfazendo os mitos, derrubando os falsos tabus, colocar à disposição dos interessados a verdade sobre Ifá e seu Sistema Oracular.",620]],"stories":[["Foi por este caminho que Axukpá, a Lua, foi à casa de Obatalá.",618]],"curiosities":[]},"ire":{"p":246,"text":"a revelação conduz à plenitude e à conexão espiritual."},"ibi":{"p":246,"text":"a quebra de utopias e ilusões conduz ao vazio, a depressões, à ganância e ao egoísmo."}}};